//  MarsL - a building and strategy game on the Red Planet
//  Needs: Node.js 22.13 or newer (uses the built-in SQLite database)
//  Only extra package: express   ->   npm install express
// =====================================================================

const express = require("express");
const runtimeTiming = require("./lib/runtime-timing")();
const nextRouteTime = require("./game/trade-schedule");
const crypto = require("crypto");
const path = require("path");
