// ---------- Beginner protection ----------
// New commanders can't be attacked, raided or spied on while they learn
// the game. It ends after PROTECTION_HOURS real hours, or as soon as all
// their colonies together have PROTECTION_POINTS points - whatever comes
// first. Attacking, raiding or spying on another player ends it at once
// (monster camps are fine). Protected players can't be attacked, so they
// also can't hide troops behind it forever.
// At normal speed it lasts 6 days; faster servers shorten it (a player grows
// faster there), but only with the square root of the speed. The owner can
// set both numbers by hand on the admin page.
const PROTECTION_BASE_HOURS = 144;
const PROTECTION_BASE_POINTS = 120;
function protectionAuto() {
  const f = Math.sqrt(Math.max(1, PRODUCTION_SPEED));
  return { hours: Math.max(12, Math.round(PROTECTION_BASE_HOURS / f)), points: Math.round(PROTECTION_BASE_POINTS * f) };
}
// Later landers start next to far bigger colonies, so the points that end
// protection grow with the age of the server, up to twice as many at server day 100.
// Players can also extend their protection once by half of its length
// (see /api/extend-protection). Owner-set numbers are left exactly as set.
const PROT_EXTEND_SHARE = 0.5, PROT_LATE_POINTS_DAY = 100; // the extension is half of the base protection, so it follows the game speed
function serverAgeDays() { try { return Math.max(0, serverClock().day - 1); } catch (e) { return 0; } }
function protectionHours() {
  const own = Number(settingOf("protection_hours", "0"));
  if (own > 0) return own;
  return protectionAuto().hours;
}
function protectionPoints() {
  const own = Number(settingOf("protection_points", "0"));
  if (own > 0) return own;
  return Math.round(protectionAuto().points * (1 + Math.min(1, serverAgeDays() / PROT_LATE_POINTS_DAY)));
}
// Protection waits for a newcomer who is away: if it would run out while the player
// has not come back, it holds (for at most 3 server days) and restarts with a short
// grace the moment they log in. Inactive colonies (bots) don't get this.
function protHoldMs() { return 3 * serverDayMs(); }
function protGraceMs() { return Math.max(5 * 60000, Math.round(6 * 3600000 * dayScale())); }

