const LANDMARKS = LANDMARK_DEFS.map((d) => {
  const p = turnAround(d.site, d.q);
  return Object.assign({}, d, { x: p.x, y: p.y });
});
// The landmarks only APPEAR when the server clock opens them: until then the
// sites look like ordinary mountains and nobody can attack or even find them.
let LM_VISIBLE = false;
for (const l of LANDMARKS) l.key = l.x + "|" + l.y;
function landmarkByKey(key) {
  return LANDMARKS.find((l) => l.key === key) || null;
}
// 1.0.373: a captured relic is carried home. While it sits in a colony its site
// is empty: it looks like a mountain again and nobody can attack the spot.
const LM_AWAY = new Set();
function landmarkAtXY(x, y) {
  const l = LM_VISIBLE ? LANDMARKS.find((q) => q.x === x && q.y === y) || null : null;
  return l && !LM_AWAY.has(l.key) ? l : null;
}
// the three Relic Hunts: each one stronger, and each one reaches further
const RELIC_TIERS = [
  { n: 1, mult: 1, scope: "colony", name: "Relic Hunt I", scopeText: "the colony that holds it" },
  { n: 2, mult: 1.6, scope: "account", name: "Relic Hunt II", scopeText: "every colony of the holder" },
  { n: 3, mult: 2.2, scope: "alliance", name: "Relic Hunt III", scopeText: "the whole alliance of the holder" },
];
// a held relic is kept in the building that sends the expeditions (the Expedition Base, whatever the tribe calls it)
function relicHomeOf() {
  return "outpost";
}
// All features below are defined for ONE quarter (x > 0, y >= 0) and the map
// turns them around the centre, so every quarter has the very same land.
// Olympus Mons and the Tharsis volcanoes, like on the real Mars
const VOLCANOES = [
  { x: 30, y: 26, ring: 2.2 }, // the giant at the edge
  { x: 20, y: 9, ring: 1.2 },
  { x: 24, y: 13, ring: 1 },
  { x: 17, y: 14, ring: 1 },
];
const BASINS = [
  { x: 14, y: 24, r: 2.8 },
  { x: 33, y: 7, r: 2 },
  { x: 7, y: 31, r: 1.7 },
  { x: 8, y: 14, r: 1.2 },
];
const ICE_PATCHES = [
  { x: 34, y: 15, r: 2.4 },
  { x: 16, y: 34, r: 2.2 },
];

function hash3(x, y, seed) {
  let h = Math.imul(x, 374761393) + Math.imul(y, 668265263) + Math.imul(seed, 1442695041);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

// Smooth noise: random values on a coarse grid, blended in between.
// This makes mountain ranges, valleys and dune fields that belong together.
function valueNoise(x, y, scale, seed) {
  const fx = x / scale;
  const fy = y / scale;
  const x0 = Math.floor(fx);
  const y0 = Math.floor(fy);
  const tx = fx - x0;
  const ty = fy - y0;
  const sx = tx * tx * (3 - 2 * tx);
  const sy = ty * ty * (3 - 2 * ty);
  const a = hash3(x0, y0, seed);
  const b = hash3(x0 + 1, y0, seed);
  const c = hash3(x0, y0 + 1, seed);
  const d = hash3(x0 + 1, y0 + 1, seed);
  return a + (b - a) * sx + (c - a) * sy + (a - b - c + d) * sx * sy;
}

// Ridges: thin, long mountain chains instead of round blobs.
// For fairness the mountains are the same in all four quarters of the
// map, just turned around the centre - so every player has the same
// number of monster camps nearby, wherever they land.
function canonical(x, y) {
  let cx = x;
  let cy = y;
  while (!(cx > 0 && cy >= 0) && !(cx === 0 && cy === 0)) {
    const t = cx;
    cx = cy;
    cy = -t;
  }
  return [cx, cy];
}

function ridge(x, y) {
  const [cx, cy] = canonical(x, y);
  const n = 0.65 * valueNoise(cx, cy, 11, 11) + 0.35 * valueNoise(cx, cy, 5, 12);
  return 1 - Math.abs(n - 0.5) * 2;
}

function generateTerrain(x, y) {
  if (Math.abs(x) > MAP_RADIUS || Math.abs(y) > MAP_RADIUS) return "x";
  if (x === 0 && y === 0) return "b";
  if (LANDMARKS.some((l) => l.x === x && l.y === y)) return "m"; // hidden until the landmarks open
  const dist = Math.hypot(x, y);
  if (dist <= SAFE_RADIUS) return hash3(x, y, 5) < 0.25 ? "d" : "p";
  const [cx, cy] = canonical(x, y); // the same spot in the first quarter

  // a frozen rim all around the planet
  const rim = MAP_RADIUS - 1 - Math.floor(valueNoise(cx, cy, 5, 3) * 3);
  if (Math.max(Math.abs(x), Math.abs(y)) >= rim) return "i";
  for (const p of ICE_PATCHES) if (Math.hypot(cx - p.x, cy - p.y) <= p.r) return "i";

  for (const v of VOLCANOES) {
    const vd = Math.hypot(cx - v.x, cy - v.y);
    if (vd < 0.5) return "v";
    if (vd <= v.ring) return "m";
  }
  for (const b of BASINS) {
    if (Math.hypot(cx - b.x, cy - b.y) <= b.r) return "c";
  }

  // Valles Marineris: a long winding canyon; four of them swirl around the middle
  if (cx >= 9 && cx <= 38) {
    const canyonY = 2 + (cx - 9) * 0.65 + 2.2 * Math.sin(cx / 3.2);
    if (Math.abs(cy - canyonY) <= 0.7) return "k";
  }

  if (hash3(cx, cy, 7) < 0.03) return "c";

  // Mountain chains get a bit more common further out (they hold the
  // stronger monster camps), so the middle stays friendly for beginners.
  const out = Math.min(1, (dist - SAFE_RADIUS) / 18);
  const rg = ridge(x, y);
  if (rg > 0.93 - 0.03 * out) return "m";
  if (rg > 0.88 - 0.03 * out && hash3(cx, cy, 9) < 0.5) return "r";

  const sand = 0.6 * valueNoise(cx, cy, 10, 21) + 0.4 * valueNoise(cx, cy, 4, 22);
  if (sand < 0.36) return "d";
  return "p";
}

// Calculate the whole map once. Row 0 is the top (north, highest y).
const MAP_ROWS = [];
for (let y = MAP_RADIUS; y >= -MAP_RADIUS; y--) {
  let row = "";
  for (let x = -MAP_RADIUS; x <= MAP_RADIUS; x++) row += generateTerrain(x, y);
  MAP_ROWS.push(row);
}

// 🗼 The four Aurora Pylons (Project Aurora, the alliance endgame).
// Each stands on the rough ground (mountain, crater, boulders, ice or canyon)
// closest to its spot, so no colony can ever be in the way.
const PYLON_DIST = 26;
const PYLONS = [
  { key: "n", name: "North Pylon", ax: 0, ay: PYLON_DIST },
  { key: "e", name: "East Pylon", ax: PYLON_DIST, ay: 0 },
  { key: "s", name: "South Pylon", ax: 0, ay: -PYLON_DIST },
  { key: "w", name: "West Pylon", ax: -PYLON_DIST, ay: 0 },
];
for (const p of PYLONS) {
  let best = null;
  for (let dy = -6; dy <= 6; dy++) {
    for (let dx = -6; dx <= 6; dx++) {
      const x = p.ax + dx, y = p.ay + dy;
      if (Math.abs(x) > MAP_RADIUS - 1 || Math.abs(y) > MAP_RADIUS - 1) continue;
      if (!"mrcik".includes(MAP_ROWS[MAP_RADIUS - y][x + MAP_RADIUS])) continue;
      if (LANDMARKS.some((l) => Math.abs(l.x - x) <= 1 && Math.abs(l.y - y) <= 1)) continue;
      const d = dx * dx + dy * dy;
      if (!best || d < best.d) best = { x, y, d };
    }
  }
  if (!best) best = { x: p.ax, y: p.ay }; // (never happens on this map)
  p.x = best.x;
  p.y = best.y;
  const row = MAP_ROWS[MAP_RADIUS - p.y];
  MAP_ROWS[MAP_RADIUS - p.y] = row.slice(0, p.x + MAP_RADIUS) + "y" + row.slice(p.x + MAP_RADIUS + 1);
}
// =====================================================================
//  MONSTER CAMPS
//  Placed after the land is made, with a seed (the admin can re-roll it):
//   - every quarter of the map gets exactly the same NUMBER of camps of every
//     tier, and the same mix of camp kinds, so no corner is luckier than another
//   - inside a quarter the spots are random, but never closer than
//     CAMP_SPACING tiles to each other, and at least 3 tiles from landmarks and pylons.
//     District placement uses open and rough land, excluding existing colonies.
// =====================================================================
const CAMP_SPACING = 3;
const CAMPS_PER_QUARTER = [0, 0, 0, 0]; // actual balanced counts, filled by rebuildCamps
const BASE_ROWS = MAP_ROWS.slice(); // the land without camps
let MAP_SEED = 1;
let CAMP_LAYOUT = 2; // 1 = old compact groups (kept on running worlds), 2 = loose, random groups
const CAMP_KIND_AT = {}; // "x|y" -> index of the camp kind of its tier
function mulberry32(a) {
  return function () {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function quarterOf(x, y) {
  return x > 0 && y >= 0 ? 0 : x <= 0 && y > 0 ? 1 : x < 0 && y <= 0 ? 2 : 3;
}
function baseTerrainAt(x, y) {
  if (Math.abs(x) > MAP_RADIUS || Math.abs(y) > MAP_RADIUS) return "x";
  return BASE_ROWS[MAP_RADIUS - y][x + MAP_RADIUS];
}
// (Re)place all camps. taken(x, y) says whether a colony stands there.
function rebuildCamps(seed, taken) {
  MAP_SEED = seed;
  for (const k in CAMP_KIND_AT) delete CAMP_KIND_AT[k];
  const rows = BASE_ROWS.map((r) => r.split(""));
  let placedCount = 0;
  function nearPlacedCamp(p) {
    for (let dy = -2; dy <= 2; dy++) {
      for (let dx = -2; dx <= 2; dx++) {
        if (Object.hasOwn(CAMP_KIND_AT, (p.x + dx) + "|" + (p.y + dy))) return true;
      }
    }
    return false;
  }
  const rand = mulberry32(seed * 7919 + 13);
  // Irregular small groups, rotated for equal count, strength and reward access.
  CAMPS_PER_QUARTER.fill(0);
  const rotate=(x,y,q)=>q===0?{x,y}:q===1?{x:-y,y:x}:q===2?{x:-x,y:-y}:{x:y,y:-x};
  const valid=p=>Math.hypot(p.x,p.y)>SAFE_RADIUS && "pdmrc".includes(baseTerrainAt(p.x,p.y)) &&
    !(taken&&taken(p.x,p.y)) && LANDMARKS.every(l=>Math.hypot(l.x-p.x,l.y-p.y)>=3) && PYLONS.every(l=>Math.hypot(l.x-p.x,l.y-p.y)>=3);
  const anchors=[];
  // Weighted, shuffled bags prevent one group size dominating a generated world.
  const sizes=[];
  // layout 2: more lone camps, loose groups with gaps, never a 2x2 block
  const L2=CAMP_LAYOUT===2;
  for(const [size,count] of (L2?[[1,56],[2,24],[3,13],[4,7]]:[[1,50],[2,27],[3,15],[4,8]])) for(let i=0;i<count;i++)sizes.push(size);
  const shuffleSizes=()=>{for(let i=sizes.length-1;i>0;i--){const j=Math.floor(rand()*(i+1));[sizes[i],sizes[j]]=[sizes[j],sizes[i]];}};
  shuffleSizes();let sizeIndex=0;
  const candidates=[];
  for(let y=2;y<MAP_RADIUS-2;y++)for(let x=2;x<MAP_RADIUS-2;x++)candidates.push({x,y,order:rand(),gap:L2?3.5+rand()*5.5:5+rand()*3});
  candidates.sort((a,b)=>a.order-b.order);
  for(const center of candidates){
    if(anchors.some(p=>Math.hypot(p.x-center.x,p.y-center.y)<Math.max(p.gap,center.gap)))continue;
    const group=[{x:center.x,y:center.y}];
    const size=sizes[sizeIndex];
    for(let tries=0;tries<30&&group.length<size;tries++){
      const p=group[Math.floor(rand()*group.length)];
      let v;
      if(L2){
        // any spot up to two tiles away, also diagonal or with a gap in between
        const dx=Math.floor(rand()*5)-2,dy=Math.floor(rand()*5)-2;
        if(!dx&&!dy)continue;
        v={x:p.x+dx,y:p.y+dy};
        if(v.x<1||v.y<1||Math.hypot(v.x-center.x,v.y-center.y)>3||group.some(w=>w.x===v.x&&w.y===v.y))continue;
        const has=(x,y)=>(x===v.x&&y===v.y)||group.some(w=>w.x===x&&w.y===y);
        let block=false;
        for(const [ox,oy] of [[0,0],[-1,0],[0,-1],[-1,-1]]){const x=v.x+ox,y=v.y+oy;if(has(x,y)&&has(x+1,y)&&has(x,y+1)&&has(x+1,y+1))block=true;}
        if(block)continue;
        // no three in a straight touching row either
        if(group.filter(w=>Math.abs(w.x-v.x)<=1&&Math.abs(w.y-v.y)<=1).length>1)continue;
      }else{
        const dirs=[[1,0],[-1,0],[0,1],[0,-1]],d=dirs[Math.floor(rand()*4)];
        v={x:p.x+d[0],y:p.y+d[1]};
        if(v.x<1||v.y<1||Math.hypot(v.x-center.x,v.y-center.y)>2||group.some(w=>w.x===v.x&&w.y===v.y))continue;
      }
      group.push(v);
    }
    if(group.length!==size)continue;
    const orbit=[0,1,2,3].map(q=>group.map(p=>rotate(p.x,p.y,q)));
    const all=orbit.flat();
    if(!all.every(valid))continue;
    if(all.some(nearPlacedCamp))continue;
    if(orbit.some((g,i)=>g.some(p=>orbit.slice(0,i).flat().some(w=>Math.hypot(w.x-p.x,w.y-p.y)<3))))continue;
    anchors.push(center);
    sizeIndex++;if(sizeIndex===sizes.length){sizeIndex=0;shuffleSizes();}
    group.forEach(p=>{
      const tier=campTier(p.x,p.y),kind=CAMPS_PER_QUARTER[tier]++ % CAMP_TIERS[tier].kinds.length;
      for(let q=0;q<4;q++){
        const spot=rotate(p.x,p.y,q);placedCount++;
        rows[MAP_RADIUS-spot.y][spot.x+MAP_RADIUS]="n";CAMP_KIND_AT[spot.x+"|"+spot.y]=kind;
      }
    });
  }
  if (LM_VISIBLE) for (const l of LANDMARKS) rows[MAP_RADIUS - l.y][l.x + MAP_RADIUS] = "l";
  for (let i = 0; i < rows.length; i++) MAP_ROWS[i] = rows[i].join("");
  return placedCount;
}
rebuildCamps(1);
// The landmarks appear on the map (or vanish from it) together with the clock event
function setLandmarksVisible(on) {
  LM_VISIBLE = !!on;
  if (typeof db !== "undefined" && db.prepare("SELECT name FROM sqlite_master WHERE name = 'landmarks'").get()) {
    LM_AWAY.clear();
    for (const r of db.prepare("SELECT key FROM landmarks WHERE holder_id IS NOT NULL").all()) LM_AWAY.add(r.key);
  }
  for (const l of LANDMARKS) {
    const row = MAP_ROWS[MAP_RADIUS - l.y];
    const tile = LM_VISIBLE && !LM_AWAY.has(l.key) ? "l" : BASE_ROWS[MAP_RADIUS - l.y][l.x + MAP_RADIUS];
    MAP_ROWS[MAP_RADIUS - l.y] = row.slice(0, l.x + MAP_RADIUS) + tile + row.slice(l.x + MAP_RADIUS + 1);
  }
}
function pylonAtXY(x, y) {
  return PYLONS.find((p) => p.x === x && p.y === y) || null;
}

function terrainAt(x, y) {
  if (Math.abs(x) > MAP_RADIUS || Math.abs(y) > MAP_RADIUS) return "x";
  return MAP_ROWS[MAP_RADIUS - y][x + MAP_RADIUS];
}

function campTier(x, y) {
  const dist = Math.hypot(x, y);
  for (let i = 0; i < CAMP_TIERS.length; i++) if (dist <= CAMP_TIERS[i].maxDist) return i;
  return CAMP_TIERS.length - 1;
}

// Which kind of camp lives on this mountain (always the same)
var titanReady = false;
var titanCache = null;
var TITAN_KIND = { name: "Dust Titan", icon: "🌪️", units: {}, treasure: { wood: 0, stone: 0, metal: 0, food: 0 } };
function campKind(x, y) {
  if (titanAt(x, y)) return TITAN_KIND;
  const kinds = CAMP_TIERS[campTier(x, y)].kinds;
  const at = CAMP_KIND_AT[x + "|" + y];
  if (at !== undefined) return kinds[at];
  return kinds[Math.min(kinds.length - 1, Math.floor(hash3(x, y, 91) * kinds.length))];
}

// The full-strength monster camp of a mountain tile (always the same)
function freshCamp(x, y) {
  const kind = campKind(x, y);
  const troops = {};
  let seed = 31;
  for (const key in kind.units) {
    const [min, max] = kind.units[key];
    troops[key] = Math.max(1, min + Math.floor(hash3(x, y, seed++ + MAP_SEED * 101) * (max - min + 1)));
  }
  const treasure = {};
  for (const r of RESOURCES) treasure[r] = Math.round((kind.treasure[r] || 0) * campLootScale());
  return { troops, treasure };
}

// =====================================================================
//  DATABASE  (everything is stored in "marsl.db" next to this script)
//  Players (users) can own several colonies. Every colony has its own id.
//  Troop movements go from colony to colony; reports and statistics
//  belong to players.
// =====================================================================
require("fs").mkdirSync(DATA_DIR, { recursive: true });
const db = new DatabaseSync(path.join(DATA_DIR, "marsl.db"));
db.exec("PRAGMA busy_timeout = 4000");
// Compiling SQL costs more than running it, and the colony poll repeats the same few hundred statements
// every few seconds per player. Keep each compiled statement; statements built from changing text
// (values pasted into the SQL) fall off the end of the cache instead of filling it.
const prepareStatement = db.prepare.bind(db);
const statementCache = new Map();
db.prepare = function (sql) {
  let statement = statementCache.get(sql);
  if (!statement) {
    statement = prepareStatement(sql);
    if (statementCache.size < 1500) statementCache.set(sql, statement);
  }
  return statement;
};
 // wait a moment instead of failing when a backup or tool holds the file
db.exec("CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)");
// A database belongs to one server. Two sites using the same folder (or the same
// DATA_DIR) would be one world under two addresses, so a server refuses to start
// on a database that was made for another one.
{
  const mine = process.env.SERVER_ID || "open-test";
  const row = db.prepare("SELECT value FROM settings WHERE key = 'server_id'").get();
  if (!row) db.prepare("INSERT INTO settings (key, value) VALUES ('server_id', ?)").run(mine);
  else if (row.value !== mine) {
    console.error("\n  STOP: this database (" + path.join(DATA_DIR, "marsl.db") + ") belongs to the server '" + row.value + "', but this server is '" + mine + "'.");
    console.error("  Every server needs its own folder (or its own DATA_DIR). Give this site a folder of its own and start again.\n");
    process.exit(1);
  }
}

// ---------- the invite code new players need ----------
// INVITE_CODE=off -> open registration. INVITE_CODE=xyz -> that code.
// Otherwise a random code is made once and kept in the database.
function makeInviteCode() {
  const abc = "ABCDEFGHJKMNPQRSTUVWXYZ23456789"; // no 0/O or 1/I mix-ups
  let code = "MARS-";
  for (let i = 0; i < 6; i++) code += abc[crypto.randomInt(abc.length)];
  return code;
}
let INVITE_CODE = "";
if (INVITE_SETTING.toLowerCase() === "off") {
  INVITE_CODE = "";
} else if (INVITE_SETTING) {
  INVITE_CODE = INVITE_SETTING;
} else {
  const row = db.prepare("SELECT value FROM settings WHERE key = 'invite'").get();
  INVITE_CODE = row ? row.value : makeInviteCode();
  if (!row) db.prepare("INSERT INTO settings (key, value) VALUES ('invite', ?)").run(INVITE_CODE);
}

