// =====================================================================
//  API: REPORTS
// =====================================================================
app.get('/api/replay/:reportId', requireLogin, (req, res) => {
  const reportId = parseInt(req.params.reportId, 10);
  if (!reportId) return res.status(400).json({ error: 'Invalid report ID' });

  const row = db.prepare(
    'SELECT id, created_at, title, icon, data, seen FROM reports WHERE user_id = ? AND id = ?'
  ).get(req.user.id, reportId);

  if (!row) return res.status(404).json({ error: 'Report not found' });

  let data;
  try { data = JSON.parse(row.data); } catch (e) { data = {}; }

  // Mark as seen when opened for replay
  if (!row.seen) {
    db.prepare('UPDATE reports SET seen = 1 WHERE user_id = ? AND id = ?').run(req.user.id, reportId);
  }

  res.json({
    id: row.id,
    at: row.created_at,
    title: row.title,
    icon: row.icon,
    seen: true,
    data,
  });
});

// Get player onboarding / first-day progress
app.get('/api/onboarding', requireLogin, (req, res) => {
  const st = firstDayState(req.user.id);
  const colony = db.prepare('SELECT name, x, y, tribe FROM colonies WHERE user_id = ? ORDER BY id LIMIT 1').get(req.user.id);

  if (!st) return res.json({ active: false });

  const onb = st.f.onb || {};
  const stepIndex = onb.i || 0;
  const totalSteps = ONB_STEPS ? ONB_STEPS.length : 0;
  const progress = totalSteps > 0 ? Math.round((stepIndex / totalSteps) * 100) : 0;

  res.json({
    active: onbActive(req.user.id, st),
    completed: !!onb.done,
    skipped: !!onb.off,
    stepIndex,
    totalSteps,
    progress,
    startedAt: onb.at || null,
    completedAt: onb.done || null,
    kitRemaining: st.f.kit || 0,
    hasLander: !!st.f.lander,
    hasScorp: !!st.f.scorp,
    colony: colony ? { name: colony.name, x: colony.x, y: colony.y, tribe: colony.tribe } : null,
  });
});

// Get player summary stats and progress
app.get('/api/player/summary', requireLogin, (req, res) => {
  const userId = req.user.id;

  // Basic user info
  const user = db.prepare('SELECT username, created_at, last_seen FROM users WHERE id = ?').get(userId);
  if (!user) return res.status(404).json({ error: 'User not found' });

  // Colony count and total points
  const colonies = db.prepare('SELECT id, name, x, y, tribe, state FROM colonies WHERE user_id = ?').all(userId);
  let totalPoints = 0;
  for (const c of colonies) {
    try { totalPoints += colonyPoints(fixState(JSON.parse(c.state))); } catch (e) {}
  }

  // Battle stats
  const stats = db.prepare('SELECT * FROM stats WHERE user_id = ?').get(userId) || {};

  // Report counts
  const reportCounts = db.prepare(
    'SELECT COUNT(*) as total, SUM(seen) as seen FROM reports WHERE user_id = ?'
  ).get(userId);

  // Movement counts
  const movements = db.prepare(
    'SELECT mission, COUNT(*) as n FROM movements WHERE attacker_id IN (SELECT id FROM colonies WHERE user_id = ?) GROUP BY mission'
  ).all(userId);
  const movementSummary = {};
  for (const m of movements) movementSummary[m.mission] = m.n;

  // Alliance info
  const alliance = db.prepare(
    'SELECT a.id, a.name, a.tag FROM alliances a JOIN alliance_members am ON a.id = am.alliance_id WHERE am.user_id = ?'
  ).get(userId);

  // Badges
  const badges = db.prepare('SELECT key, icon, title, earned_at FROM badges WHERE user_id = ? AND shown = 1 ORDER BY earned_at DESC LIMIT 10').all(userId);

  res.json({
    username: user.username,
    createdAt: user.created_at,
    lastSeen: user.last_seen,
    colonies: colonies.map(c => ({ id: c.id, name: c.name, x: c.x, y: c.y, tribe: c.tribe })),
    totalPoints,
    stats: {
      atkKills: stats.atk_kills || 0,
      defKills: stats.def_kills || 0,
      npcKills: stats.npc_kills || 0,
      lost: stats.lost || 0,
      loot: stats.loot || 0,
      wins: stats.wins || 0,
      battles: stats.battles || 0,
    },
    reports: { total: reportCounts.total || 0, unread: (reportCounts.total || 0) - (reportCounts.seen || 0) },
    movements: movementSummary,
    alliance: alliance ? { id: alliance.id, name: alliance.name, tag: alliance.tag } : null,
    badges: badges || [],
  });
});

app.get("/api/reports", requireLogin, (req, res) => {
  processMovements(Date.now());
  // a cheap fingerprint: the page asks every few seconds, and most of the time nothing changed
  const fp = db.prepare("SELECT COUNT(*) AS n, MAX(id) AS mx, SUM(seen) AS s FROM reports WHERE user_id = ?").get(req.user.id);
  const fq0 = db.prepare("SELECT farm_quiet, farm_hidden FROM users WHERE id = ?").get(req.user.id) || {};
  const v = [fp.n, fp.mx || 0, fp.s || 0, fq0.farm_quiet ? 1 : 0, fq0.farm_hidden || 0].join(".");
  if (req.query.v && String(req.query.v) === v) return res.json({ same: true, v });
  const rows = db
    .prepare("SELECT id, created_at, title, icon, data, seen FROM reports WHERE user_id = ? ORDER BY id DESC")
    .all(req.user.id);
  const fq = db.prepare("SELECT farm_quiet, farm_hidden FROM users WHERE id = ?").get(req.user.id) || {};
  res.json({
    v,
    now: Date.now(),
    farmQuiet: !!fq.farm_quiet,
    farmHidden: fq.farm_hidden || 0,
    reports: rows.map((r) => ({ id: r.id, at: r.created_at, title: r.title, icon: r.icon, seen: !!r.seen, data: JSON.parse(r.data) })),
  });
});

// read: one report (opened) or, with no id, all of them ("mark all as read")
// unread: true puts one report back to unread
app.post("/api/reports/seen", requireLogin, (req, res) => {
  const id = parseInt((req.body || {}).id, 10);
  if (id && (req.body || {}).unread) db.prepare("UPDATE reports SET seen = 0 WHERE user_id = ? AND id = ?").run(req.user.id, id);
  else if (id) db.prepare("UPDATE reports SET seen = 1 WHERE user_id = ? AND id = ?").run(req.user.id, id);
  else db.prepare("UPDATE reports SET seen = 1 WHERE user_id = ?").run(req.user.id);
  res.json({ ok: true });
});

app.post("/api/reports/clear", requireLogin, (req, res) => {
  db.prepare("DELETE FROM reports WHERE user_id = ?").run(req.user.id);
  res.json({ ok: true });
});

// =====================================================================
//  API: RANKING (per player: all their colonies together)
// =====================================================================
app.get("/api/ranking", requireLogin, (req, res) => {
  const z = zoneRow();
  const kingUser = zoneHolderUser(z);
  const now = Date.now();
  const users = db
    .prepare(
      `SELECT users.id, users.username, stats.atk_kills, stats.def_kills, stats.npc_kills, stats.lost, stats.loot,
              stats.wins, stats.battles, stats.crown_ms
       FROM users LEFT JOIN stats ON stats.user_id = users.id`
    )
    .all();
  const players = [];
  for (const u of users) {
    const cols = coloniesOf(u.id);
    if (!cols.length) continue;
    let crownMs = u.crown_ms || 0;
    if (kingUser === u.id) crownMs += now - z.since;
    const first = cols[0];
    players.push({
      id: u.id,
      player: u.username,
    npc: BOT_IDS.has(u.id),
    npcRole: BOT_IDS.has(u.id) && cols[0] ? (cols[0].state.botStyle || "builder") : null,
      colony: first.name,
      colonies: cols.length,
      tribeIcon: tribeOf(first.tribe).icon,
      x: first.x,
      y: first.y,
      points: cols.reduce((n, c) => n + colonyPoints(c.state), 0),
      atk: u.atk_kills || 0,
      def: u.def_kills || 0,
      npc: u.npc_kills || 0,
      lost: u.lost || 0,
      loot: u.loot || 0,
      wins: u.wins || 0,
      battles: u.battles || 0,
      crown: Math.floor(crownMs / 60000), // minutes as ruler
      king: kingUser === u.id,
      me: u.id === req.user.id,
      tag: (allianceOf(u.id) || {}).tag || null,
    });
  }
  res.json({ players, weekly: weeklyRanking(req.user.id, now), league: leagueView(req.user.id, now) });
});

// The best players of this week (and the winners of last week)
function weeklyRanking(myId, now) {
  const start = weekStart(now);
  const lastStart = weekStart(start - 1);
  const top = (key, from, to, limit) =>
    db
      .prepare(
        `SELECT users.id, users.username, SUM(stats_log.n) AS total
         FROM stats_log JOIN users ON users.id = stats_log.user_id
         WHERE stats_log.key = ? AND stats_log.at >= ? AND stats_log.at < ?
         GROUP BY users.id ORDER BY total DESC, users.username LIMIT ?`
      )
      .all(key, from, to, limit)
      .map((r) => ({ player: r.username, value: r.total, me: r.id === myId }));
  const lists = {};
  const lastWinners = {};
  for (const key of WEEKLY_KEYS) {
    lists[key] = top(key, start, now + 1, 5);
    const w = top(key, lastStart, start, 1)[0];
    lastWinners[key] = w || null;
  }
  return { since: start, ends: start + 7 * 86400000, lists, last: lastWinners };
}

