// A 25 x 25 piece of the map around (x|y), with colonies, landmarks and camps
app.get("/api/map", requireLogin, (req, res) => {
  const now = Date.now();
  processMovements(now);
  const me = loadColony(req.colonyId);
  const clamp = (v) => Math.max(-MAP_RADIUS, Math.min(MAP_RADIUS, v));
  let cx = parseInt(req.query.x, 10);
  let cy = parseInt(req.query.y, 10);
  cx = clamp(Number.isNaN(cx) ? me.x : cx);
  cy = clamp(Number.isNaN(cy) ? me.y : cy);
  const rq = parseInt(req.query.r, 10);
  const R = Number.isNaN(rq) ? CHUNK_RADIUS : Math.max(CHUNK_RADIUS, Math.min(CHUNK_RADIUS_MAX, rq));

  const rows = [];
  const camps = [];
  const taken = new Set(
    db
      .prepare("SELECT x, y FROM colonies WHERE x BETWEEN ? AND ? AND y BETWEEN ? AND ?")
      .all(cx - R, cx + R, cy - R, cy + R)
      .map((c) => c.x + "|" + c.y)
  );
  const mixes = [];
  for (let y = cy + R; y >= cy - R; y--) {
    let row = "";
    let mixRow = "";
    for (let x = cx - R; x <= cx + R; x++) {
      const t = terrainAt(x, y);
      row += t;
      if (t === "n" && !taken.has(x + "|" + y)) camps.push(campInfo(x, y, now));
      // field mix of free land (index into FIELD_MIXES), "." = can't settle here
      mixRow += !taken.has(x + "|" + y) && TERRAIN[t].buildable && !(Math.abs(x) <= 1 && Math.abs(y) <= 1) ? mixIndexAt(x, y) : ".";
    }
    rows.push(row);
    mixes.push(mixRow);
  }

  // Where are my troops heading? A little sign on the map shows what kind of trip it is:
  // "⚔️" attack, 💰 raid, "🔍" spies, 🐪 merchants, 🛡️ support, 🏳️ settlers (the most warlike one wins)
  const myIds = colonyIdsOf(req.user.id);
  const MOVE_RANK = { attack: 6, raid: 5, scout: 4, trade: 3, reinforce: 2, settle: 1 };
  const targetMap = new Map();
  for (const t of db
    .prepare(
      `SELECT DISTINCT COALESCE(movements.target_x, colonies.x) AS x, COALESCE(movements.target_y, colonies.y) AS y, movements.mission AS mission
       FROM movements LEFT JOIN colonies ON colonies.id = movements.target_id
       WHERE attacker_id IN (` + myIds.map(() => "?").join(",") + `) AND phase = 'out'`
    )
    .all(...myIds)) {
    const key = t.x + "|" + t.y;
    const kind = MOVE_RANK[t.mission] ? t.mission : "attack";
    if (!targetMap.has(key) || MOVE_RANK[kind] > MOVE_RANK[targetMap.get(key)]) targetMap.set(key, kind);
  }
  const targeted = { has: (k) => targetMap.get(k) || false };

  // players under beginner protection get a 🛡️ on the map
  const protectedUsers = new Set(
    db.prepare("SELECT id FROM users WHERE protected_until > ? OR (protected_until > ? AND bot = 0 AND prot_grace != protected_until AND last_seen < protected_until) OR vac LIKE '%\"from\":%' OR vac LIKE '%\"shield\":%'").all(now, now - protHoldMs()).map((u) => u.id).filter((id) => protectionOf(id, now).active)
  );

  const diplo = diploRelations(req.user.id, now);
  const colonies = db
    .prepare(
      `SELECT colonies.id, colonies.user_id, colonies.name, colonies.x, colonies.y, colonies.state, colonies.tribe, users.username
       FROM colonies JOIN users ON users.id = colonies.user_id
       WHERE colonies.x BETWEEN ? AND ? AND colonies.y BETWEEN ? AND ?`
    )
    .all(cx - R, cx + R, cy - R, cy + R)
    .map((r) => {
      const tribe = tribeOf(r.tribe);
      return {
        id: r.id,
        x: r.x,
        y: r.y,
        name: r.name,
        owner: r.username,
        points: colonyPoints(fixState(JSON.parse(r.state))),
        mine: r.user_id === req.user.id,
        protected: protectedUsers.has(r.user_id),
        vac: protectedUsers.has(r.user_id) && vacationOf(r.user_id, now).on,
        active: r.id === req.colonyId,
        tribe: tribe.name,
        tribeKey: Object.keys(TRIBES).find((k) => TRIBES[k] === tribe) || "human",
        tribeIcon: tribe.icon,
        home: tribe.home,
        color: tribe.color,
        targeted: targeted.has(r.x + "|" + r.y),
        tag: (allianceOf(r.user_id) || {}).tag || null,
        ally: areAllies(r.user_id, req.user.id),
        rel: diploRelOf(diplo, r.user_id),
      };
    });
  for (const c of camps) c.targeted = targeted.has(c.x + "|" + c.y);

  res.json({
    me: { x: me.x, y: me.y },
    center: { x: cx, y: cy },
    origin: { x: cx - R, y: cy + R },
    size: 2 * R + 1,
    mapRadius: MAP_RADIUS,
    rows,
    mixes,
    caravans: db.prepare(`SELECT m.depart_at,m.arrive_at,m.return_at,m.phase,c.x,c.y,m.target_x,m.target_y FROM movements m JOIN colonies c ON c.id=m.attacker_id JOIN users u ON u.id=c.user_id WHERE u.bot=1 AND m.mission='trade'`).all().map(m=>{
      const back=m.phase==='back',start=back?m.arrive_at:m.depart_at,end=back?m.return_at:m.arrive_at;
      const t=Math.max(0,Math.min(1,(now-start)/Math.max(1,end-start))),f=back?1-t:t;
      return {x:Math.round(m.x+(m.target_x-m.x)*f),y:Math.round(m.y+(m.target_y-m.y)*f)};
    }).filter(p=>Math.abs(p.x-cx)<=R&&Math.abs(p.y-cy)<=R),
    fieldMixes: FIELD_MIXES.map((m) => ({ key: m.key, name: m.name, icon: m.icon, counts: m.counts })),
    colonies,
    camps,
    meteors: meteorsIn(cx - R, cx + R, cy - R, cy + R, now).concat([landerTile(req.user.id, cx - R, cx + R, cy - R, cy + R)].filter(Boolean)).map((m) => Object.assign(m, { targeted: targeted.has(m.x + "|" + m.y) })),
    landmarks: (landmarksOpen() ? LANDMARKS : []).filter((l) => !LM_AWAY.has(l.key) && Math.abs(l.x - cx) <= R && Math.abs(l.y - cy) <= R).map((l) => landmarkInfo(l, req.user.id)),
    allyMarks: allyMarksIn(req.user.id, cx - R, cx + R, cy - R, cy + R),
    inAlliance: !!allianceOf(req.user.id),
    rich: richIn(cx - R, cx + R, cy - R, cy + R, now),
    traders: tradersIn(cx - R, cx + R, cy - R, cy + R, req.user.id, now).map((t) => Object.assign(t, { inRange: distance(me.x, me.y, t.x, t.y) <= TRADER_RANGE })),
    zone: zoneInfo(req.user.id, now),
    pylons: pylonMapInfo(req.user.id, now, targeted),
    marks: marksOf(req.user.id),
    fx: worldFxIn(cx - R, cx + R, cy - R, cy + R, now),
    markIcons: MARK_ICONS,
    terrain: TERRAIN,
    serverNow: now,
    totalPlayers: db.prepare("SELECT COUNT(*) AS n FROM users").get().n,
  });
});

