const COUNTRY_FLAG_SVGS = JSON.parse(require("zlib").gunzipSync(Buffer.from("","base64")).toString("utf8"));
app.get("/country-flags/:code.svg", (req,res)=>{
 const code=String(req.params.code||"").toUpperCase();
 if(!Object.prototype.hasOwnProperty.call(COUNTRY_FLAG_SVGS,code))return res.status(404).send("Unknown flag");
 res.setHeader("Cache-Control","public, max-age=604800");
 res.type("image/svg+xml").send(COUNTRY_FLAG_SVGS[code]);
});
function profileFlags(raw) { try { const a = JSON.parse(raw || "[]"); return Array.isArray(a) ? [...new Set(a.filter(c => PROFILE_COUNTRIES.includes(c)))].slice(0, 3) : []; } catch (_) { return []; } }

// Badges that only last for one round (weekly ranks and achievements);
// champions of a round (Hall of Fame, Relic Hunt, Aurora) stay for good.
const ROUND_BADGE_KEYS = ["board10", "board30", "board60", "grad", "win1", "win100", "npc500", "loot100k", "colony2", "colony5", "ruler", "kraken", "relic"];
function roundBadge(key) {
  return /^w\d/.test(key) || ROUND_BADGE_KEYS.includes(key);
}
function meaningfulBadge(key, title) {
  return !["board10","board30","grad","win1","npc500","loot100k","colony2"].includes(key)
    && (!/^w\d/.test(key) || !/ #[23] · Week /.test(title));
}
addColumn("badges", "server_name", "TEXT");
addColumn("badges", "server_week", "INTEGER");
function medalWeek(at, startedAt) {
  return Math.max(1, Math.floor((at - startedAt) / (7 * 86400000)) + 1);
}
function giveBadge(userId, key, icon, title, at) {
  if (!userId || !meaningfulBadge(key, title)) return;
  const earned = at || Date.now();
  db.prepare("INSERT OR IGNORE INTO badges (user_id, key, icon, title, earned_at, server_name, server_week) VALUES (?, ?, ?, ?, ?, ?, ?)")
    .run(userId, key, icon, title, earned, thisServerName(), medalWeek(earned, serverStartAt()));
}
function medalDisplay(b, startedAt, server, history) {
  const at = b.earned_at || b.at;
  const oldRound = at < startedAt && history.find(r => at >= r.started_at && at <= r.ended_at);
  return {
    title: /^w\d/.test(b.key) ? b.title.replace(/ · Week \d+ \d{4}$/, "") : b.title,
    server: b.server_name || b.server || (oldRound ? oldRound.server : server),
    week: b.server_week || (oldRound ? medalWeek(at, oldRound.started_at) : at >= startedAt ? medalWeek(at, startedAt) : null)
  };
}

const WEEKLY_BADGES = {
  atk_kills: ["⚔️", "Attacker"],
  def_kills: ["🛡️", "Defender"],
  npc_kills: ["🦂", "Monster Hunter"],
  loot: ["💰", "Raider"],
};
const MEDALS = ["🥇", "🥈", "🥉"];

// When a week is over, its top 3 in every category get a badge (once)
function awardWeeklyBadges(now) {
  const lastStart = weekStart(weekStart(now) - 1);
  const row = db.prepare("SELECT value FROM settings WHERE key = 'badges_week'").get();
  if (row && Number(row.value) >= lastStart) return;
  const end = lastStart + 7 * 86400000;
  for (const key of WEEKLY_KEYS) {
    const top = db
      .prepare(
        `SELECT user_id, SUM(n) AS total FROM stats_log WHERE key = ? AND at >= ? AND at < ?
           AND user_id NOT IN (SELECT id FROM users WHERE bot = 1)
         GROUP BY user_id HAVING total > 0 ORDER BY total DESC LIMIT 3`
      )
      .all(key, lastStart, end);
    top.forEach((t, i) => {
      const [icon, name] = WEEKLY_BADGES[key];
      const title = (i === 0 ? "Top " + name : name + " #" + (i + 1));
      giveBadge(t.user_id, "w" + lastStart + ":" + key, MEDALS[i] + icon, title, end);
    });
  }
  db.prepare("INSERT INTO settings (key, value) VALUES ('badges_week', ?) ON CONFLICT (key) DO UPDATE SET value = excluded.value").run(String(lastStart));
}

// 🏅 leagues: every week the players are split by points into four leagues,
// and every league has its own winner in this week's contest (it rotates)
const LEAGUES = [
  { icon: "🥔", name: "Potato League" },
  { icon: "🪨", name: "Boulder League" },
  { icon: "🌋", name: "Volcano League" },
  { icon: "🌌", name: "Star League" },
];
const LEAGUE_CONTESTS = [
  { key: "loot", icon: "💰", name: "Loot", unit: "resources looted" },
  { key: "npc_kills", icon: "🦂", name: "Camps", unit: "monsters defeated" },
  { key: "def_kills", icon: "🛡️", name: "Defense", unit: "attackers stopped" },
  { key: "trade", icon: "🐪", name: "Trade", unit: "resources delivered to other players" },
];
function leagueContest(weekFrom) {
  return LEAGUE_CONTESTS[Math.floor(weekFrom / (7 * 86400000)) % LEAGUE_CONTESTS.length];
}
function leagueTable() {
  const rows = db.prepare("SELECT DISTINCT users.id, users.username FROM users JOIN colonies ON colonies.user_id = users.id WHERE users.bot = 0").all()
    .map((u) => ({ id: u.id, name: u.username, points: playerPoints(u.id) }))
    .sort((a, b) => a.points - b.points || a.id - b.id);
  const n = rows.length;
  rows.forEach((r, i) => { r.league = n ? Math.min(3, Math.floor((i * 4) / n)) : 0; });
  return rows;
}
function leagueScores(key, from, to) {
  const m = new Map();
  for (const r of db.prepare("SELECT user_id, SUM(n) AS total FROM stats_log WHERE key = ? AND at >= ? AND at < ? GROUP BY user_id").all(key, from, to)) m.set(r.user_id, r.total);
  return m;
}
function awardLeagues(now) {
  const lastStart = weekStart(weekStart(now) - 1);
  if (Number(settingOf("league_week", "0")) >= lastStart) return;
  const end = lastStart + 7 * 86400000, C = leagueContest(lastStart);
  const table = leagueTable(), sc = leagueScores(C.key, lastStart, end);
  for (let L = 0; L < 4; L++) {
    const best = table.filter((r) => r.league === L && (sc.get(r.id) || 0) > 0).sort((a, b) => sc.get(b.id) - sc.get(a.id))[0];
    if (best) giveBadge(best.id, "w" + lastStart + ":league" + L, LEAGUES[L].icon, LEAGUES[L].name + " winner (" + C.name + ") · Week " + wk.week + " " + wk.year, end);
  }
  setSetting("league_week", String(lastStart));
}
function leagueView(myId, now) {
  const start = weekStart(now), C = leagueContest(start);
  const table = leagueTable(), me = table.find((r) => r.id === myId);
  if (!me) return null;
  const sc = leagueScores(C.key, start, now + 1);
  const mates = table.filter((r) => r.league === me.league).map((r) => ({ player: r.name, value: sc.get(r.id) || 0, me: r.id === myId })).sort((a, b) => b.value - a.value || a.player.localeCompare(b.player));
  const lo = mates.length ? Math.min.apply(null, table.filter((r) => r.league === me.league).map((r) => r.points)) : 0;
  return { league: me.league, icon: LEAGUES[me.league].icon, name: LEAGUES[me.league].name, contest: C, size: mates.length, rank: mates.findIndex((m) => m.me) + 1, top: mates.slice(0, 5), mine: sc.get(myId) || 0, ends: start + 7 * 86400000, from: lo, next: LEAGUE_CONTESTS[(LEAGUE_CONTESTS.indexOf(C) + 1) % LEAGUE_CONTESTS.length] };
}

// 🎖️ across rounds: the badges of a round become medals for good, and medals
// unlock commander titles. Cosmetic only.
const LEGACY_TITLES = [
  { key: "rookie", name: "Rookie of Mars", need: (L) => true, how: "Everybody starts here" },
  { key: "veteran", name: "Veteran of Mars", need: (L) => L.medals.length >= 1, how: "1 medal" },
  { key: "old", name: "Old Red Dust", need: (L) => L.medals.length >= 10, how: "10 medals" },
  { key: "tamer", name: "Monster Tamer", need: (L) => L.medals.some((m) => /npc|Hunter|hunt/i.test(m.key + m.title)), how: "a monster hunting medal" },
  { key: "boss", name: "Raid Boss", need: (L) => L.medals.some((m) => /loot|Raider/i.test(m.key + m.title)), how: "a raiding medal" },
  { key: "wall", name: "The Wall", need: (L) => L.medals.some((m) => /def|Defender/i.test(m.key + m.title)), how: "a defense medal" },
  { key: "league", name: "League Legend", need: (L) => L.medals.some((m) => /league/.test(m.key)), how: "a league win" },
  { key: "builder", name: "Empire Builder", need: (L) => L.medals.some((m) => /colony5|board60/.test(m.key)), how: "5 colonies or 60 missions in a round" },
  { key: "aurora", name: "Lightbringer", need: (L) => L.rounds.some((r) => r.aurora), how: "light the Aurora with your alliance" },
];
function legacyOf(userId) {
  const r = db.prepare("SELECT legacy FROM users WHERE id = ?").get(userId);
  let L = {};
  try { L = r && r.legacy ? JSON.parse(r.legacy) : {}; } catch (e) {}
  L.medals = (L.medals || []).filter(m => meaningfulBadge(m.key,m.title));
  L.rounds = L.rounds || [];
  return L;
}
function saveLegacy(userId, L) {
  db.prepare("UPDATE users SET legacy = ? WHERE id = ?").run(JSON.stringify(L), userId);
}
function legacyTitles(L) {
  return LEGACY_TITLES.map((t) => ({ key: t.key, name: t.name, how: t.how, open: !!t.need(L) }));
}
function legacyTitle(userId) {
  const L = legacyOf(userId);
  const t = LEGACY_TITLES.find((x) => x.key === L.title);
  return t && t.need(L) ? t.name : "";
}
// at the end of a round, before the round badges are swept away
function legacyBank(now) {
  const server = thisServerName() + " x" + PRODUCTION_SPEED;
  const aur = (() => { try { return JSON.parse(settingOf("round_aurora", "null")); } catch (e) { return null; } })();
  for (const u of db.prepare("SELECT id, username FROM users WHERE bot = 0").all()) {
    const L = legacyOf(u.id);
    const lit = !!(aur && aur.players && aur.players.includes(u.username));
    L.rounds.push({ server, at: now, points: playerPoints(u.id), aurora: lit });
    if (L.rounds.length > 50) L.rounds = L.rounds.slice(-50);
    saveLegacy(u.id, L);
  }
}
app.post("/api/legacy-title", requireLogin, (req, res) => {
  const k = String((req.body || {}).key || "");
  const L = legacyOf(req.user.id);
  const t = LEGACY_TITLES.find((x) => x.key === k);
  if (k && (!t || !t.need(L))) return res.status(400).json({ error: "That title is still locked" });
  L.title = k;
  saveLegacy(req.user.id, L);
  res.json({ ok: true });
});

// Achievements that can be read from the statistics
function checkAchievements(userId) {
  const st = db.prepare("SELECT * FROM stats WHERE user_id = ?").get(userId) || {};
  const cols = colonyIdsOf(userId).length;
  const z = zoneRow();
  if ((st.wins || 0) >= 1) giveBadge(userId, "win1", "🏅", "First Victory");
  if ((st.wins || 0) >= 100) giveBadge(userId, "win100", "🏆", "Warlord (100 wins)");
  if ((st.npc_kills || 0) >= 500) giveBadge(userId, "npc500", "🦂", "Monster Hunter (500 kills)");
  if ((st.loot || 0) >= 100000) giveBadge(userId, "loot100k", "💰", "Treasure Hoarder (100k loot)");
  if (cols >= 2) giveBadge(userId, "colony2", "🏳️", "Founder");
  if (cols >= 5) giveBadge(userId, "colony5", "🗺️", "Empire Builder (5 colonies)");
  if ((st.crown_ms || 0) > 0 || zoneHolderUser(z) === userId) giveBadge(userId, "ruler", "👑", "Ruler of Mars");
}

function badgeRound() {
  const now = Date.now();
  try {
    awardWeeklyBadges(now);
    awardLeagues(now);
    for (const u of db.prepare("SELECT id FROM users WHERE bot = 0").all()) checkAchievements(u.id);
  } catch (e) {
    console.error("badges:", e.message);
  }
}
setTimeout(badgeRound, 3000);
setInterval(badgeRound, 10 * 60000);

// =====================================================================
//  PLAYER PROFILES
// =====================================================================
app.get("/api/profile", requireLogin, (req, res) => {
  const name = String(req.query.name || req.user.username);
  const u = db.prepare("SELECT id, username, created_at, bio, profile_flags, last_seen FROM users WHERE username = ?").get(name);
  if (!u) return res.status(404).json({ error: "There is no player with that name" });
  checkAchievements(u.id);
  const me = u.id === req.user.id;
  const cols = coloniesOf(u.id);
  const st = db.prepare("SELECT * FROM stats WHERE user_id = ?").get(u.id) || {};
  const points = cols.reduce((n, c) => n + colonyPoints(c.state), 0);
  // rank by points among all players with a colony
  const all = db.prepare("SELECT id FROM users").all().map((x) => playerPoints(x.id));
  const rank = 1 + all.filter((p) => p > points).length;
  const a = allianceOf(u.id);
  const startedAt = serverStartAt(), server = thisServerName();
  const history = db.prepare("SELECT server, started_at, ended_at FROM hall_of_fame ORDER BY ended_at DESC").all();
  const badges = db
    .prepare("SELECT id, key, icon, title, earned_at, shown, server_name, server_week FROM badges WHERE user_id = ? " + (me ? "" : "AND shown = 1 ") + "ORDER BY earned_at DESC")
    .all(u.id)
    .filter(b => meaningfulBadge(b.key,b.title))
    .map((b) => ({ id: b.id, icon: b.icon, at: b.earned_at, shown: !!b.shown, round: roundBadge(b.key), ...medalDisplay(b, startedAt, server, history) }));
  const relics = cols
    .filter((c) => c.state.relic)
    .map((c) => landmarkByKey(c.state.relic))
    .filter(Boolean)
    .map((l) => ({ icon: l.icon, name: l.name, bonus: l.bonus.text }));
  res.json({
    player: u.username,
    me,
    joined: u.created_at,
    online: Date.now() - (u.last_seen || 0) < 10 * 60000,
    bio: u.bio || "",
    flags: profileFlags(u.profile_flags),
    flagOptions: me ? PROFILE_COUNTRIES : undefined,
    tribe: cols[0] ? { icon: tribeOf(cols[0].tribe).icon, name: tribeOf(cols[0].tribe).name } : null,
    points,
    rank,
    colonies: cols.map((c) => ({ name: c.name, x: c.x, y: c.y, points: colonyPoints(c.state) })),
    alliance: a ? { name: a.name, tag: a.tag, role: a.role } : null,
    ally: areAllies(u.id, req.user.id),
    king: zoneHolderUser(zoneRow()) === u.id,
    relics,
    stats: { wins: st.wins || 0, battles: st.battles || 0, atk: st.atk_kills || 0, def: st.def_kills || 0, npc: st.npc_kills || 0, loot: st.loot || 0 },
    badges,
    legacy: (() => { const L = legacyOf(u.id); return { title: legacyTitle(u.id), medals: L.medals.slice(-60).reverse().map(m => ({...m, ...medalDisplay(m, startedAt, server, history)})), count: L.medals.length, rounds: L.rounds.length, titles: me ? legacyTitles(L).filter(t => t.open) : undefined, chosen: me ? L.title || "" : undefined }; })(),
    protected: protectionOf(u.id).active,
    vacation: vacationOf(u.id).on,
    sat: !!(me && sittersOf(u.id).length),
    lfa: (() => { const r = db.prepare("SELECT lfa, lfa_note FROM users WHERE id = ?").get(u.id); return r && r.lfa && !a ? { note: r.lfa_note || "" } : null; })(),
    commander: (() => { const h = heroReady && !BOT_IDS.has(u.id) ? heroOf(u.id) : null; if (!h) return null; const pth = HERO_PATHS[h.tribe]; return { name: h.name, level: h.level, path: pth && h.pts.path ? pth.icon + " " + pth.name + " " + h.pts.path : null, wins: (h.stats && h.stats.wins) || 0, card: (() => { const r = rosterOf(u.id, Date.now()); const c = r && r.cards.find((x) => x.id === r.active); const d = c && COMMANDERS[c.key]; return d ? { name: d.name, icon: d.icon, rarity: d.rarity, rank: c.rank } : null; })() }; })(),
  });
});

