app.post("/api/admin/events", requireOwner, (req, res) => {
  const b = req.body || {};
  const now = Date.now();
  if (b.on !== undefined) db.prepare("INSERT INTO settings (key, value) VALUES ('events_on', ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value").run(b.on ? "1" : "0");
  if (b.start) {
    if (!EVENT_KINDS[b.start]) return res.status(400).json({ error: "Unknown event" });
    if (currentEvent(now)) return res.status(400).json({ error: "An event is already running" });
    startEvent(b.start, now);
  }
  if (b.titan === "spawn") {
    if (titanNow()) return res.status(400).json({ error: "A Dust Titan is already out there" });
    if (!spawnTitan(now)) return res.status(400).json({ error: "No free camp found" });
  }
  if (b.titan === "stop") {
    db.prepare("UPDATE titan SET until = ? WHERE done = 0").run(now);
    titanCache = null;
  }
  if (b.stop) {
    db.prepare("UPDATE events SET ends = ? WHERE ends > ?").run(now, now);
    db.prepare("DELETE FROM meteors").run();
    loadEvents();
  }
  res.json({ ok: true });
});

// =====================================================================
//  ALLIANCE TEAMWORK
//   🏦 Bank: members put resources in; the leader pays them out or
//      spends them on projects
//   ✨ Projects: a few days of a bonus for EVERY member
//   "🎯" Joint attacks: pick a target and a landing time, everybody sees
//      when each of their colonies has to send which troops
// =====================================================================
// ✨ Alliance projects: PERMANENT bonuses for every member, in 5 levels.
// Members donate to the project they like; a full pot raises its level.
// "per" is the bonus per level. Speed bonuses mean "x% faster" (time / (1 + bonus)).
// Each level costs costHours x LEVEL_GROWTH^(level-1) hours of a typical
// player's production per member (at least 3 members are counted).
const ALLY_MAX_LEVEL = 5;
const ALLY_LEVEL_GROWTH = 1.6;
const ALLY_PROJECTS = {
  harvest: { icon: "🌾", name: "Big Harvest", what: "production", per: 0.02, costHours: 3 },
  builders: { icon: "🏗️", name: "Builders’ Guild", what: "faster building & fields", per: 0.04, costHours: 3 },
  drill: { icon: "🎖️", name: "Drill Camp", what: "faster troop training", per: 0.04, costHours: 3 },
  lab: { icon: "🔬", name: "Think Tank", what: "faster research & weapon upgrades", per: 0.05, costHours: 2 },
  drums: { icon: "🥁", name: "War Drums", what: "attack", per: 0.015, costHours: 4 },
  shield: { icon: "🛡️", name: "Shield Wall", what: "defense", per: 0.02, costHours: 3 },
  green: { icon: "🌱", name: "Green Mars", what: "terra", per: 0.04, costHours: 2 },
  caravan: { icon: "🐪", name: "Caravans", what: "faster merchants", per: 0.08, costHours: 2 },
};
function allyProjText(kind, level) {
  const p = ALLY_PROJECTS[kind];
  const v = Math.round(p.per * level * 1000) / 10;
  return "+" + v + "% " + p.what;
}
db.exec(`
  CREATE TABLE IF NOT EXISTS alliance_bank (
    alliance_id INTEGER PRIMARY KEY,
    wood INTEGER NOT NULL DEFAULT 0, stone INTEGER NOT NULL DEFAULT 0,
    metal INTEGER NOT NULL DEFAULT 0, food INTEGER NOT NULL DEFAULT 0
  );
  CREATE TABLE IF NOT EXISTS alliance_bank_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT, alliance_id INTEGER NOT NULL,
    at INTEGER NOT NULL, user_id INTEGER, text TEXT NOT NULL
  );
  CREATE TABLE IF NOT EXISTS alliance_projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT, alliance_id INTEGER NOT NULL,
    kind TEXT NOT NULL, starts INTEGER NOT NULL, ends INTEGER NOT NULL
  );
  CREATE TABLE IF NOT EXISTS alliance_levels (
    alliance_id INTEGER NOT NULL, kind TEXT NOT NULL, level INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (alliance_id, kind)
  );
  CREATE TABLE IF NOT EXISTS alliance_project_pots (
    alliance_id INTEGER NOT NULL, kind TEXT NOT NULL,
    wood INTEGER NOT NULL DEFAULT 0, stone INTEGER NOT NULL DEFAULT 0,
    metal INTEGER NOT NULL DEFAULT 0, food INTEGER NOT NULL DEFAULT 0,
    rounds INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (alliance_id, kind)
  );
  CREATE TABLE IF NOT EXISTS alliance_project_donors (
    alliance_id INTEGER NOT NULL, kind TEXT NOT NULL, user_id INTEGER NOT NULL,
    amount INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (alliance_id, kind, user_id)
  );
  CREATE TABLE IF NOT EXISTS alliance_plan_joins (
    plan_id INTEGER NOT NULL, user_id INTEGER NOT NULL, PRIMARY KEY (plan_id, user_id)
  );
  CREATE TABLE IF NOT EXISTS alliance_plans (
    id INTEGER PRIMARY KEY AUTOINCREMENT, alliance_id INTEGER NOT NULL,
    by_id INTEGER NOT NULL, x INTEGER NOT NULL, y INTEGER NOT NULL,
    land_at INTEGER NOT NULL, note TEXT NOT NULL DEFAULT ''
  );
`);
addColumn("alliance_project_pots", "cred", "INTEGER NOT NULL DEFAULT 0"); // Star Credits given to the pot for this level

// fast lookups for the bonuses (they are asked for very often)
var ALLY_PROJ;
var allyOfCache = { at: 0, map: new Map() };
// levels of every alliance: Map(aid -> { kind: level })
function loadAllyProjects() {
  const m = new Map();
  for (const r of db.prepare("SELECT alliance_id AS aid, kind, level FROM alliance_levels WHERE level > 0").all()) {
    if (!m.has(r.aid)) m.set(r.aid, {});
    m.get(r.aid)[r.kind] = r.level;
  }
  ALLY_PROJ = m;
}
function allyIdOf(uid) {
  if (!uid) return 0;
  const now = Date.now();
  if (now - allyOfCache.at > 30000) {
    allyOfCache = { at: now, map: new Map(db.prepare("SELECT user_id, alliance_id FROM alliance_members").all().map((r) => [r.user_id, r.alliance_id])) };
  }
  return allyOfCache.map.get(uid) || 0;
}
function allyLevel(aid, kind) {
  if (!aid || !ALLY_PROJ) return 0;
  const l = ALLY_PROJ.get(aid);
  return l && l[kind] ? l[kind] : 0;
}
function allyBoost(uid, kind) {
  const p = ALLY_PROJECTS[kind];
  return p ? allyLevel(allyIdOf(uid), kind) * p.per : 0;
}
// (kept for the production code: the bonus is permanent now)
function allyShare(uid, kind) {
  return allyBoost(uid, kind);
}
function allyAttackLevel(a, level) {
  const b = level * ALLY_PROJECTS.drums.per;
  return b ? { g: a.g * (1 + b), a: a.a * (1 + b) } : a;
}
function allyAttack(a, uid) {
  const b = allyBoost(uid, "drums");
  return b ? { g: a.g * (1 + b), a: a.a * (1 + b) } : a;
}
loadAllyProjects();
setInterval(loadAllyProjects, 60000);

function bankOf(aid) {
  db.prepare("INSERT OR IGNORE INTO alliance_bank (alliance_id) VALUES (?)").run(aid);
  return db.prepare("SELECT wood, stone, metal, food FROM alliance_bank WHERE alliance_id = ?").get(aid);
}
function bankLog(aid, uid, text) {
  db.prepare("INSERT INTO alliance_bank_log (alliance_id, at, user_id, text) VALUES (?, ?, ?, ?)").run(aid, Date.now(), uid, text);
  db.prepare("DELETE FROM alliance_bank_log WHERE alliance_id = ? AND id NOT IN (SELECT id FROM alliance_bank_log WHERE alliance_id = ? ORDER BY id DESC LIMIT 30)").run(aid, aid);
}
const resText = (r) => RESOURCES.filter((k) => r[k] > 0).map((k) => r[k] + " " + k).join(", ");
function cleanRes(raw) {
  const r = {};
  for (const k of RESOURCES) {
    const n = Number((raw || {})[k] || 0);
    if (!Number.isInteger(n) || n < 0) return null;
    r[k] = n;
  }
  return r;
}
// A project costs about "costHours" hours of a typical player's production per member
function projectCost(aid, kind, now) {
  const members = db.prepare("SELECT COUNT(*) AS n FROM alliance_members WHERE alliance_id = ?").get(aid).n;
  const next = Math.min(ALLY_MAX_LEVEL, allyLevel(aid, kind) + 1);
  const hours = ALLY_PROJECTS[kind].costHours * Math.pow(ALLY_LEVEL_GROWTH, next - 1);
  const each = Math.round(meteorSize(now) * hours * Math.max(3, members) / 4 / 10) * 10;
  const cost = {};
  for (const k of RESOURCES) cost[k] = each;
  return cost;
}

// Everything for the alliance page (added to /api/alliance)
function allianceExtras(aid, uid, now) {
  const bank = bankOf(aid);
  const log = db.prepare("SELECT alliance_bank_log.at, alliance_bank_log.text, users.username FROM alliance_bank_log LEFT JOIN users ON users.id = alliance_bank_log.user_id WHERE alliance_id = ? ORDER BY alliance_bank_log.id DESC LIMIT 8").all(aid)
    .map((r) => ({ at: r.at, text: r.text, by: r.username || "🤝 Alliance" }));
  const projects = Object.keys(ALLY_PROJECTS).map((k) => {
    const p = ALLY_PROJECTS[k];
    const level = allyLevel(aid, k);
    const max = level >= ALLY_MAX_LEVEL;
    const donors = max ? [] : db.prepare("SELECT users.username AS name, amount FROM alliance_project_donors LEFT JOIN users ON users.id = alliance_project_donors.user_id WHERE alliance_id = ? AND kind = ? AND amount > 0 ORDER BY amount DESC LIMIT 5").all(aid, k);
    return { key: k, icon: p.icon, name: p.name, level, max: ALLY_MAX_LEVEL, now: level ? allyProjText(k, level) : "no bonus yet", next: max ? null : allyProjText(k, level + 1), cost: max ? null : projectCost(aid, k, now), pot: potOf(aid, k), donors, credit: max ? null : (() => { const c = allyCreditInfo(aid, k, now); return { each: c.rate, room: c.room }; })() };
  });
  db.prepare("DELETE FROM alliance_plans WHERE land_at < ?").run(now - 3600000);
  db.prepare("DELETE FROM alliance_plan_joins WHERE plan_id NOT IN (SELECT id FROM alliance_plans)").run();
  const myCols = coloniesOf(uid);
  const plans = db.prepare("SELECT alliance_plans.*, users.username FROM alliance_plans LEFT JOIN users ON users.id = alliance_plans.by_id WHERE alliance_id = ? ORDER BY land_at").all(aid).map((p) => {
    const target = db.prepare("SELECT name, user_id FROM colonies WHERE x = ? AND y = ?").get(p.x, p.y);
    // when must each of MY colonies send which troops, to land right on time?
    const legs = [];
    for (const c of myCols) {
      const tribe = tribeOf(c.tribe);
      const dist = distance(c.x, c.y, p.x, p.y);
      // one departure per speed: all troops of the same speed leave together
      const bySpeed = new Map();
      Object.keys(c.state.troops)
        .filter((k) => c.state.troops[k] > 0 && tribe.units[k] && !isSettler(tribe.units[k]) && !isScout(tribe.units[k]))
        .forEach((k) => {
          const u = tribe.units[k];
          if (!bySpeed.has(u.speed)) bySpeed.set(u.speed, []);
          bySpeed.get(u.speed).push({ key: k, icon: u.icon, name: u.name, count: Math.floor(c.state.troops[k]) });
        });
      for (const [speed, units] of bySpeed) {
        legs.push({ colony: c.name, colonyId: c.id, units, speed: speed * MOVE_SPEED, leaveAt: p.land_at - travelMs(dist, speed) });
      }
    }
    legs.sort((a, b) => a.leaveAt - b.leaveAt);
    const joined = db.prepare("SELECT users.username AS name, alliance_plan_joins.user_id AS id, alliance_plan_joins.note AS note FROM alliance_plan_joins JOIN users ON users.id = alliance_plan_joins.user_id WHERE plan_id = ?").all(p.id);
    return { id: p.id, x: p.x, y: p.y, landAt: p.land_at, note: p.note, by: p.username || "?", mine: p.by_id === uid,
      joined: joined.map((j) => j.name), notes: joined.filter((j) => j.note).map((j) => ({ name: j.name, note: j.note })), myNote: (joined.find((j) => j.id === uid) || {}).note || "", iJoined: joined.some((j) => j.id === uid),
      target: target ? target.name + " (" + usernameOf(target.user_id) + ")" : p.x === 0 && p.y === 0 ? "🚩 Landing Zone" : landmarkAtXY(p.x, p.y) ? landmarkAtXY(p.x, p.y).name : terrainAt(p.x, p.y) === "n" ? campKind(p.x, p.y).name : "Target", legs };
  });
  return { bank, log, projects, plans };
}

function allyMember(req) {
  const me = allianceOf(req.user.id);
  return me ? me : null;
}

app.post("/api/alliance/bank/deposit", requireLogin, (req, res) => {
  const me = allyMember(req);
  if (!me) return res.status(400).json({ error: "You are not in an alliance" });
  const want = cleanRes((req.body || {}).res);
  if (!want || !RESOURCES.some((k) => want[k] > 0)) return res.status(400).json({ error: "Enter how much to put in" });
  withColony(req, res, (s) => {
    for (const k of RESOURCES) if (want[k] > Math.floor(s.res[k])) return "This colony doesn't have that much " + k;
    for (const k of RESOURCES) s.res[k] -= want[k];
    bankOf(me.id);
    db.prepare("UPDATE alliance_bank SET wood = wood + ?, stone = stone + ?, metal = metal + ?, food = food + ? WHERE alliance_id = ?").run(want.wood, want.stone, want.metal, want.food, me.id);
    bankLog(me.id, req.user.id, "put in " + resText(want));
    return null;
  });
});

app.post("/api/alliance/bank/give", requireLogin, (req, res) => {
  const me = allyMember(req);
  if (!me || !allyStaff(me)) return res.status(400).json({ error: "Only the leader and officers can pay out" });
  const b = req.body || {};
  const want = cleanRes(b.res);
  if (!want || !RESOURCES.some((k) => want[k] > 0)) return res.status(400).json({ error: "Enter how much to pay out" });
  const to = db.prepare("SELECT id, username FROM users WHERE username = ?").get(String(b.name || ""));
  if (!to || allyIdOf(to.id) !== me.id) return res.status(400).json({ error: "That player is not in your alliance" });
  if (accountsLinked(to.id, req.user.id)) return res.status(400).json({ error: LINKED_MSG });
  const bank = bankOf(me.id);
  for (const k of RESOURCES) if (want[k] > bank[k]) return res.status(400).json({ error: "The bank doesn't have that much " + k });
  // to the player's main colony; what doesn't fit stays in the bank
  const col = coloniesOf(to.id).find((c) => c.state.main) || coloniesOf(to.id)[0];
  if (!col) return res.status(400).json({ error: "That player has no colony" });
  update(col.state, tribeOf(col.tribe), Date.now());
  const cap = capacities(col.state);
  const sent = {};
  for (const k of RESOURCES) sent[k] = Math.max(0, Math.min(want[k], Math.floor(cap[k] - col.state.res[k])));
  for (const k of RESOURCES) col.state.res[k] += sent[k];
  saveColony(col.id, col.state);
  db.prepare("UPDATE alliance_bank SET wood = wood - ?, stone = stone - ?, metal = metal - ?, food = food - ? WHERE alliance_id = ?").run(sent.wood, sent.stone, sent.metal, sent.food, me.id);
  bankLog(me.id, req.user.id, "paid " + (resText(sent) || "nothing (storage full)") + " to " + to.username);
  res.json({ ok: true, sent });
});

// ✨ Projects are funded together: every member donates to the pot they like.
// As soon as a pot holds the full cost of the next level, the level goes up
// by itself, for good, for every member. No leader needed.
function potOf(aid, kind) {
  const p = db.prepare("SELECT wood, stone, metal, food FROM alliance_project_pots WHERE alliance_id = ? AND kind = ?").get(aid, kind);
  return p ? { wood: p.wood, stone: p.stone, metal: p.metal, food: p.food } : { wood: 0, stone: 0, metal: 0, food: 0 };
}
function fundProject(aid, uid, kind, give, now) {
  const p = ALLY_PROJECTS[kind];
  const level = allyLevel(aid, kind);
  if (level >= ALLY_MAX_LEVEL) return { error: p.name + " is already at the highest level" };
  const cost = projectCost(aid, kind, now);
  const pot = potOf(aid, kind);
  // never take more than the pot still needs
  const took = {};
  for (const k of RESOURCES) took[k] = Math.max(0, Math.min(give[k], cost[k] - pot[k]));
  const n = RESOURCES.reduce((a, k) => a + took[k], 0);
  if (!n) return { error: "This project already has enough of that. Give what is still missing." };
  for (const k of RESOURCES) pot[k] += took[k];
  db.prepare("INSERT INTO alliance_project_pots (alliance_id, kind, wood, stone, metal, food) VALUES (?, ?, ?, ?, ?, ?) ON CONFLICT(alliance_id, kind) DO UPDATE SET wood = excluded.wood, stone = excluded.stone, metal = excluded.metal, food = excluded.food").run(aid, kind, pot.wood, pot.stone, pot.metal, pot.food);
  if (uid) db.prepare("INSERT INTO alliance_project_donors (alliance_id, kind, user_id, amount) VALUES (?, ?, ?, ?) ON CONFLICT(alliance_id, kind, user_id) DO UPDATE SET amount = amount + excluded.amount").run(aid, kind, uid, n);
  let up = false;
  if (RESOURCES.every((k) => pot[k] >= cost[k])) {
    db.prepare("INSERT INTO alliance_levels (alliance_id, kind, level) VALUES (?, ?, 1) ON CONFLICT(alliance_id, kind) DO UPDATE SET level = MIN(" + ALLY_MAX_LEVEL + ", level + 1)").run(aid, kind);
    db.prepare("UPDATE alliance_project_pots SET wood = 0, stone = 0, metal = 0, food = 0, cred = 0, rounds = rounds + 1 WHERE alliance_id = ? AND kind = ?").run(aid, kind);
    db.prepare("DELETE FROM alliance_project_donors WHERE alliance_id = ? AND kind = ?").run(aid, kind);
    loadAllyProjects();
    bankLog(aid, null, p.icon + " " + p.name + " reached level " + (level + 1) + ": " + allyProjText(kind, level + 1) + " for everyone!");
    for (const m of allianceMembers(aid)) addReport(m.id, now, p.icon, tt("{0} level {1}", shortColonyName(p.name), level + 1), { mission: "aurora", flavor: "Your alliance finished a project. Every member now gets " + allyProjText(kind, level + 1) + ", for good." });
    up = level + 1;
  }
  return { took, up };
}

// 🎫 Star Credits into a project: one credit fills a little of every resource, but credits can cover
// at most ALLY_CREDIT_SHARE of a level, so the pot still needs real resources from the members
const ALLY_CREDIT_SHARE = 0.3, ALLY_CREDIT_PER_HOUR = 0.02; // a credit = 2% of a typical player's hourly production, of each resource
function allyCreditInfo(aid, kind, now) {
  const cost = projectCost(aid, kind, now);
  const rate = Math.max(1, Math.round(meteorSize(now) * ALLY_CREDIT_PER_HOUR));
  const pot = db.prepare("SELECT cred FROM alliance_project_pots WHERE alliance_id = ? AND kind = ?").get(aid, kind);
  const room = Math.max(0, Math.floor((cost.wood * ALLY_CREDIT_SHARE) / rate) - (pot ? pot.cred : 0));
  return { cost, rate, room };
}
app.post("/api/alliance/credits", requireLogin, (req, res) => {
  const me = allyMember(req);
  if (!me) return res.status(400).json({ error: "You are not in an alliance" });
  const kind = String((req.body || {}).kind || "");
  if (!ALLY_PROJECTS[kind]) return res.status(400).json({ error: "Unknown project" });
  const want = Math.floor(Number((req.body || {}).credits) || 0);
  if (want < 1) return res.status(400).json({ error: "Enter how many Star Credits to give" });
  const now = Date.now();
  if (allyLevel(me.id, kind) >= ALLY_MAX_LEVEL) return res.status(400).json({ error: ALLY_PROJECTS[kind].name + " is already at the highest level" });
  const info = allyCreditInfo(me.id, kind, now);
  const pot = potOf(me.id, kind);
  const missing = Math.max(...RESOURCES.map((k) => Math.max(0, info.cost[k] - pot[k])));
  const take = Math.min(want, info.room, Math.ceil(missing / info.rate));
  if (take < 1) return res.status(400).json({ error: info.room < 1 ? "Star Credits already cover their share of this level. The rest must come as resources." : "This project already has enough." });
  commanderCollect(req.user.id, now);
  if (creditsOf(req.user.id) < take) return res.status(400).json({ error: "You need " + take + " Star Credits for this (you have " + creditsOf(req.user.id) + ")" });
  const give = {};
  for (const k of RESOURCES) give[k] = take * info.rate;
  const r = fundProject(me.id, req.user.id, kind, give, now);
  if (r.error) return res.status(400).json({ error: r.error });
  addCredits(req.user.id, -take);
  if (!r.up) db.prepare("UPDATE alliance_project_pots SET cred = cred + ? WHERE alliance_id = ? AND kind = ?").run(take, me.id, kind);
  bankLog(me.id, req.user.id, "gave " + take + " Star Credits to " + ALLY_PROJECTS[kind].icon + " " + ALLY_PROJECTS[kind].name);
  res.json({ ok: true, credits: take, up: r.up });
});

// Donate to a project from the colony you are in (or, as leader, from the bank)
app.post("/api/alliance/project", requireLogin, (req, res) => {
  const me = allyMember(req);
  if (!me) return res.status(400).json({ error: "You are not in an alliance" });
  const b = req.body || {};
  const kind = String(b.kind || "");
  if (!ALLY_PROJECTS[kind]) return res.status(400).json({ error: "Unknown project" });
  const want = cleanRes(b.res);
  if (!want || !RESOURCES.some((k) => want[k] > 0)) return res.status(400).json({ error: "Enter how much to give" });
  const now = Date.now();
  if (b.fromBank) {
    if (!allyStaff(me)) return res.status(400).json({ error: "Only the leader and officers can pay from the bank" });
    const bank = bankOf(me.id);
    for (const k of RESOURCES) want[k] = Math.min(want[k], bank[k]);
    const r = fundProject(me.id, null, kind, want, now);
    if (r.error) return res.status(400).json({ error: r.error });
    db.prepare("UPDATE alliance_bank SET wood = wood - ?, stone = stone - ?, metal = metal - ?, food = food - ? WHERE alliance_id = ?").run(r.took.wood, r.took.stone, r.took.metal, r.took.food, me.id);
    bankLog(me.id, req.user.id, "gave " + resText(r.took) + " from the bank to " + ALLY_PROJECTS[kind].icon + " " + ALLY_PROJECTS[kind].name);
    return res.json({ ok: true, took: r.took, up: r.up });
  }
  withColony(req, res, (s) => {
    for (const k of RESOURCES) if (want[k] > Math.floor(s.res[k])) return "This colony doesn't have that much " + k;
    const r = fundProject(me.id, req.user.id, kind, want, now);
    if (r.error) return r.error;
    for (const k of RESOURCES) s.res[k] -= r.took[k];
    return null;
  });
});

app.post("/api/alliance/plan", requireLogin, (req, res) => {
  const me = allyMember(req);
  if (!me) return res.status(400).json({ error: "You are not in an alliance" });
  const b = req.body || {};
  const now = Date.now();
  if (b.join) {
    const p = db.prepare("SELECT id FROM alliance_plans WHERE id = ? AND alliance_id = ?").get(Number(b.join), me.id);
    if (!p) return res.status(400).json({ error: "Plan not found" });
    if (b.on) {
      db.prepare("INSERT OR IGNORE INTO alliance_plan_joins (plan_id, user_id) VALUES (?, ?)").run(p.id, req.user.id);
      if (b.note !== undefined) db.prepare("UPDATE alliance_plan_joins SET note = ? WHERE plan_id = ? AND user_id = ?").run(String(b.note || "").trim().slice(0, 60), p.id, req.user.id);
    }
    else db.prepare("DELETE FROM alliance_plan_joins WHERE plan_id = ? AND user_id = ?").run(p.id, req.user.id);
    return res.json({ ok: true });
  }
  if (b.remove) {
    const p = db.prepare("SELECT * FROM alliance_plans WHERE id = ? AND alliance_id = ?").get(Number(b.remove), me.id);
    if (!p) return res.status(400).json({ error: "Plan not found" });
    if (p.by_id !== req.user.id && !allyStaff(me)) return res.status(400).json({ error: "Only the planner, an officer or the leader can remove it" });
    db.prepare("DELETE FROM alliance_plans WHERE id = ?").run(p.id);
    return res.json({ ok: true });
  }
  const x = parseInt(b.x, 10), y = parseInt(b.y, 10), landAt = Number(b.landAt);
  if (!Number.isInteger(x) || !Number.isInteger(y) || Math.abs(x) > MAP_RADIUS || Math.abs(y) > MAP_RADIUS) return res.status(400).json({ error: "Enter the target's X and Y" });
  if (!(landAt > now + 60000) || landAt > now + 7 * 86400000) return res.status(400).json({ error: "Pick a landing time in the future (up to 7 days)" });
  if (db.prepare("SELECT COUNT(*) AS n FROM alliance_plans WHERE alliance_id = ?").get(me.id).n >= 10) return res.status(400).json({ error: "10 plans at most. Remove an old one." });
  const ins = db.prepare("INSERT INTO alliance_plans (alliance_id, by_id, x, y, land_at, note) VALUES (?, ?, ?, ?, ?, ?)").run(me.id, req.user.id, x, y, Math.round(landAt), String(b.note || "").slice(0, 120));
  db.prepare("INSERT OR IGNORE INTO alliance_plan_joins (plan_id, user_id) VALUES (?, ?)").run(Number(ins.lastInsertRowid), req.user.id);
  res.json({ ok: true });
});

// =====================================================================
//  🌌 PROJECT AURORA - the alliance endgame (a season the owner starts)
//
//  Four ancient pylons stand at the edges of the planet. An alliance wins
//  by lighting the aurora over Mars:
//   1. CHARGE  every pylon: members send merchants full of resources.
//              A pylon that is fully charged is LOCKED for that alliance.
//              Until then, enemies can raid it and drain the charge.
//   2. LINK    every pylon to the Landing Zone with a "ley line": a chain
//              of the alliance's colonies, each at most AURORA_LINK tiles
//              from the next (the pylon and the Landing Zone are the ends).
//   3. IGNITE  hold the Landing Zone while all four pylons are charged and
//              linked. Then the countdown runs. Lose the flag or break a
//              ley line and it starts all over. Reach zero: you win.
// =====================================================================
const AURORA_LINK = 9; // max. tiles between two links of a ley line
const AURORA_CHARGE_HOURS = 4; // a pylon needs ~8 hours of production per member
const AURORA_IGNITE_HOURS = 24; // the final countdown
const AURORA_DRAIN_SHARE = 0.10; // one raid drains at most 25% of a pylon

db.exec(`
  CREATE TABLE IF NOT EXISTS aurora_charge (
    season      INTEGER NOT NULL,
    alliance_id INTEGER NOT NULL,
    pylon       TEXT NOT NULL,
    amount      INTEGER NOT NULL DEFAULT 0,
    locked      INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (season, alliance_id, pylon)
  );
`);

addColumn("aurora_charge", "secured", "INTEGER NOT NULL DEFAULT 0");
addColumn("movements", "aurora_meta", "TEXT");
function auroraDefaultHours() { return Math.max(2, Math.round(AURORA_IGNITE_HOURS / Math.max(1, Math.sqrt(PRODUCTION_SPEED / 10)))); }
function auroraGraceMs() { return Math.max(120000, Math.round(15 * 60000 / Math.max(1, Math.sqrt(PRODUCTION_SPEED / 10)))); }
// The same speed-neutral goal for every alliance: three typical main colonies
// funding several production hours per pylon. `production()` is per game hour,
// so server speed must not inflate the raw resource target.
function auroraBudget(now, hours) {
  const rates = db.prepare("SELECT colonies.* FROM colonies JOIN users ON users.id = colonies.user_id WHERE users.bot = 0 AND users.banned = 0 AND MAX(users.last_seen, users.created_at) > ?")
    .all(now - 3 * 86400000).map(loadColonyRow).filter((c) => c.state.main)
    .map((c) => RESOURCES.reduce((n, r) => n + Math.max(0, production(c.state)[r] || 0), 0)).sort((a, b) => a - b);
  const median = rates.length ? rates[Math.floor(rates.length / 2)] : 180;
  return Math.ceil(Math.max(30000, Math.min(60000, median * hours * 3)) / 100) * 100;
}
function ensureAuroraBudget(se, now) {
  if (Number.isFinite(se.pylonBudget) && se.pylonBudget > 0) return se.pylonBudget;
  se.pylonBudget = auroraBudget(now, se.charge || AURORA_CHARGE_HOURS);
  se.rulesVersion = 2;
  se.graceMs = auroraGraceMs();
  // Existing contributions and completed pylons survive the migration.
  for (const r of db.prepare("SELECT alliance_id, pylon, amount, locked FROM aurora_charge WHERE season = ?").all(se.number)) {
    const locked = r.locked || r.amount >= se.pylonBudget;
    const secured = locked ? se.pylonBudget : Math.floor(Math.floor(r.amount / se.pylonBudget * 4) * se.pylonBudget / 4);
    db.prepare("UPDATE aurora_charge SET locked = ?, secured = ? WHERE season = ? AND alliance_id = ? AND pylon = ?").run(locked ? 1 : 0, secured, se.number, r.alliance_id, r.pylon);
  }
  writeSeason(se);
  return se.pylonBudget;
}
function pylonIncoming(se, aid, key) {
  const p = PYLONS.find((x) => x.key === key);
  if (!p) return 0;
  return db.prepare("SELECT loot, aurora_meta FROM movements WHERE target_kind = 'pylon' AND mission = 'trade' AND phase = 'out' AND target_x = ? AND target_y = ?").all(p.x, p.y)
    .reduce((n, m) => { try { const meta = JSON.parse(m.aurora_meta || 'null'); return n + (meta && meta.season === se.number && meta.aid === aid ? lootTotal(JSON.parse(m.loot)) : 0); } catch (e) { return n; } }, 0);
}

function auroraSeason() {
  const se = readSeason();
  return se && se.kind === "aurora" ? se : null;
}
function auroraRunning() {
  const se = auroraSeason();
  return se && se.active ? se : null;
}
function allianceName(aid) {
  const a = db.prepare("SELECT name, tag FROM alliances WHERE id = ?").get(aid);
  return a ? "[" + a.tag + "] " + a.name : "?";
}
function allianceSize(aid) {
  return db.prepare("SELECT COUNT(*) AS n FROM alliance_members WHERE alliance_id = ?").get(aid).n;
}
// What one pylon needs (resources in total, any mix)
function pylonNeed(se, aid, now) {
  return ensureAuroraBudget(se, now);
}
function chargeRow(season, aid, key) {
  return db.prepare("SELECT amount, locked, secured FROM aurora_charge WHERE season = ? AND alliance_id = ? AND pylon = ?").get(season, aid, key) || { amount: 0, locked: 0, secured: 0 };
}
function setCharge(season, aid, key, amount, locked, secured) {
  db.prepare("INSERT INTO aurora_charge (season, alliance_id, pylon, amount, locked) VALUES (?, ?, ?, ?, ?) ON CONFLICT(season, alliance_id, pylon) DO UPDATE SET amount = excluded.amount, locked = excluded.locked")
    .run(season, aid, key, Math.max(0, Math.round(amount)), locked ? 1 : 0);
  if (secured !== undefined) db.prepare("UPDATE aurora_charge SET secured = MAX(secured, ?) WHERE season = ? AND alliance_id = ? AND pylon = ?").run(secured, season, aid, key);
  teamsCache.at = 0;
}

// ---------- ley lines ----------
// For every alliance: which pylons are linked to the Landing Zone, and how
// far the nearest link is from each pylon that is not linked yet.
let leyCache = { at: 0, data: null };
function leyLines(now) {
  if (leyCache.data && now - leyCache.at < 5000) return leyCache.data;
  const byAlly = new Map();
  const rows = db.prepare("SELECT colonies.x, colonies.y, alliance_members.alliance_id AS aid FROM colonies JOIN alliance_members ON alliance_members.user_id = colonies.user_id").all();
  for (const r of rows) {
    if (!byAlly.has(r.aid)) byAlly.set(r.aid, []);
    byAlly.get(r.aid).push({ x: r.x, y: r.y });
  }
  const out = new Map();
  for (const [aid, cols] of byAlly) {
    // walk from the Landing Zone outwards
    const reached = [{ x: 0, y: 0 }];
    const left = cols.slice();
    for (let i = 0; i < reached.length; i++) {
      const a = reached[i];
      for (let j = left.length - 1; j >= 0; j--) {
        if (Math.hypot(left[j].x - a.x, left[j].y - a.y) <= AURORA_LINK) reached.push(left.splice(j, 1)[0]);
      }
    }
    const pylons = {};
    for (const p of PYLONS) {
      let best = Infinity;
      for (const r of reached) best = Math.min(best, Math.hypot(r.x - p.x, r.y - p.y));
      // the colonies NOT on the line yet also tell you where the gap is
      let near = Infinity;
      for (const c of cols) near = Math.min(near, Math.hypot(c.x - p.x, c.y - p.y));
      pylons[p.key] = { linked: best <= AURORA_LINK, gap: Math.max(0, Math.ceil(best - AURORA_LINK)), nearOwn: near };
    }
    out.set(aid, { pylons, chain: reached.length - 1 });
  }
  leyCache = { at: now, data: out };
  return out;
}
function leyOf(aid, now) {
  const l = leyLines(now).get(aid);
  if (l) return l;
  const pylons = {};
  for (const p of PYLONS) pylons[p.key] = { linked: false, gap: Math.ceil(Math.hypot(p.x, p.y) - AURORA_LINK), nearOwn: Infinity };
  return { pylons, chain: 0 };
}

// ---------- standings ----------
let teamsCache = { at: 0, data: null };
function auroraTeams(se, now) {
  if (teamsCache.data && now - teamsCache.at < 5000) return teamsCache.data;
  teamsCache = { at: now, data: auroraTeamsNow(se, now) };
  return teamsCache.data;
}
function auroraTeamsNow(se, now) {
  const ids = db.prepare("SELECT DISTINCT alliance_id AS aid FROM aurora_charge WHERE season = ?").all(se.number).map((r) => r.aid);
  for (const aid of leyLines(now).keys()) if (!ids.includes(aid)) ids.push(aid);
  const z = zoneRow();
  const zoneAlly = allyIdOf(zoneHolderUser(z));
  return ids
    .filter((aid) => db.prepare("SELECT 1 FROM alliances WHERE id = ?").get(aid))
    .map((aid) => {
      const need = pylonNeed(se, aid, now);
      const ley = leyOf(aid, now);
      let charged = 0, linked = 0, pct = 0;
      for (const p of PYLONS) {
        const c = chargeRow(se.number, aid, p.key);
        if (c.locked) charged += 1;
        if (ley.pylons[p.key].linked) linked += 1;
        pct += c.locked ? 1 : Math.min(1, c.amount / need);
      }
      return { aid, name: allianceName(aid), charged, linked, zone: zoneAlly === aid, pct: Math.round((pct / PYLONS.length) * 100) };
    })
    .filter((t) => t.pct > 0 || t.linked > 0 || t.zone)
    .sort((a, b) => b.charged + b.linked + (b.zone ? 1 : 0) - (a.charged + a.linked + (a.zone ? 1 : 0)) || b.pct - a.pct);
}

// ---------- the clock: checks the ignition every 30 seconds ----------
function auroraTick() {
  const se = auroraRunning();
  if (!se) return;
  const now = Date.now();
  ensureAuroraBudget(se, now);
  leyCache.at = 0; teamsCache.at = 0;
  const aid = allyIdOf(zoneHolderUser(zoneRow()));
  const ley = aid ? leyOf(aid, now) : null;
  const ready = !!aid && PYLONS.every((p) => chargeRow(se.number, aid, p.key).locked && ley.pylons[p.key].linked);
  let ig = se.ignition;
  if (ig && ig.progressMs === undefined) {
    ig.progressMs = Math.min(se.hours * 3600000, Math.max(0, now - ig.since));
    ig.lastAt = now;
  }
  if (ready && (!ig || ig.aid !== aid)) {
    ig = se.ignition = { aid, key: "a" + aid, name: allianceName(aid), since: now, lastAt: now, progressMs: 0, pausedAt: 0 };
    addNews("⚡ " + ig.name + " began Aurora ignition. Hold the flag and all four links for " + se.hours + " hours. Interruptions pause it before progress decays.", now, "season", 24);
  }
  if (!ig) return;
  // Never award an unchecked night of progress after an offline server restart.
  const dt = Math.max(0, Math.min(90000, now - (ig.lastAt || now)));
  if (ready && ig.aid === aid) {
    if (!ig.pausedAt) ig.progressMs += dt;
    ig.pausedAt = 0;
  } else {
    if (!ig.pausedAt) {
      ig.pausedAt = now;
      addNews("⏸ " + ig.name + " lost an Aurora requirement. A short recovery window protects ignition progress, then it decays.", now, "season", 6);
    }
    const decay = Math.max(0, Math.min(dt, now - ig.pausedAt - (se.graceMs || auroraGraceMs())));
    ig.progressMs = Math.max(0, ig.progressMs - decay * 0.5);
  }
  ig.lastAt = now;
  if (ready && ig.progressMs >= se.hours * 3600000) {
    se.active = false; se.endedAt = now; se.ignition = null;
    se.winner = { key: "a" + aid, name: allianceName(aid), at: now };
    rememberRoundWinner("aurora", se.winner.key, se.winner.name, now);
    for (const m of allianceMembers(aid)) giveBadge(m.id, "aurora" + se.number, "🌌", "Lit the Aurora · won Server " + se.number, now);
    addNews("🌌 " + se.winner.name + " lit the Aurora and won the server!", now, "season", 96);
    writeSeason(se);
    freezeWonWorld();
  } else if (ig.pausedAt && ig.progressMs === 0 && now - ig.pausedAt > (se.graceMs || auroraGraceMs())) se.ignition = null;
  writeSeason(se);
}
setInterval(() => {
  try {
    auroraTick();
  } catch (e) {
    console.error("aurora:", e.message);
  }
}, 30000);

// What the game shows (in the season bar and on the map)
function auroraInfo(se, userId, now) {
  const aid = allyIdOf(userId);
  const out = {
    kind: "aurora",
    number: se.number,
    active: !!se.active,
    hours: se.hours,
    link: AURORA_LINK,
    startedAt: se.startedAt,
    winner: se.winner || null,
    myKey: aid ? "a" + aid : "u" + userId,
    inAlliance: !!aid,
    ignition: se.ignition ? { key: se.ignition.key, name: se.ignition.name, since: se.ignition.since,
      paused: !!se.ignition.pausedAt, progressMs: se.ignition.progressMs || 0,
      graceUntil: se.ignition.pausedAt ? se.ignition.pausedAt + (se.graceMs || auroraGraceMs()) : 0,
      // progress is added every 30 s by the tick, counted from lastAt: the end stays fixed between ticks
      winsAt: se.ignition.pausedAt ? null : (se.ignition.lastAt || now) + Math.max(0, se.hours * 3600000 - (se.ignition.progressMs || 0)) } : null,
    graceMs: se.graceMs || auroraGraceMs(),
    standings: se.active ? auroraTeams(se, now).slice(0, 5).map((t) => ({ key: "a" + t.aid, name: t.name, charged: t.charged, linked: t.linked, zone: t.zone, pct: t.pct })) : [],
    pylons: [],
  };
  const need = aid ? pylonNeed(se, aid, now) : 0;
  const ley = aid ? leyOf(aid, now) : null;
  const zoneAlly = allyIdOf(zoneHolderUser(zoneRow()));
  out.zoneMine = !!aid && zoneAlly === aid;
  for (const p of PYLONS) {
    const c = aid ? chargeRow(se.number, aid, p.key) : { amount: 0, locked: 0 };
    const l = ley ? ley.pylons[p.key] : null;
    out.pylons.push({ key: p.key, name: p.name, x: p.x, y: p.y, amount: c.locked ? need : Math.min(c.amount, need), need, secured: c.locked ? need : c.secured || 0, incoming: pylonIncoming(se, aid, p.key), locked: !!c.locked, linked: !!(l && l.linked), gap: l ? l.gap : null });
  }
  return out;
}

function pylonMapInfo(userId, now, targeted) {
  const se = auroraSeason();
  const run = se && se.active;
  const aid = allyIdOf(userId);
  const need = run && aid ? pylonNeed(se, aid, now) : 0;
  const ley = run && aid ? leyOf(aid, now) : null;
  return PYLONS.map((p) => {
    const o = { key: p.key, name: p.name, x: p.x, y: p.y, active: !!run, link: AURORA_LINK, targeted: targeted ? targeted.has(p.x + "|" + p.y) : false };
    if (!run) return o;
    if (aid) {
      const c = chargeRow(se.number, aid, p.key);
      Object.assign(o, { mine: true, amount: c.locked ? need : Math.min(c.amount, need), need, secured: c.locked ? need : c.secured || 0, incoming: pylonIncoming(se, aid, p.key), locked: !!c.locked, linked: ley.pylons[p.key].linked, gap: ley.pylons[p.key].gap });
    }
    // who else is charging here (public: the towers glow)
    const rows = db.prepare("SELECT alliance_id AS aid, amount, locked, secured FROM aurora_charge WHERE season = ? AND pylon = ? AND (amount > 0 OR locked = 1) ORDER BY locked DESC, amount DESC LIMIT 4").all(se.number, p.key);
    o.others = rows.filter((r) => r.aid !== aid).map((r) => ({ name: allianceName(r.aid), locked: !!r.locked, drainable: !r.locked && r.amount > (r.secured || 0), pct: r.locked ? 100 : Math.min(99, Math.floor((r.amount / pylonNeed(se, r.aid, now)) * 100)) }));
    o.ignited = !!(se.ignition && rows.some((r) => r.aid === se.ignition.aid && r.locked));
    return o;
  });
}

// ---------- charging: merchants carry resources to a pylon ----------
app.post("/api/aurora/charge", requireLogin, (req, res) => {
  withColony(req, res, (s, tribe, colony) => {
    const body = req.body || {};
    const se = auroraRunning();
    if (!se) return "Project Aurora is not running right now";
    const aid = allyIdOf(req.user.id);
    if (!aid) return "Only alliances can charge the pylons. Join or found one first!";
    const p = PYLONS.find((q) => q.key === String(body.pylon || ""));
    if (!p) return "Unknown pylon";
    if (levelOf(s, "market") === 0) return "You need a marketplace first";
    const now = Date.now();
    const c = chargeRow(se.number, aid, p.key);
    if (c.locked) return p.name + " is already fully charged for your alliance";
    const goods = {};
    let total = 0;
    for (const r of RESOURCES) {
      const n = Number((body.res || {})[r] || 0);
      if (!Number.isSafeInteger(n) || n < 0) return "Invalid amount";
      if (n > Math.floor(s.res[r])) return "You don't have that much " + r;
      goods[r] = n;
      total += n;
    }
    if (!total) return "Put something on the camels first";
    const remaining = Math.max(0, pylonNeed(se, aid, now) - c.amount - pylonIncoming(se, aid, p.key));
    if (total > remaining) return "Only " + remaining.toLocaleString("en-US") + " resources are still needed after incoming deliveries. Refresh and use Fill in.";
    const need = Math.ceil(total / merchantCarry(s));
    const free = merchantsFree(s, colony.id);
    if (need > free) return "You need " + need + " merchants but only " + free + " are free";
    pay(s, goods);
    const trip = merchantTrip(colony, p.x, p.y, now);
    const ins = db.prepare(
      `INSERT INTO movements (attacker_id, target_id, mission, troops, depart_at, arrive_at, return_at, phase, next_at,
                              target_kind, target_x, target_y, loot, merchants, aurora_meta)
       VALUES (?, 0, 'trade', '{}', ?, ?, ?, 'out', ?, 'pylon', ?, ?, ?, ?, ?)`
    ).run(colony.id, now, now + trip, now + 2 * trip, now + trip, p.x, p.y, JSON.stringify(goods), need, JSON.stringify({ season: se.number, aid }));
    return null;
  });
});

function resolvePylonCharge(m) {
  const T = m.arrive_at;
  const cache = colonyCache(T);
  const from = cache.get(m.attacker_id);
  const goods = m.loot ? JSON.parse(m.loot) : null;
  const p = pylonAtXY(m.target_x, m.target_y);
  const se = auroraRunning();
  const total = goods ? RESOURCES.reduce((n, r) => n + goods[r], 0) : 0;
  let used = 0;
  let text = "";
  const aid = from ? allyIdOf(from.userId) : 0;
  let meta = null;
  try { meta = JSON.parse(m.aurora_meta || "null"); } catch (e) {}
  const valid = se && (meta ? meta.season === se.number && meta.aid === aid : m.depart_at >= se.startedAt);
  if (from && p && se && aid && total && valid) {
    const need = pylonNeed(se, aid, T);
    const c = chargeRow(se.number, aid, p.key);
    if (!c.locked) {
      used = Math.max(0, Math.min(total, need - c.amount));
      const level = c.amount + used;
      const locked = level >= need;
      setCharge(se.number, aid, p.key, level, locked, locked ? need : Math.floor(Math.floor(level / need * 4) * need / 4));
      text = locked ? "⚡ " + p.name + " is FULLY CHARGED and locked for your alliance!" : p.name + " is now at " + Math.floor((level / need) * 100) + "%.";
      if (locked) {
        for (const mem of allianceMembers(aid)) if (mem.id !== from.userId) addReport(mem.id, T, "⚡", tt("{0} charged", shortColonyName(p.name)), { mission: "aurora", flavor: usernameOf(from.userId) + " delivered the last load. Your alliance's " + p.name + " can't be drained anymore." });
      }
    } else text = p.name + " was already full.";
  } else text = !se ? "Project Aurora is over." : !aid ? "You are not in an alliance anymore." : !valid ? "This shipment belongs to a different alliance or Aurora round." : "Delivery could not be accepted.";
  // what was too much goes back home (as far as the storage allows)
  const back = {};
  if (from && goods) {
    let skip = used;
    for (const r of RESOURCES) {
      const take = Math.min(goods[r], skip);
      skip -= take;
      back[r] = goods[r] - take;
    }
    // Unused cargo travels home with the same merchants; no instant refund.
  }
  if (from) {
    addReport(from.userId, T, "🗼", tt("Charged {0} with {1}", p ? shortColonyName(p.name) : "pylon", used.toLocaleString("en-US")), {
      mission: "aurora",
      side: "sender",
      attacker: colonyInfo(from),
      defender: { name: "🗼 " + (p ? p.name : "Pylon"), x: m.target_x, y: m.target_y },
      goods,
      used,
      returned: back, returnAt: m.return_at,
      flavor: text + (used < total ? " Unused cargo is travelling home with the merchants." : ""),
    });
  }
  cache.saveAll();
  db.prepare("UPDATE movements SET loot = ?, phase = 'back', next_at = return_at WHERE id = ?").run(lootTotal(back) ? JSON.stringify(back) : null, m.id);
}

// ---------- sabotage: a raid drains another alliance's unfinished charge ----------
function pylonSendCheck(p, mission, userId) {
  const se = auroraRunning();
  if (!se) return "The pylons sleep. They only wake up during Project Aurora.";
  if (mission !== "raid") return "Send a Raid to drain an enemy's charge (charge your own with merchants)";
  const aid = allyIdOf(userId);
  const victims = db.prepare("SELECT alliance_id AS aid FROM aurora_charge WHERE season = ? AND pylon = ? AND locked = 0 AND amount > secured").all(se.number, p.key).filter((r) => r.aid !== aid);
  if (!victims.length) return "There is no unfinished enemy charge at " + p.name + " to drain";
  return null;
}

function resolvePylonRaid(m) {
  const T = m.arrive_at;
  const cache = colonyCache(T);
  const att = cache.get(m.attacker_id);
  if (!att) { db.prepare("DELETE FROM movements WHERE id = ?").run(m.id); return; }
  const tribe = tribeOf(att.tribe);
  const troops = JSON.parse(m.troops);
  const p = pylonAtXY(m.target_x, m.target_y);
  const se = auroraRunning();
  const aid = allyIdOf(att.userId);
  let loot = null;
  let victim = null;
  let drained = 0;
  if (p && se) {
    const rows = db.prepare("SELECT alliance_id AS aid, amount, secured FROM aurora_charge WHERE season = ? AND pylon = ? AND locked = 0 AND amount > secured ORDER BY amount DESC").all(se.number, p.key).filter((r) => r.aid !== aid);
    if (rows.length) {
      victim = rows[0];
      const cap = Math.round(pylonNeed(se, victim.aid, T) * AURORA_DRAIN_SHARE);
      drained = Math.max(0, Math.min(victim.amount - (victim.secured || 0), cap, carryOf(troops, tribe)));
      setCharge(se.number, victim.aid, p.key, victim.amount - drained, false);
      // the stolen energy turns back into resources: evenly split
      loot = { wood: 0, stone: 0, metal: 0, food: 0 };
      RESOURCES.forEach((r, i) => { loot[r] = Math.floor(drained / 4) + (i < drained % 4 ? 1 : 0); });
      addStats(att.userId, { loot: drained });
      const vName = allianceName(victim.aid);
      for (const mem of allianceMembers(victim.aid)) {
        addReport(mem.id, T, "🔌", tt("{0} drained", shortColonyName(p.name)), {
          mission: "aurora",
          flavor: usernameOf(att.userId) + " drained " + drained.toLocaleString("en-US") + " from your alliance's charge. Charge milestones at 25%, 50% and 75% protect banked resources; a full pylon is safe.",
        });
      }
      victim.name = vName;
    }
  }
  addReport(att.userId, T, drained ? "🔌" : "💨", drained ? tt("Drained {0} at {1}", drained.toLocaleString("en-US"), shortColonyName(p.name)) : "Nothing to drain", {
    mission: "meteor",
    drain: true,
    side: "attacker",
    attacker: Object.assign({}, colonyInfo(att), { units: unitList(troops, tribe, null) }),
    defender: { name: "🗼 " + (p ? p.name : "Pylon"), x: m.target_x, y: m.target_y },
    loot,
    carry: carryOf(troops, tribe),
    flavor: drained ? "Your troops pulled the cables. " + victim.name + " won't be happy." : "Somebody locked it, or nobody was charging it anymore.",
  });
  cache.saveAll();
  finishArrival(m, troops, loot);
}

// ---------- the owner starts / stops it ----------
function startAurora(b) {
  const old = readSeason();
  if (old && old.active) return "A server goal is already running";
  const hours = Math.max(1, Math.min(168, parseInt(b.hours, 10) || auroraDefaultHours()));
  const charge = Math.max(1, Math.min(72, parseInt(b.charge, 10) || AURORA_CHARGE_HOURS));
  const now = Date.now();
  const se = { kind: "aurora", number: (old ? old.number || 0 : 0) + 1, active: true, hours, charge, startedAt: now, ignition: null, winner: null, pylonBudget: auroraBudget(now, charge), rulesVersion: 2, graceMs: auroraGraceMs() };
  writeSeason(se);
  addNews("🌌 Project Aurora begins! Charge the 4 pylons, link them to the Landing Zone and hold the flag for " + hours + "h to win the server.", now, "season", 48);
  return null;
}
app.post("/api/admin/aurora/start", requireOwner, (req, res) => {
  const err = startAurora(req.body || {});
  if (err) return res.status(400).json({ error: err });
  res.json({ ok: true });
});

// =====================================================================
//  🗓️ THE SERVER CLOCK
//  "Server day" 1 is the day the server was created. The landmarks open,
//  the Relic Hunt and finally Project Aurora begin on fixed server days
//  (see serverDayMs for how long a day is at each game speed).
//  Winning Project Aurora wins the server. The owner can move the days.
// =====================================================================
const SERVER_CLOCK_DEFAULT = THIS_PRESET.clock || { landmarks: 30, relic: 250, aurora: 340 };
// A day lasts 24 real hours at normal speed (x1), so "day 340" on the Classic
// server is real day 340. Faster servers get shorter days, but only with the
// square root of the speed, so a faster round is still a faster round without
// the big events rushing past. The event days below are the days at x1: a round
// at speed s lasts that many days divided by the square root of s.
const CLOCK_REF_SPEED = 1;
// "24 h": the length of a day in real hours, for texts
function dayTxt() {
  const h = serverDayMs() / 3600000;
  return (h < 10 ? Math.round(h * 10) / 10 : Math.round(h)) + " h";
}
// a short real date for a server day, for texts
function dayDate(day) {
  const an = clockAnchor();
  return new Date(an.t + (day - 1 - an.d) * serverDayMs()).toLocaleDateString("en-GB", { day: "numeric", month: "short", timeZone: SERVER_TZ });
}
function serverDayMs() {
  return Math.round(86400000 * Math.sqrt(CLOCK_REF_SPEED / Math.max(1, PRODUCTION_SPEED)));
}
// How long a server day is next to 24 real hours (1 on Classic, about 0.04 on Speed).
// Real-hour rules (relic hold time, auctions) are multiplied by it so every game speed
// gets the same pacing; players always see the result as real time.
function dayScale() { return serverDayMs() / 86400000; }
function scaleHours(h, min) { return Math.max(min || 0.05, Math.round(h * dayScale() * 100) / 100); }
// 0.5 -> "30 min", 1 -> "1 h", 2.5 -> "2.5 h"
function hrTxt(h) {
  if (h < 1) return Math.max(1, Math.round(h * 60)) + " min";
  return (Math.round(h * 10) / 10) + " h";
}
// Until 1.0.370 a day was this much longer. Rules that are not "once per day" keep
// their old real-time length by measuring in these long days (offers, notices, trader life ...).
const DAY_K = Math.sqrt(10);
function holdDayMs() { return Math.round(serverDayMs() * DAY_K); }
// The clock stood at day "d" (fractional, 0 = start) at time "t". A speed change
// sets a new anchor, so the days never jump.
function clockAnchor() {
  const row = db.prepare("SELECT value FROM settings WHERE key = 'clock_anchor'").get();
  try { if (row) { const a = JSON.parse(row.value); if (a && a.t > 0) return a; } } catch (e) {}
  return { t: serverStartAt(), d: 0 };
}
function clockReanchor(now) {
  const a = clockAnchor();
  const d = a.d + (now - a.t) / serverDayMs();
  db.prepare("INSERT INTO settings (key, value) VALUES ('clock_anchor', ?) ON CONFLICT (key) DO UPDATE SET value = excluded.value").run(JSON.stringify({ t: now, d }));
}
function clockRestartNow(now) {
  db.prepare("DELETE FROM settings WHERE key = 'clock_anchor'").run();
  db.prepare("INSERT INTO settings (key, value) VALUES ('server_start', ?) ON CONFLICT (key) DO UPDATE SET value = excluded.value").run(String(now));
}
function serverStartAt() {
  const row = db.prepare("SELECT value FROM settings WHERE key = 'server_start'").get();
  if (row && Number(row.value) > 0) return Number(row.value);
  const now = Date.now();
  db.prepare("INSERT INTO settings (key, value) VALUES ('server_start', ?) ON CONFLICT (key) DO UPDATE SET value = excluded.value").run(String(now));
  return now;
}
function clockDays() {
  const row = db.prepare("SELECT value FROM settings WHERE key = 'server_clock'").get();
  let c = {};
  try { c = row ? JSON.parse(row.value) : {}; } catch (e) {}
  const out = {};
  for (const k in SERVER_CLOCK_DEFAULT) out[k] = Number(c[k]) > 0 ? Number(c[k]) : SERVER_CLOCK_DEFAULT[k];
  return out;
}
// 🎭 the round as six acts. Each one changes one rule.
const ACTS = [
  { key: "landing", icon: "🛬", name: "Landing", rule: "Beginner protection and the first rich sites." },
  { key: "expansion", icon: "🏗️", name: "Expansion", rule: "Colony specialisations can be chosen." },
  { key: "discovery", icon: "🗿", name: "Discovery", rule: "Landmarks open. Monster camps level up: +25% monsters and bounty. Hunt luck ×1.25." },
  { key: "storm", icon: "⚡", name: "Storm Season", rule: "Ion storms join the weather, meteor crates can hold commander gear and a Dust Titan appears now and then. Monster camps: +50%. Hunt luck ×1.5." },
  { key: "relic", icon: "🏆", name: "Relic Hunt", rule: "Three Relic Hunts: each one stronger, the last reaches the whole alliance. Monster camps: +75%. Hunt luck ×1.75." },
  { key: "aurora", icon: "🌌", name: "Aurora", rule: "The race for the Aurora. Monster camps level up again: +100%. Hunt luck ×2." },
];
// the three Relic Hunts: the first on the Relic Hunt day, the others a third and two thirds of the way to the Aurora
function huntDays() {
  const d = clockDays();
  const gap = Math.max(3, d.aurora - d.relic);
  return [d.relic, Math.round(d.relic + gap / 3), Math.round(d.relic + (gap * 2) / 3)];
}
function actDays() {
  const d = clockDays();
  // the Storm Season starts 40% of the way from the landmarks to the Relic Hunt
  const storm = Math.min(d.relic - 1, Math.max(d.landmarks + 1, Math.round(d.landmarks + (d.relic - d.landmarks) * 0.4)));
  return [1, Math.max(2, Math.min(4, Math.round(d.landmarks / 3))), d.landmarks, storm, d.relic, d.aurora];
}
function actAt(day) {
  const ds = actDays();
  let i = 0;
  for (let k = 0; k < ds.length; k++) if (day >= ds[k]) i = k;
  return i;
}
function actNow(now) {
  return actAt(clockDayNow(now));
}
function actsView(now) {
  const c = serverClock(), ds = actDays(), i = actAt(c.day);
  const an = clockAnchor(), dm = serverDayMs();
  return { now: i, list: ACTS.map((a, k) => ({ key: a.key, icon: a.icon, name: a.name, rule: a.rule, day: ds[k], at: Math.round(an.t + (ds[k] - 1 - an.d) * dm) })) };
}
// camps level up with the acts: +25% Discovery, +50% Storm Season, +75% Relic Hunt, +100% Aurora
function campActMult() {
  return [1, 1, 1.25, 1.5, 1.75, 2][actNow()] || 1;
}
// 🍀 hunt luck grows with every act the way the camps do (×1 to ×2): rarer creatures and shinies show up more often,
// and more opponents come while you are away (+5 points per act from Discovery on)
function huntLuck() { return campActMult(); }
const HUNT_SPAWN_ACT = [0, 0, 0.05, 0.1, 0.15, 0.2];
function huntSpawnBonus() { return HUNT_SPAWN_ACT[actNow()] || 0; }
function shinyChances(base) { const l = huntLuck(); return base.map((x) => x * l); }

// what the game (and the guide) shows
function serverClock() {
  const start = serverStartAt();
  const days = clockDays();
  const now = Date.now();
  const an = clockAnchor();
  const dm = serverDayMs();
  const mk = (day) => ({ day, at: Math.round(an.t + (day - 1 - an.d) * dm) });
  const ev = { landmarks: mk(days.landmarks), relic: mk(days.relic), aurora: mk(days.aurora) };
  return { day: Math.floor(an.d + (now - an.t) / dm) + 1, start, dayMs: dm, origin: Math.round(an.t - an.d * dm), events: ev };
}
function clockDoneRead() {
  const row = db.prepare("SELECT value FROM settings WHERE key = 'server_clock_done'").get();
  try { return row ? JSON.parse(row.value) : {}; } catch (e) { return {}; }
}
function scheduleTick() {
  const clock = serverClock();
  const now = Date.now();
  const done = clockDoneRead();
  let changed = false;
  const mark = (k) => { done[k] = now; changed = true; };
  if (!done.landmarks && now >= clock.events.landmarks.at) {
    if (!landmarksOpen()) {
      setLandmarksOpen(true);
      seasonCache = null;
      addNews("🗿 The landmarks of Mars are open! Claim them for big bonuses.", now, "server", 24);
    }
    mark("landmarks");
  }
  if (!done.relic && now >= clock.events.relic.at) {
    const se = readSeason();
    if ((se?.active && se.kind === "relic") || !startRelicHunt({})) mark("relic");
  }
  // Hunts II and III: a running hunt that nobody is winning closes, a streak gets to finish
  const hd = huntDays();
  const dayAt = (day) => Math.round(clock.events.relic.at + (day - hd[0]) * clock.dayMs);
  for (let h = 2; h <= 3; h++) {
    const key = "hunt" + h;
    if (done[key] || !done.relic || now < dayAt(hd[h - 1])) continue;
    const se = readSeason();
    if (se && se.active && se.kind === "relic") {
      if (se.streak) continue; // the leaders may finish their 24h first
      stopSeasonKind("relic", now);
    }
    if (!startRelicHunt({ hunt: h })) mark(key);
  }
  if (!done.aurora && now >= clock.events.aurora.at) {
    const se = readSeason();
    if (se && se.active && se.kind === "relic") {
      const earliest = se.startedAt + Math.max(7 * 86400000, se.hours * 3600000);
      if (now >= earliest && !se.streak) {
        stopSeasonKind("relic", now);
        addNews("The Relic Hunt has closed. Project Aurora is opening.", now, "season", 48);
        if (!startAurora({})) mark("aurora");
      }
    } else if ((se?.active && se.kind === "aurora") || !startAurora({})) mark("aurora");
  }
  if (changed) db.prepare("INSERT INTO settings (key, value) VALUES ('server_clock_done', ?) ON CONFLICT (key) DO UPDATE SET value = excluded.value").run(JSON.stringify(done));
}
serverStartAt();
setInterval(() => {
  try { scheduleTick(); } catch (e) { console.error("clock:", e.message); }
}, 30000);
app.get("/api/admin/clock", requireOwner, (req, res) => {
  res.json({ clock: serverClock(), days: clockDays(), done: clockDoneRead() });
});
// body: { landmarks, relic, aurora (days), restart?: true }
app.post("/api/admin/clock", requireOwner, (req, res) => {
  const b = req.body || {};
  const days = {};
  for (const k in SERVER_CLOCK_DEFAULT) {
    const v = Math.round(Number(b[k]));
    days[k] = Number.isFinite(v) && v >= 1 && v <= 400 ? v : clockDays()[k];
  }
  if (!(days.landmarks <= days.relic && days.relic <= days.aurora)) return res.status(400).json({ error: "Order must be: landmarks, then Relic Hunt, then Aurora" });
  const put = (k, v) => db.prepare("INSERT INTO settings (key, value) VALUES (?, ?) ON CONFLICT (key) DO UPDATE SET value = excluded.value").run(k, v);
  put("server_clock", JSON.stringify(days));
  if (b.restart) { clockRestartNow(Date.now()); put("server_clock_done", "{}"); }
  else {
    // days that lie in the future can fire again
    const done = clockDoneRead();
    const c = serverClock();
    for (const k in done) if (c.events[k] && c.events[k].at > Date.now()) delete done[k];
    put("server_clock_done", JSON.stringify(done));
  }
  res.json({ ok: true });
});

// =====================================================================
//  "📖" GUIDE - everything the help pages show, straight from the rules
//  above (so the guide never tells a different story than the game).
//  Times and speeds are in REAL time for this server's speed settings.
// =====================================================================
app.get("/api/wiki", requireLogin, (req, res) => {
  const realSec = (s) => Math.round(s / BUILD_SPEED); // base build/training seconds
  const perHour = (v) => Math.round(v * PRODUCTION_SPEED);
  const tribes = Object.keys(TRIBES).map((key) => {
    const t = TRIBES[key];
    return {
      key, name: t.name, icon: t.icon, desc: t.desc, color: t.color, perks: tribePerkList(key),
      perk: Object.fromEntries(Object.keys(PERK_DEFAULT).map((p) => [p, perkOf(key, p)])),
      bdef: Object.fromEntries(Object.keys(BUILDING_TYPES).map((b) => [b, tribeBuilding(key, b)])),
      bperks: Object.fromEntries(Object.keys(BUILDING_TYPES).map((b) => [b, buildingPerks(b, key)])),
      names: Object.fromEntries(Object.keys(t.names).map((b) => [b, { name: t.names[b][0], icon: t.names[b][1] }])),
      units: Object.keys(t.units).map((k) => {
        const u = t.units[k];
        return {
          key: k, name: u.name, icon: u.icon, role: u.role, trait: traitOf(u), type: u.type, atk: u.atk, defG: u.defG, defA: u.defA,
          speed: Math.round(u.speed * MOVE_SPEED), carry: Math.round(u.carry), upkeep: Math.round(u.upkeep * 10) / 10, cost: u.cost, time: realSec(u.time),
          building: u.building, level: u.level, lab: u.lab, quote: u.quote,
          scout: isScout(u), siege: isSiege(u), settler: isSettler(u),
        };
      }),
    };
  });
  const buildings = Object.keys(BUILDING_TYPES).map((k) => {
    const b = BUILDING_TYPES[k];
    return { key: k, info: b.info, requires: b.requires, max: b.max || MAX_LEVEL, multi: !!b.multi, field: b.field || null, cost: b.cost, time: realSec(b.time) };
  });
  const levels = (n, f) => Array.from({ length: n }, (_, i) => f(i + 1));
  res.json({
    version: GAME_VERSION, stage: GAME_STAGE, serverName: thisServerName(),
    speeds: { production: PRODUCTION_SPEED, build: BUILD_SPEED, move: MOVE_SPEED },
    clock: serverClock(),
    myTribe: (loadColony(req.colonyId) || {}).tribe || "human",
    tribes,
    buildings,
    fields: {
      types: Object.keys(FIELD_TYPES).map((k) => ({ key: k, info: FIELD_TYPES[k].info, cost: FIELD_TYPES[k].cost })),
      max: MAX_LEVEL, mainMax: MAIN_FIELD_MAX, perLevel: Math.round((PROD_GROWTH - 1) * 100),
      prod: levels(MAIN_FIELD_MAX, (l) => perHour(fieldProduction(l))),
      layout: { wood: 3, stone: 3, metal: 2, food: 4 },
    },
    storage: { scale: 1, base: capacityAt(0), levels: levels(maxLevelOf("warehouse"), (l) => capacityAt(l)),
      metal: levels(maxLevelOf("warehouse"), (l) => capacityAt(l, "metal")),
      food: levels(maxLevelOf("granary"), (l) => capacityAt(l, "food")),
      starting: { wood: capacityAt(0), metal: capacityAt(0, "metal"), food: capacityAt(0, "food") },
      bunker: levels(MAX_LEVEL, bunkerAt), secondAt: maxLevelOf("warehouse"), bunkerSecondAt: SECOND_BUILDING_LEVEL },
    boosters: { per: Math.round(BOOST_PER_LEVEL * 100), max: BOOST_MAX },
    combat: {
      traits: UNIT_TRAITS, moraleMax: Math.round(MORALE_MAX * 100),
      luck: Math.round(LUCK * 100), wall: WALL_BONUS, upgrade: Math.round(UPGRADE_BONUS * 100), upgradeMax: UPGRADE_MAX,
      combo: Math.round(COMBINED_ARMS_BONUS * 100), comboShare: Math.round(COMBINED_ARMS_SHARE * 100),
      militiaBase: MILITIA_BASE, militiaPerHq: MILITIA_PER_HQ, ramPerLevel: RAM_PER_WALL_LEVEL,
      hospital: Math.round(HOSPITAL_RATE * 100), beds: HOSPITAL_BEDS, heal: Math.round(HEAL_COST * 100),
      cancel: Math.round(CANCEL_WINDOW_MS / 1000), 
      spyDetect: SPY_DETECT, spyWipe: SPY_WIPE, research: RESEARCH_COST,
    },
    codexTiers: CODEX_TIERS, codexCampTiers: CODEX_CAMP_TIERS,
    monsters: Object.keys(MONSTERS).map((k) => Object.assign({ key: k }, MONSTERS[k], { bounty: Object.fromEntries(RESOURCES.map((r) => [r, Math.round((MONSTERS[k].bounty[r] || 0) * campBountyScale())])) })),
    campScale: 1, campLoot: campLootScale(), campTrophy: campBountyScale(),
    camps: CAMP_TIERS.map((t, i) => ({ tier: i + 1, maxDist: t.maxDist === Infinity ? null : t.maxDist, kinds: t.kinds.map((c) => {
      const k = 1;
      const units = {}, treasure = {};
      for (const u in c.units) units[u] = c.units[u].map((n) => Math.max(1, Math.round(n * k)));
      for (const r in c.treasure) treasure[r] = Math.round(c.treasure[r] * campLootScale());
      return { name: c.name, icon: c.icon, units, treasure };
    }) })),
    campRegrow: CAMP_REGROW_HOURS, campTreasure: CAMP_TREASURE_HOURS,
    landmarks: LANDMARKS.map((l) => ({ icon: l.icon, name: l.name, x: landmarksOpen() ? l.x : null, y: landmarksOpen() ? l.y : null, bonus: l.bonus.text, guards: Math.round(l.guards * LANDMARK_GUARD_SCALE * speedScale()) })),
    landmarkRange: LANDMARK_RANGE, landmarkRangePer: LANDMARK_RANGE_PER_LEVEL, landmarkDef: Math.round(LANDMARK_DEF_BONUS * 100),
    zone: { prod: Math.round(ZONE_PROD_BONUS * 100), def: Math.round(ZONE_DEF_BONUS * 100), robots: zoneRobots() },
    terrain: Object.keys(TERRAIN).filter((k) => k !== "l").map((k) => ({ key: k, name: TERRAIN[k].name, icon: TERRAIN[k].icon, buildable: TERRAIN[k].buildable, info: TERRAIN[k].info })),
    colonies: { max: null, settlers: SETTLERS_NEEDED, hubLevel: SETTLER_HUB_LEVEL, terra: levels(14, terraNeededFor) },
    terraProjects: Object.keys(TERRA_PROJECTS).map((k) => { const p = TERRA_PROJECTS[k]; return { name: p.name, icon: p.icon, hub: p.hub, terra: p.terra, cost: p.cost }; }),
    perkDefault: PERK_DEFAULT,
    market: { perLevel: MERCHANTS_PER_LEVEL, carry: MERCHANT_CARRY, speed: Math.round(MERCHANT_SPEED * MOVE_SPEED), swapBase: Math.round(SWAP_RATE_BASE * 100), swapPer: Math.round(SWAP_RATE_PER_LEVEL * 100) },
    protection: { hours: protectionHours(), points: protectionPoints(), extendHours: Math.round(protectionHours() * PROT_EXTEND_SHARE * 10) / 10, dayHours: Math.round(serverDayMs() / 360000) / 10 },
    alliance: {
      maxMembers: ALLIANCE_MAX_MEMBERS, maxLevel: ALLY_MAX_LEVEL, growth: ALLY_LEVEL_GROWTH,
      projects: Object.keys(ALLY_PROJECTS).map((k) => { const p = ALLY_PROJECTS[k]; return { key: k, icon: p.icon, name: p.name, levels: levels(ALLY_MAX_LEVEL, (l) => allyProjText(k, l)), hours: levels(ALLY_MAX_LEVEL, (l) => Math.round(p.costHours * Math.pow(ALLY_LEVEL_GROWTH, l - 1) * 10) / 10) }; }),
    },
    events: Object.keys(EVENT_KINDS).map((k) => Object.assign({ key: k }, EVENT_KINDS[k])),
    aurora: { link: AURORA_LINK, charge: AURORA_CHARGE_HOURS, ignite: auroraDefaultHours(), drain: Math.round(AURORA_DRAIN_SHARE * 100), pylons: PYLONS.map((p) => ({ name: p.name, x: p.x, y: p.y })) },
    relic: { count: RELIC_HUNT_COUNT, hours: relicHoursDefault() },
    auction: { fee: Math.round(AUCTION_FEE * 100), hours: auctionHours(), maxActive: AUCTION_MAX_ACTIVE, step: Math.round(AUCTION_STEP * 100), snipeMs: auctionSnipeMs() },
    extra: wikiExtra(),
    tables: wikiTables(),
    formulas: {
      costGrowth: COST_GROWTH, timeGrowth: TIME_GROWTH, prodGrowth: PROD_GROWTH, fieldCostHigh: FIELD_COST_GROWTH_HIGH, fieldTimeHigh: FIELD_TIME_GROWTH_HIGH,
      capGrowth: CAPACITY_GROWTH, hq: HQ_SPEEDUP, barracks: BARRACKS_SPEEDUP, hangar: HANGAR_SPEEDUP, workshop: WORKSHOP_SPEEDUP, lab: LAB_SPEEDUP, weaponry: WEAPONRY_SPEEDUP,
      upCost: UPGRADE_COST, upCostGrowth: UPGRADE_COST_GROWTH, upTime: UPGRADE_TIME, upTimeGrowth: UPGRADE_TIME_GROWTH, researchTime: RESEARCH_TIME,
      terraPerPoint: TERRA_PER_POINT, terraHubBase: TERRA_HUB_BASE, terraHubCurve: TERRA_HUB_CURVE, terraZone: TERRA_ZONE_BONUS, terraBase: TERRA_BASE, terraExp: TERRA_EXP,
      boostCostGrowth: BOOST_COST_GROWTH, merchantSpeed: MERCHANT_SPEED, gravity: GRAVITY_BONUS,
      ally: Object.fromEntries(Object.keys(ALLY_PROJECTS).map((k) => [k, ALLY_PROJECTS[k].per])),
    },
  });
});

// Cost, time and effect of every level (times at HQ level 1, no bonuses)
let wikiTablesCache = null;
function wikiTables() {
  if (wikiTablesCache && wikiTablesCache.speed === BUILD_SPEED + "|" + PRODUCTION_SPEED) return wikiTablesCache.data;
  const plain = { buildings: [], fields: [], main: true };
  const out = { buildings: {}, fields: {} };
  // one table per tribe: the tribes build a little differently
  for (const tk of Object.keys(TRIBES)) {
    const st = { buildings: [], fields: [], main: true };
    Object.defineProperty(st, "_tribe", { value: tk, enumerable: false });
    out.buildings[tk] = {};
    for (const k of Object.keys(BUILDING_TYPES)) {
      const b = BUILDING_TYPES[k];
      const rows = [];
      for (let l = 1; l <= (b.max || MAX_LEVEL); l++) {
        rows.push({ level: l, cost: buildingCost(st, k, l), ms: buildingDuration(st, k, l), effect: effectText(k, l, tk) });
      }
      out.buildings[tk][k] = rows;
    }
  }
  for (const k of Object.keys(FIELD_TYPES)) {
    const rows = [];
    for (let l = 1; l <= MAIN_FIELD_MAX; l++) rows.push({ level: l, cost: fieldCost(k, l), ms: fieldDuration(plain, k, l), prod: Math.round(fieldProduction(l) * PRODUCTION_SPEED) });
    out.fields[k] = rows;
  }
  wikiTablesCache = { speed: BUILD_SPEED + "|" + PRODUCTION_SPEED, data: out };
  return out;
}


// =====================================================================
//  📌 PERSONAL MAP MARKERS - only you see them
// =====================================================================
const MARK_ICONS = ["📌", "⭐", "⚔️", "💰", "🛡️", "❗", "❓", "🎯"];
const MARKS_MAX = 60;
db.exec(`
  CREATE TABLE IF NOT EXISTS map_marks (
    user_id INTEGER NOT NULL, x INTEGER NOT NULL, y INTEGER NOT NULL,
    icon TEXT NOT NULL, label TEXT NOT NULL DEFAULT '', at INTEGER NOT NULL,
    PRIMARY KEY (user_id, x, y)
  );
`);
function marksOf(userId) {
  return db.prepare("SELECT x, y, icon, label, at FROM map_marks WHERE user_id = ? ORDER BY at DESC").all(userId);
}
app.post("/api/marks", requireLogin, (req, res) => {
  const b = req.body || {};
  const x = parseInt(b.x, 10), y = parseInt(b.y, 10);
  if (!Number.isInteger(x) || !Number.isInteger(y) || Math.abs(x) > MAP_RADIUS || Math.abs(y) > MAP_RADIUS) return res.status(400).json({ error: "That tile is not on the map" });
  if (b.remove) {
    db.prepare("DELETE FROM map_marks WHERE user_id = ? AND x = ? AND y = ?").run(req.user.id, x, y);
    return res.json({ ok: true, marks: marksOf(req.user.id) });
  }
  const icon = MARK_ICONS.includes(b.icon) ? b.icon : "📌";
  const label = String(b.label || "").replace(/[\u0000-\u001f]/g, "").trim().slice(0, 40);
  const exists = db.prepare("SELECT 1 FROM map_marks WHERE user_id = ? AND x = ? AND y = ?").get(req.user.id, x, y);
  if (!exists && db.prepare("SELECT COUNT(*) AS n FROM map_marks WHERE user_id = ?").get(req.user.id).n >= MARKS_MAX) return res.status(400).json({ error: "You have " + MARKS_MAX + " markers. Delete an old one first." });
  db.prepare("INSERT INTO map_marks (user_id, x, y, icon, label, at) VALUES (?, ?, ?, ?, ?, ?) ON CONFLICT(user_id, x, y) DO UPDATE SET icon = excluded.icon, label = excluded.label").run(req.user.id, x, y, icon, label, Date.now());
  res.json({ ok: true, marks: marksOf(req.user.id) });
});

// =====================================================================
//  🗂️ COLONY GROUPS - private labels and colours for my own colonies
//  Only the player sees them (nobody else gets this data).
// =====================================================================
const GROUP_COLORS = ["#e5484d", "#f08c00", "#e5c100", "#3fae49", "#16a3a3", "#3a7bd5", "#7a5af8", "#d6409f", "#8a6a4f", "#6b7280"];
const GROUPS_MAX = 12;
function colGroupsOf(userId) {
  const row = db.prepare("SELECT col_groups FROM users WHERE id = ?").get(userId);
  let g = {};
  try { g = row ? JSON.parse(row.col_groups) : {}; } catch (e) {}
  const mine = new Set(coloniesOf(userId).map((c) => c.id));
  const groups = (Array.isArray(g.groups) ? g.groups : []).filter((x) => x && x.id && x.name).slice(0, GROUPS_MAX);
  const ids = new Set(groups.map((x) => x.id));
  const map = {};
  for (const k in g.map || {}) if (mine.has(Number(k)) && ids.has(g.map[k])) map[k] = g.map[k];
  const order = (Array.isArray(g.order) ? g.order : []).map(Number).filter((id) => mine.has(id));
  return { groups, map, colors: GROUP_COLORS, order }; // order: the player's own colony order (dragged in the list)
}
app.post("/api/colgroups", requireLogin, (req, res) => {
  const b = req.body || {};
  const groups = [];
  const seen = new Set();
  for (const x of Array.isArray(b.groups) ? b.groups.slice(0, GROUPS_MAX) : []) {
    const id = String((x && x.id) || "").replace(/[^a-z0-9]/gi, "").slice(0, 12);
    const name = String((x && x.name) || "").replace(/[\u0000-\u001f]/g, "").trim().slice(0, 20);
    if (!id || !name || seen.has(id)) continue;
    seen.add(id);
    groups.push({ id, name, color: GROUP_COLORS.includes(x.color) ? x.color : GROUP_COLORS[groups.length % GROUP_COLORS.length] });
  }
  const mine = new Set(coloniesOf(req.user.id).map((c) => c.id));
  const map = {};
  for (const k in b.map || {}) if (mine.has(Number(k)) && seen.has(b.map[k])) map[k] = b.map[k];
  const order = [...new Set((Array.isArray(b.order) ? b.order : []).map(Number))].filter((id) => mine.has(id));
  db.prepare("UPDATE users SET col_groups = ? WHERE id = ?").run(JSON.stringify({ groups, map, order }), req.user.id);
  res.json({ ok: true, colGroups: colGroupsOf(req.user.id) });
});

// =====================================================================
//  🛠️ ADMIN TOOLS - events that really reset, the world, the whole server
// =====================================================================
db.exec("CREATE TABLE IF NOT EXISTS admin_log (id INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER NOT NULL, who TEXT NOT NULL, text TEXT NOT NULL)");
function adminLog(req, text) {
  db.prepare("INSERT INTO admin_log (at, who, text) VALUES (?, ?, ?)").run(Date.now(), req && req.user ? req.user.username : "system", text);
  db.prepare("DELETE FROM admin_log WHERE id < (SELECT MAX(id) FROM admin_log) - 300").run();
}
function settingOf(key, dflt) {
  const row = db.prepare("SELECT value FROM settings WHERE key = ?").get(key);
  return row ? row.value : dflt;
}
function maintenanceOn() {
  return settingOf("maintenance", "0") === "1";
}
function registrationClosed() {
  return settingOf("reg_closed", "0") === "1";
}
// typed confirmation for dangerous buttons
function confirmed(req, word) {
  return String((req.body || {}).confirm || "").trim().toUpperCase() === word;
}

// ---------- the three big events of the server clock ----------
const GOAL_INFO = {
  landmarks: { icon: "🗿", name: "Landmarks open" },
  relic: { icon: "🏆", name: "Relic Hunt" },
  aurora: { icon: "🌌", name: "Project Aurora" },
};
function clockDoneWrite(done) {
  setSetting("server_clock_done", JSON.stringify(done));
}
function clockDaysWrite(days) {
  setSetting("server_clock", JSON.stringify(days));
}
function goalStates() {
  const clock = serverClock();
  const done = clockDoneRead();
  const se = readSeason();
  const now = Date.now();
  const days = clockDays();
  return Object.keys(GOAL_INFO).map((key) => {
    const ev = clock.events[key];
    let status = "waiting";
    let text = key === "aurora" && now >= ev.at && se?.active && se.kind === "relic" ? "Waiting for the Relic Hunt to finish" : "waits for day " + ev.day;
    if (key === "landmarks") {
      if (landmarksOpen()) { status = "running"; text = "open: players can claim landmarks"; }
    } else if (se && se.kind === key && se.active) {
      status = "running";
      text = key === "relic"
        ? "hold " + se.count + " landmarks for " + hrTxt(se.hours) + (se.streak ? " · " + se.streak.name + " is on a streak" : "")
        : "countdown " + se.hours + "h" + (se.ignition ? " · " + se.ignition.name + " is igniting" : "");
    } else if (se && se.kind === key && se.winner) {
      status = "won";
      text = "won by " + se.winner.name;
    } else if (done[key]) {
      status = "ended";
      text = "ended";
    }
    return { key, icon: GOAL_INFO[key].icon, name: GOAL_INFO[key].name, day: days[key], at: ev.at, status, text, done: done[key] || 0 };
  });
}
function freeAllLandmarks(now) {
  for (const l of LANDMARKS) {
    const r = landmarkRow(l);
    for (const g of landmarkGarrison(l)) {
      db.prepare("UPDATE movements SET phase = 'back', arrive_at = ?, return_at = ?, next_at = ? WHERE id = ?").run(now, now + 60000, now + 60000, g.id);
    }
    const holder = r.holder_id ? loadColony(r.holder_id) : null;
    if (holder) {
      update(holder.state, tribeOf(holder.tribe), now);
      loseLandmark(l, holder);
      saveColony(holder.id, holder.state);
    } else loseLandmark(l, null);
  }
  seasonCache = null;
}
function stopSeasonKind(kind, now) {
  const se = readSeason();
  if (!se || se.kind !== kind) return false;
  const was = !!se.active;
  se.active = false;
  se.endedAt = now;
  se.streak = null;
  se.ignition = null;
  writeSeason(se);
  return was;
}
function dropSeasonKind(kind) {
  const se = readSeason();
  if (!se || se.kind !== kind) return;
  if (kind === "aurora") db.prepare("DELETE FROM aurora_charge WHERE season = ?").run(se.number || 0);
  se.active = false;
  se.winner = null;
  se.streak = null;
  se.ignition = null;
  writeSeason(se);
}
// Back to "waiting for its day". Returns a sentence for the owner.
function resetGoal(key, now) {
  if (key === "landmarks") {
    freeAllLandmarks(now);
    setLandmarksOpen(false);
    seasonCache = null;
  } else if (key === "relic") {
    dropSeasonKind("relic");
  } else if (key === "aurora") {
    dropSeasonKind("aurora");
  }
  const done = clockDoneRead();
  delete done[key];
  clockDoneWrite(done);
  // a day that already lies in the past would fire again at once: move it to tomorrow (and keep the order)
  const days = clockDays();
  const clock = serverClock();
  if (clock.events[key].at <= now) days[key] = clock.day + 1;
  if (days.relic < days.landmarks) days.relic = days.landmarks;
  if (days.aurora < days.relic) days.aurora = days.relic;
  clockDaysWrite(days);
  seasonCache = null;
  return GOAL_INFO[key].icon + " " + GOAL_INFO[key].name + " is reset and starts on server day " + days[key] + ".";
}
app.get("/api/admin/goals", requireOwner, (req, res) => {
  res.json({ now: Date.now(), clock: serverClock(), days: clockDays(), dayHours: Math.round((serverDayMs() / 3600000) * 10) / 10, goals: goalStates(), defaults: { count: RELIC_HUNT_COUNT, hours: relicHoursDefault(), auroraCharge: AURORA_CHARGE_HOURS, auroraHours: auroraDefaultHours() } });
});
app.post("/api/admin/goal", requireOwner, (req, res) => {
  const b = req.body || {};
  const key = String(b.key || "");
  const act = String(b.act || "");
  if (!GOAL_INFO[key]) return res.status(400).json({ error: "Unknown event" });
  const now = Date.now();
  const done = clockDoneRead();
  let msg = "";
  if (act === "start") {
    if (key === "landmarks") {
      setLandmarksOpen(true);
      addNews("🗿 The landmarks of Mars are open! Claim them for big bonuses.", now, "server", 24);
    } else if (key === "relic") {
      const err = startRelicHunt(b);
      if (err) return res.status(400).json({ error: err });
    } else {
      const se = readSeason();
      if (se && se.active && se.kind === "relic") stopSeasonKind("relic", now);
      const err = startAurora(b);
      if (err) return res.status(400).json({ error: err });
    }
    done[key] = now;
    clockDoneWrite(done);
    msg = GOAL_INFO[key].name + " started";
  } else if (act === "stop") {
    if (key === "landmarks") {
      setLandmarksOpen(false);
      addNews("🔒 The landmarks were sealed.", now, "server", 24);
    } else {
      if (!stopSeasonKind(key, now)) return res.status(400).json({ error: GOAL_INFO[key].name + " is not running" });
      addNews("⏹️ " + GOAL_INFO[key].name + " was stopped early.", now, "server", 24);
    }
    done[key] = done[key] || now;
    clockDoneWrite(done);
    msg = GOAL_INFO[key].name + " stopped";
  } else if (act === "reset") {
    msg = resetGoal(key, now);
  } else if (act === "day") {
    const days = clockDays();
    const v = Math.round(Number(b.day));
    if (!(v >= 1 && v <= 400)) return res.status(400).json({ error: "Day must be 1 to 400" });
    days[key] = v;
    if (days.relic < days.landmarks || days.aurora < days.relic) return res.status(400).json({ error: "Order must be: landmarks, then Relic Hunt, then Aurora" });
    clockDaysWrite(days);
    // a day in the future can fire again
    const c = serverClock();
    if (c.events[key].at > now) { delete done[key]; clockDoneWrite(done); }
    msg = GOAL_INFO[key].name + " moved to day " + v;
  } else return res.status(400).json({ error: "Unknown action" });
  seasonCache = null;
  adminLog(req, msg);
  res.json({ ok: true, message: msg });
});
// Restart the whole clock: day 1 is today, every event waits for its day again
app.post("/api/admin/clock/restart", requireOwner, (req, res) => {
  const now = Date.now();
  if (!confirmed(req, "RESTART")) return res.status(400).json({ error: "Type RESTART to confirm" });
  for (const key of ["aurora", "relic", "landmarks"]) resetGoal(key, now);
  clockRestartNow(now);
  clockDoneWrite({});
  const days = clockDays();
  addNews("🗓️ The server clock was restarted. Day 1 is today.", now, "server", 24);
  adminLog(req, "Server clock restarted (landmarks day " + days.landmarks + ", Relic Hunt " + days.relic + ", Aurora " + days.aurora + ")");
  res.json({ ok: true, message: "Clock restarted: day 1 is today" });
});

// ---------- the world: camps, meteors, the Landing Zone ----------
function campCensus() {
  const per = [0, 0, 0, 0].map(() => [0, 0, 0, 0]);
  let total = 0;
  for (let y = -MAP_RADIUS; y <= MAP_RADIUS; y++) {
    for (let x = -MAP_RADIUS; x <= MAP_RADIUS; x++) {
      if (terrainAt(x, y) !== "n") continue;
      per[quarterOf(x, y)][campTier(x, y)]++;
      total++;
    }
  }
  return { total, per };
}
function resetZone(now) {
  const z = zoneRow();
  for (const g of zoneGarrison()) {
    db.prepare("UPDATE movements SET phase = 'back', arrive_at = ?, return_at = ?, next_at = ? WHERE id = ?").run(now, now + 60000, now + 60000, g.id);
  }
  if (z.holder_id) {
    const holder = loadColony(z.holder_id);
    if (holder) {
      update(holder.state, tribeOf(holder.tribe), now);
      loseCrown(holder, now);
      saveColony(holder.id, holder.state);
    } else db.prepare("UPDATE zone SET holder_id = NULL, since = NULL, robots = ? WHERE id = 1").run(zoneRobots());
  } else db.prepare("UPDATE zone SET robots = ? WHERE id = 1").run(zoneRobots());
}
function clearMeteors() {
  db.prepare("DELETE FROM meteors").run();
}
app.get("/api/admin/world", requireOwner, (req, res) => {
  const now = Date.now();
  const z = zoneRow();
  res.json({
    seed: MAP_SEED,
    census: campCensus(),
    wounded: db.prepare("SELECT COUNT(*) AS n FROM camps").get().n,
    meteors: db.prepare("SELECT COUNT(*) AS n FROM meteors WHERE until > ?").get(now).n,
    zone: { holder: z.holder_id ? usernameOf(zoneHolderUser(z)) : null, robots: z.robots },
    landmarksOpen: landmarksOpen(),
    spacing: CAMP_SPACING,
    perQuarter: CAMPS_PER_QUARTER.reduce((n, v) => n + v, 0),
  });
});
app.post("/api/admin/world", requireOwner, (req, res) => {
  const b = req.body || {};
  const act = String(b.act || "");
  const now = Date.now();
  let msg = "";
  if (act === "camps-regrow") {
    db.prepare("DELETE FROM camps").run();
    msg = "All monster camps are back at full strength";
  } else if (act === "camps-reroll") {
    const seed = Math.round(Number(b.seed)) > 0 ? Math.round(Number(b.seed)) : null;
    const used = rerollCamps(seed);
    msg = "New camp layout rolled (seed " + used + ")";
  } else if (act === "meteors-clear") {
    clearMeteors();
    msg = "All meteor crates removed";
  } else if (act === "zone-reset") {
    resetZone(now);
    msg = "The Landing Zone is guarded by robots again";
  } else if (act === "map-reset") {
    if (!confirmed(req, "RESET MAP")) return res.status(400).json({ error: "Type RESET MAP to confirm" });
    freeAllLandmarks(now);
    resetZone(now);
    clearMeteors();
    const used = rerollCamps(null);
    msg = "Map reset: new camp layout (seed " + used + "), landmarks free, Landing Zone and meteors cleared";
    addNews("🗺️ The map was reset: new monster camps, free landmarks.", now, "server", 24);
  } else return res.status(400).json({ error: "Unknown action" });
  adminLog(req, msg);
  res.json({ ok: true, message: msg });
});

// ---------- Mars events (solar wind, meteors...) ----------
app.post("/api/admin/events/tools", requireOwner, (req, res) => {
  const act = String((req.body || {}).act || "");
  const now = Date.now();
  let msg = "";
  if (act === "end") {
    db.prepare("UPDATE events SET ends = ? WHERE ends > ?").run(now, now);
    clearMeteors();
    loadEvents();
    msg = "The running Mars event was ended";
  } else if (act === "reroll") {
    const next = now + (14 + Math.random() * 16) * 3600000;
    setSetting("events_next", String(Math.round(next)));
    msg = "The next Mars event comes in about " + Math.round((next - now) / 3600000) + " hours";
  } else if (act === "clear") {
    db.prepare("UPDATE events SET ends = ? WHERE ends > ?").run(now, now);
    db.prepare("DELETE FROM events").run();
    db.prepare("DELETE FROM meteor_claims").run();
    clearMeteors();
    loadEvents();
    msg = "Mars event history cleared";
  } else return res.status(400).json({ error: "Unknown action" });
  adminLog(req, msg);
  res.json({ ok: true, message: msg });
});

