addColumn("users", "roster", "TEXT NOT NULL DEFAULT ''");
// 1.0.396: Space-Cash amounts became 1200 times larger (income is now per second). Old balances, auction prices
// and the fractions kept for the wallet are converted once.
if (!db.prepare("SELECT 1 FROM settings WHERE key = 'cash_x1200'").get()) {
  db.exec("BEGIN");
  try {
    db.prepare("UPDATE users SET cash = cash * 1200").run();
    db.prepare("UPDATE auctions SET start_price = start_price * 1200, bid = bid * 1200 WHERE cash = 1").run();
    for (const u of db.prepare("SELECT id, roster FROM users WHERE roster != ''").all()) {
      let r = null;
      try { r = JSON.parse(u.roster); } catch (e) {}
      if (r && r.hunt && r.hunt.cashFrac) {
        const extra = Math.round(r.hunt.cashFrac * 1200);
        r.hunt.cashFrac = 0;
        db.prepare("UPDATE users SET cash = cash + ?, roster = ? WHERE id = ?").run(extra, JSON.stringify(r), u.id);
      }
    }
    db.prepare("INSERT INTO settings (key, value) VALUES ('cash_x1200', '1')").run();
    db.exec("COMMIT");
  } catch (e) { db.exec("ROLLBACK"); console.error("cash migration:", e.message); }
}
// 1.0.441: aliens have one siege unit. Every Spore Cannon becomes an Acid Slug (which now also hits buildings):
// at home, away, wounded, in training, in prisons and on the road. Research and upgrades carry over.
if (!db.prepare("SELECT 1 FROM settings WHERE key = 'alien_one_siege'").get()) {
  const mv = (o, from, to) => {
    if (!o || !o[from]) return;
    o[to] = (o[to] || 0) + o[from];
    delete o[from];
  };
  const FROM = "catapult", TO = "ram";
  db.exec("BEGIN");
  try {
    const alienCols = new Set();
    for (const c of db.prepare("SELECT id, tribe, state FROM colonies").all()) {
      if (c.tribe === "alien") alienCols.add(c.id);
      let s = null;
      try { s = JSON.parse(c.state); } catch (e) {}
      if (!s) continue;
      let touched = false;
      for (const p of s.prisoners || []) if (p.tribe === "alien" && p.t && p.t[FROM]) { mv(p.t, FROM, TO); touched = true; }
      if (c.tribe === "alien") {
        touched = true;
        mv(s.troops, FROM, TO); mv(s.away, FROM, TO); mv(s.wounded, FROM, TO); mv(s.reserve, FROM, TO);
        if (s.healJob) mv(s.healJob.troops, FROM, TO);
        for (const p of s.panic || []) mv(p.troops, FROM, TO);
        for (const b in s.training || {}) for (const o of s.training[b] || []) if (o.unit === FROM) o.unit = TO;
        if (s.research && s.research[FROM]) { s.research[TO] = true; delete s.research[FROM]; }
        if (s.upgrades && s.upgrades[FROM]) { s.upgrades[TO] = Math.max(s.upgrades[TO] || 0, s.upgrades[FROM]); delete s.upgrades[FROM]; }
        for (const jk of ["labJob", "smithJob"]) {
          const j = s[jk];
          if (j && j.unit === FROM) {
            for (const k in j.cost || {}) s.res[k] = (s.res[k] || 0) + j.cost[k]; // the cannon job is refunded
            delete s[jk];
          }
        }
      }
      if (touched) db.prepare("UPDATE colonies SET state = ? WHERE id = ?").run(JSON.stringify(s), c.id);
    }
    for (const m of db.prepare("SELECT id, attacker_id, troops FROM movements").all()) {
      if (!alienCols.has(m.attacker_id)) continue;
      let t = null;
      try { t = JSON.parse(m.troops); } catch (e) {}
      if (!t || !t[FROM]) continue;
      mv(t, FROM, TO);
      db.prepare("UPDATE movements SET troops = ? WHERE id = ?").run(JSON.stringify(t), m.id);
    }
    db.prepare("INSERT INTO settings (key, value) VALUES ('alien_one_siege', '1')").run();
    db.exec("COMMIT");
  } catch (e) { db.exec("ROLLBACK"); console.error("alien siege migration:", e.message); }
}
