// =====================================================================
//  🌍 ONE MAIN ACCOUNT FOR EVERY SERVER
//  The main server keeps the main accounts (name, password, email). Logging
//  in there opens the server selection; a game account (with its colony) is
//  only made on the server the player picks. Picking a server hands the
//  player over with a signed link that only that server accepts, only once
//  and only for ten minutes. Every server keeps its own colonies, speeds,
//  rounds and admin page.
//  HOP_SECRET   the same secret text on every server (needed for the others)
//  HUB_URL      only on connected servers: the address of the main server (the main hub leaves it empty)
// =====================================================================
const configuredHubUrl = (process.env.HUB_URL || process.env.HUB_UR || "").trim().replace(/\/+$/, "");
const ownServerUrl = process.env.PUBLIC_URL || SERVER_LIST.find((server) => server.id === THIS_SERVER)?.url || "";
function configuredOrigin(value) {
  try { return new URL(value).origin; } catch { return ""; }
}
const HUB_URL = configuredOrigin(configuredHubUrl) === configuredOrigin(ownServerUrl) && configuredOrigin(ownServerUrl)
  ? "" : configuredHubUrl;
const HOP_SECRET = process.env.HOP_SECRET || (HUB_URL ? "" : crypto.randomBytes(24).toString("hex")); // without it: only this server
const HOP_SHARED = !!process.env.HOP_SECRET;
const HOP_MINUTES = 10;
addColumn("users", "hub", "TEXT NOT NULL DEFAULT ''"); // the main account's name
db.exec(`
  CREATE TABLE IF NOT EXISTS accounts (
    id             INTEGER PRIMARY KEY AUTOINCREMENT,
    username       TEXT NOT NULL,
    pass_hash      TEXT NOT NULL,
    salt           TEXT NOT NULL,
    email          TEXT,
    norm_email     TEXT,
    email_verified INTEGER NOT NULL DEFAULT 0,
    banned         INTEGER NOT NULL DEFAULT 0,
    created_at     INTEGER NOT NULL
  );
  CREATE UNIQUE INDEX IF NOT EXISTS accounts_name ON accounts (username COLLATE NOCASE);
  CREATE TABLE IF NOT EXISTS acct_sessions (
    token      TEXT PRIMARY KEY,
    account_id INTEGER NOT NULL,
    created_at INTEGER NOT NULL
  );
`);
// players from before main accounts: their game account becomes a main account too
if (!HUB_URL && settingOf("accounts_made", "") !== "1") {
  for (const u of db.prepare("SELECT * FROM users WHERE bot = 0 AND hub = ''").all()) {
    if (db.prepare("SELECT 1 FROM accounts WHERE username = ? COLLATE NOCASE").get(u.username)) continue;
    db.prepare("INSERT INTO accounts (username, pass_hash, salt, email, norm_email, email_verified, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)").run(u.username, u.pass_hash, u.salt, u.email, u.norm_email, u.email_verified ? 1 : 0, u.created_at || Date.now());
    db.prepare("UPDATE users SET hub = ? WHERE id = ?").run(u.username, u.id);
  }
  setSetting("accounts_made", "1");
}
const OFFENSIVE_NAME_TERMS = ["anal", "asshole", "bastard", "bitch", "bullshit", "cunt", "damn", "dick", "fuck", "kurwa", "motherfucker", "nazi", "nigger", "piss", "porn", "shit", "slut", "whore"];
function offensiveName(name) {
  const normalized=String(name||"").normalize("NFKD").toLowerCase().replace(/[0@]/g,"o").replace(/[1!|]/g,"i").replace(/[3]/g,"e").replace(/[4@]/g,"a").replace(/[5$]/g,"s").replace(/[7]/g,"t").replace(/[^a-z]/g,"");
  return OFFENSIVE_NAME_TERMS.some(term=>normalized.includes(term.replace(/[^a-z]/g,"")));
}
function acctNameTaken(name) {
  return !!db.prepare("SELECT 1 FROM accounts WHERE username = ? COLLATE NOCASE").get(name) || !!db.prepare("SELECT 1 FROM users WHERE username = ? COLLATE NOCASE AND hub != ?").get(name, name);
}
function acctCookie(req, token, maxAge) {
  return `marsl_acct=${token}; HttpOnly; SameSite=Lax; Path=/; Max-Age=${maxAge}` + (req.secure ? "; Secure" : "");
}
function acctSession(req, res, accountId) {
  const token = crypto.randomBytes(32).toString("hex");
  db.prepare("INSERT INTO acct_sessions (token, account_id, created_at) VALUES (?, ?, ?)").run(token, accountId, Date.now());
  db.prepare("DELETE FROM acct_sessions WHERE account_id = ? AND token NOT IN (SELECT token FROM acct_sessions WHERE account_id = ? ORDER BY created_at DESC LIMIT ?)").run(accountId, accountId, SESSIONS_PER_PLAYER);
  res.setHeader("Set-Cookie", acctCookie(req, token, SESSION_DAYS * 86400));
}
function acctOf(req) {
  const token = readCookie(req, "marsl_acct");
  if (!token) return null;
  const a = db.prepare("SELECT accounts.*, acct_sessions.created_at AS s_at FROM acct_sessions JOIN accounts ON accounts.id = acct_sessions.account_id WHERE acct_sessions.token = ?").get(token);
  if (!a || a.banned || Date.now() - a.s_at > SESSION_DAYS * 86400000) return null;
  a.token = token;
  return a;
}
function requireAcct(req, res, next) {
  const a = acctOf(req);
  if (!a) return res.status(401).json({ error: "Please log in" });
  req.acct = a;
  next();
}
setInterval(() => db.prepare("DELETE FROM acct_sessions WHERE created_at < ?").run(Date.now() - SESSION_DAYS * 86400000), 3600000);

function acctRegister(req, res) {
  const body = req.body || {};
  if (registrationClosed()) return res.status(400).json({ error: "Registration is closed right now." });
  const username = String(body.username || "").trim();
  const password = String(body.password || "");
  const wait = Math.max(blocked("reg:" + req.ip, REGISTER_MAX), blocked("invite:" + req.ip, LOGIN_TRIES));
  if (wait) return res.status(429).json({ error: "Too many tries. Try again in " + wait + " min." });
  if (INVITE_CODE && String(body.invite || "").trim() !== INVITE_CODE) {
    hit("invite:" + req.ip, LOGIN_WINDOW);
    return res.status(400).json({ error: "Wrong invite code. Ask whoever runs this server!" });
  }
  if (!/^[A-Za-z0-9_]{3,20}$/.test(username)) return res.status(400).json({ error: "Name: 3-20 letters, numbers or _" });
  if (offensiveName(username)) return res.status(400).json({ error: "Please choose a name without offensive language" });
  const pwBad = passwordProblem(password, username);
  if (pwBad) return res.status(400).json({ error: pwBad });
  if (acctNameTaken(username)) return res.status(400).json({ error: "That name is already taken" });
  if (emailRequired()) return startSignup(req, res, { username, password, tribe: "", lang: body.lang });
  const salt = crypto.randomBytes(16).toString("hex");
  const r = db.prepare("INSERT INTO accounts (username, pass_hash, salt, created_at) VALUES (?, ?, ?, ?)").run(username, hashPassword(password, salt), salt, Date.now());
  hit("reg:" + req.ip, 3600000);
  acctSession(req, res, Number(r.lastInsertRowid));
  res.json({ ok: true });
}
function acctLogin(req, res) {
  const body = req.body || {};
  const username = String(body.username || "").trim();
  const password = String(body.password || "");
  const ipKey = "login-ip:" + req.ip;
  const nameKey = "login-name:" + username.toLowerCase();
  if (password.length > 200 || username.length > 40) return res.status(400).json({ error: "Wrong name or password" });
  const wait = Math.max(blocked(ipKey, LOGIN_TRIES), blocked(nameKey, LOGIN_TRIES_NAME));
  if (wait) return res.status(429).json({ error: "Too many wrong passwords. Try again in " + wait + " min." });
  const a = db.prepare("SELECT * FROM accounts WHERE username = ? COLLATE NOCASE").get(username);
  if (!a) hashPassword(password, "0000000000000000");
  if (!a || !passwordMatches(password, a.salt, a.pass_hash)) {
    hit(ipKey, LOGIN_WINDOW);
    hit(nameKey, LOGIN_WINDOW);
    return res.status(400).json({ error: "Wrong name or password" });
  }
  if (a.banned) return res.status(403).json({ error: "This account was blocked." });
  attempts.delete(nameKey);
  upgradePassword("accounts", a.id, password, a.pass_hash);
  acctSession(req, res, a.id);
  res.json({ ok: true });
}
// the main account: who is logged in (for the server selection)
// what the selection shows about every server: version, players, speed and whether this account plays there
function hopInfoHere(name) {
  const players = db.prepare("SELECT COUNT(*) AS n FROM users WHERE bot = 0").get().n;
  const online = db.prepare("SELECT COUNT(*) AS n FROM users WHERE bot = 0 AND last_seen > ?").get(Date.now() - 10 * 60000).n;
  const mine = db.prepare("SELECT MAX(last_seen) AS t, COUNT(*) AS n FROM users WHERE hub = ?").get(name);
  return { version: GAME_VERSION, players, online, speed: PRODUCTION_SPEED, has: !!(mine && mine.n), lastSeen: (mine && mine.t) || 0, startedAt: serverStartAt() };
}
const hopInfoCache = new Map();
async function hopInfoOf(s, name) {
  if (s.id === THIS_SERVER) return hopInfoHere(name);
  if (!s.url || !HOP_SECRET) return null;
  const key = s.id + ":" + name;
  const c = hopInfoCache.get(key);
  if (c && c.until > Date.now()) return c.v;
  let v = null;
  try {
    const token = hopSign({ u: name, to: s.id, info: true, exp: Date.now() + 60000, n: crypto.randomBytes(9).toString("hex") });
    const r = await fetch(s.url.replace(/\/+$/, "") + "/api/hop/info", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ t: token }), signal: AbortSignal.timeout(2500) });
    if (r.ok) v = await r.json();
  } catch (e) {}
  hopInfoCache.set(key, { v, until: Date.now() + (v ? 30000 : 8000) });
  return v;
}
app.post("/api/hop/info", (req, res) => {
  const o = hopRead((req.body || {}).t, true);
  if (!o || !o.info) return res.status(400).json({ error: "Not allowed" });
  res.json(hopInfoHere(o.u));
});
app.get("/api/acct", async (req, res) => {
  try {
    if (HUB_URL) return res.json({ ok: false, hub: HUB_URL });
    const a = acctOf(req);
    if (!a) return res.json({ ok: false });
    const info = {};
    await Promise.all(SERVER_LIST.map(async (s) => { try { const v = await hopInfoOf(s, a.username); if (v) info[s.id] = v; } catch (e) {} }));
    res.json({ ok: true, name: a.username, email: a.email_verified ? a.email : null, mailReady: mailReady(), here: !!(info[THIS_SERVER] && info[THIS_SERVER].has), info });
  } catch (e) { console.error("/api/acct:", e.message); res.status(500).json({ error: "Server error" }); }
});
app.post("/api/acct/logout", (req, res) => {
  const a = acctOf(req);
  if (a) db.prepare("DELETE FROM acct_sessions WHERE token = ?").run(a.token);
  const gt = readCookie(req, "marsl_session");
  if (gt) db.prepare("DELETE FROM sessions WHERE token = ?").run(gt);
  res.setHeader("Set-Cookie", [acctCookie(req, "", 0), sessionCookie(req, "", 0)]);
  res.json({ ok: true });
});
app.post("/api/acct/password", requireAcct, (req, res) => {
  const b = req.body || {};
  const key = "pw:a" + req.acct.id;
  const wait = blocked(key, LOGIN_TRIES);
  if (wait) return res.status(429).json({ error: "Too many wrong passwords. Try again in " + wait + " min." });
  if (!passwordMatches(String(b.old || ""), req.acct.salt, req.acct.pass_hash)) {
    hit(key, LOGIN_WINDOW);
    return res.status(400).json({ error: "Your current password is wrong" });
  }
  const pw = String(b.password || "");
  const pwBad = passwordProblem(pw, req.acct.username);
  if (pwBad) return res.status(400).json({ error: pwBad });
  const salt = crypto.randomBytes(16).toString("hex");
  db.prepare("UPDATE accounts SET pass_hash = ?, salt = ? WHERE id = ?").run(hashPassword(pw, salt), salt, req.acct.id);
  db.prepare("DELETE FROM acct_sessions WHERE account_id = ? AND token != ?").run(req.acct.id, req.acct.token);
  res.json({ ok: true });
});

const hopUsed = new Map();
function hopSign(o) {
  const p = Buffer.from(JSON.stringify(o)).toString("base64url");
  return p + "." + crypto.createHmac("sha256", HOP_SECRET).update(p).digest("base64url");
}
function hopRead(t, again) {
  if (!HOP_SECRET) return null;
  const parts = String(t || "").split(".");
  if (parts.length !== 2 || !parts[0] || !parts[1]) return null;
  const ok = crypto.createHmac("sha256", HOP_SECRET).update(parts[0]).digest("base64url");
  if (parts[1].length !== ok.length || !crypto.timingSafeEqual(Buffer.from(parts[1]), Buffer.from(ok))) return null;
  try {
    const o = JSON.parse(Buffer.from(parts[0], "base64url").toString());
    if (!o || o.exp < Date.now() || o.to !== THIS_SERVER || !o.u || !o.n || (!again && hopUsed.has(o.n))) return null;
    return o;
  } catch (e) {
    return null;
  }
}
setInterval(() => {
  const now = Date.now();
  for (const [n, exp] of hopUsed) if (exp < now) hopUsed.delete(n);
}, 600000);

// main server: the player picks a server (this one or another)
app.post("/api/hop", requireAcct, (req, res) => {
  if (HUB_URL) return res.status(400).json({ error: "Servers are picked on the main server." });
  const srv = SERVER_LIST.find((s) => s.id === String((req.body || {}).server || ""));
  const here = srv && srv.id === THIS_SERVER;
  if (!srv || (!here && !srv.url)) return res.status(400).json({ error: "Unknown server" });
  if (!here && !HOP_SHARED) return res.status(400).json({ error: "This server is not connected yet." });
  if (blocked("hop:" + req.acct.id, 30)) return res.status(429).json({ error: "Too many tries. Wait a moment." });
  hit("hop:" + req.acct.id, 600000);
  const token = hopSign({ u: req.acct.username, e: req.acct.email_verified ? req.acct.email : "", to: srv.id, exp: Date.now() + HOP_MINUTES * 60000, n: crypto.randomBytes(9).toString("hex") });
  res.json({ ok: true, url: (here ? "" : srv.url.replace(/\/+$/, "")) + "/?hop=" + token });
});

// every server: the link from the main server
app.post("/api/hop/enter", (req, res) => {
  const body = req.body || {};
  const o = hopRead(body.t);
  if (!o || o.erase) return res.status(400).json({ error: "This link is too old or was already used. Pick the server again." });
  const user = db.prepare("SELECT * FROM users WHERE hub = ?").get(o.u);
  if (user) {
    if (user.banned) return res.status(403).json({ blocked: true, name: user.username, error: "This account was blocked by the server owner." });
    hopUsed.set(o.n, o.exp);
    createSession(req, res, user.id);
    return res.json({ ok: true });
  }
  const tribe = String(body.tribe || "");
  if (!tribe) return res.json({ ok: true, need: "tribe", name: o.u });
  if (!TRIBES[tribe]) return res.status(400).json({ error: "Pick a tribe" });
  if (registrationClosed()) return res.status(400).json({ error: "Registration is closed on this server right now." });
  if (db.prepare("SELECT id FROM users WHERE username = ? COLLATE NOCASE").get(o.u)) return res.status(400).json({ error: "The name " + o.u + " is already used on this server." });
  const spot = findFreeSpot();
  if (!spot) return res.status(400).json({ error: "Mars is full! No free land left." });
  const salt = crypto.randomBytes(16).toString("hex");
  const mail = o.e && !db.prepare("SELECT 1 FROM users WHERE norm_email = ? AND email_verified = 1").get(normEmail(o.e)) ? o.e : null;
  const result = db
    .prepare("INSERT INTO users (username, pass_hash, salt, created_at, email, norm_email, email_verified, hub) VALUES (?, ?, ?, ?, ?, ?, ?, ?)")
    .run(o.u, hashPassword(crypto.randomBytes(24).toString("hex"), salt), salt, Date.now(), mail, mail ? normEmail(mail) : null, mail ? 1 : 0, o.u);
  const userId = Number(result.lastInsertRowid);
  createColony(userId, tribe, "New Colony", spot.x, spot.y);
  // an extra account on a device that already has another player starts without beginner protection
  const dev = deviceOf(req);
  const alt = dev && db.prepare("SELECT 1 FROM device_links d JOIN users u ON u.id = d.user_id WHERE d.device = ? AND u.id != ? AND u.bot = 0 AND u.multi_ok = 0 LIMIT 1").get(dev, userId);
  if (!alt) db.prepare("UPDATE users SET protected_until = ? WHERE id = ?").run(Date.now() + protectionHours() * 3600000, userId);
  hopUsed.set(o.n, o.exp);
  createSession(req, res, userId);
  res.json({ ok: true });
  setTimeout(botTick, 3000);
});


// =====================================================================
//  ♻️ RESPAWN  +  "🗑️" DELETING THE MAIN ACCOUNT
//  Respawn: the player stays (name, account, sessions) but every colony,
//  troop, hero, quest and alliance place on THIS server is removed and a new
//  colony is made. Deleting the main account removes the account and the
//  player on every server (the other servers are asked with a signed call).
// =====================================================================
db.exec("CREATE TABLE IF NOT EXISTS colony_deletions (user_id INTEGER PRIMARY KEY, due_at INTEGER NOT NULL, round_id INTEGER NOT NULL)");
function finishColonyDeletion(userId){
  const now = Date.now();
  const ids = colonyIdsOf(userId);
  if (ids.length) {
    const marks = ids.map(() => "?").join(",");
    // troops of others at these colonies walk home
    db.prepare(`UPDATE movements SET phase = 'back', arrive_at = ?, return_at = ?, next_at = ?
       WHERE target_kind = 'colony' AND target_id IN (${marks}) AND attacker_id NOT IN (${marks})`).run(now, now + 1000, now + 1000, ...ids, ...ids);
    db.prepare(`DELETE FROM movements WHERE attacker_id IN (${marks})`).run(...ids);
    const z = zoneRow();
    if (z.holder_id && ids.includes(z.holder_id)) db.prepare("UPDATE zone SET holder_id = NULL, since = NULL, robots = ? WHERE id = 1").run(zoneRobots());
    for (const l of LANDMARKS) {
      const r = landmarkRow(l);
      if (r.holder_id && ids.includes(r.holder_id)) loseLandmark(l, null);
    }
    for (const id of ids) db.prepare("DELETE FROM build_hands WHERE colony_id = ?").run(id);
    db.prepare(`DELETE FROM colonies WHERE id IN (${marks})`).run(...ids);
  }
  for (const t of ["reports", "stats", "badges", "alliance_invites", "crew_busy"]) {
    try { db.prepare(`DELETE FROM ${t} WHERE user_id = ?`).run(userId); } catch (e) {}
  }
  const ally = allianceOf(userId);
  db.prepare("DELETE FROM alliance_members WHERE user_id = ?").run(userId);
  if (ally) fixAlliance(ally.id);
  db.prepare("UPDATE users SET hero='', quests='{}', vac='{}', col_groups='{}', farm='', firstday='' WHERE id=?").run(userId);
  db.prepare("UPDATE sessions SET active_colony=NULL,sit_for=NULL WHERE user_id=? OR sit_for=?").run(userId,userId);
}
function processColonyDeletions(){
  for(const pending of db.prepare('SELECT * FROM colony_deletions WHERE due_at<=?').all(Date.now())){
    db.exec('BEGIN');
    try{if(pending.round_id===roundNumber())finishColonyDeletion(pending.user_id);db.prepare('DELETE FROM colony_deletions WHERE user_id=?').run(pending.user_id);db.exec('COMMIT');}
    catch(e){db.exec('ROLLBACK');console.error('Colony deletion failed',e.message);}
  }
}
setInterval(processColonyDeletions,1000);
app.post('/api/colonies/delete',requireLogin,(req,res)=>{
  if(req.sitterId)return res.status(403).json({error:'Use your own account.'});
  if(req.body&&req.body.cancel){db.prepare('DELETE FROM colony_deletions WHERE user_id=?').run(req.user.id);return res.json({ok:true});}
  if(!req.body||req.body.confirm!==req.user.username)return res.status(400).json({error:'Type your player name exactly to confirm.'});
  db.prepare('INSERT OR IGNORE INTO colony_deletions(user_id,due_at,round_id) VALUES(?,?,?)').run(req.user.id,Date.now()+48*3600000,roundNumber());
  res.json({ok:true});
});
function respawnPlayer(userId, tribe) {
  const user = db.prepare("SELECT id, username, bot FROM users WHERE id = ?").get(userId);
  if (!user || user.bot) return "Not possible";
  if (!TRIBES[tribe]) return "Pick a tribe";
  const spot = findFreeSpot();
  if (!spot) return "Mars is full! No free land left.";
  const now = Date.now();
  const ids = colonyIdsOf(userId);
  if (ids.length) {
    const marks = ids.map(() => "?").join(",");
    // troops of others at these colonies walk home
    db.prepare(`UPDATE movements SET phase = 'back', arrive_at = ?, return_at = ?, next_at = ?
       WHERE target_kind = 'colony' AND target_id IN (${marks}) AND attacker_id NOT IN (${marks})`).run(now, now + 1000, now + 1000, ...ids, ...ids);
    db.prepare(`DELETE FROM movements WHERE attacker_id IN (${marks})`).run(...ids);
    const z = zoneRow();
    if (z.holder_id && ids.includes(z.holder_id)) db.prepare("UPDATE zone SET holder_id = NULL, since = NULL, robots = ? WHERE id = 1").run(zoneRobots());
    for (const l of LANDMARKS) {
      const r = landmarkRow(l);
      if (r.holder_id && ids.includes(r.holder_id)) loseLandmark(l, null);
    }
    for (const id of ids) db.prepare("DELETE FROM build_hands WHERE colony_id = ?").run(id);
    db.prepare(`DELETE FROM colonies WHERE id IN (${marks})`).run(...ids);
  }
  for (const t of ["reports", "stats", "badges", "alliance_invites", "crew_busy"]) {
    try { db.prepare(`DELETE FROM ${t} WHERE user_id = ?`).run(userId); } catch (e) {}
  }
  const ally = allianceOf(userId);
  db.prepare("DELETE FROM alliance_members WHERE user_id = ?").run(userId);
  if (ally) fixAlliance(ally.id);
  createColony(userId, tribe, "New Colony", spot.x, spot.y);
  db.prepare("UPDATE users SET hero = '', quests = '{}', vac = '{}', col_groups = '{}', farm = '', main_moved_at = 0, tutorial = 0, firstday = '', protected_until = ? WHERE id = ?").run(now + protectionHours() * 3600000, userId);
  db.prepare("UPDATE sessions SET active_colony = NULL, sit_for = NULL WHERE user_id = ?").run(userId);
  return null;
}
app.post("/api/respawn", requireLogin, (req, res) => {
  if (blocked("respawn:" + req.user.id, 3)) return res.status(429).json({ error: "Too many respawns. Try again later." });
  const no = respawnPlayer(req.user.id, String((req.body || {}).tribe || ""));
  if (no) return res.status(400).json({ error: no });
  hit("respawn:" + req.user.id, 3600000);
  heroProdCache.clear();
  res.json({ ok: true });
  setTimeout(botTick, 3000);
});

// main server: the account and every player that belongs to it
async function acctEraseEverywhere(name) {
  const failed = [];
  for (const s of SERVER_LIST) {
    if (s.id === THIS_SERVER || !s.url) continue;
    try {
      const token = hopSign({ u: name, to: s.id, erase: true, exp: Date.now() + 120000, n: crypto.randomBytes(9).toString("hex") });
      const r = await fetch(s.url.replace(/\/+$/, "") + "/api/hop/erase", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ t: token }), signal: AbortSignal.timeout(6000) });
      if (!r.ok) failed.push(s.name);
    } catch (e) {
      failed.push(s.name);
    }
  }
  const u = db.prepare("SELECT id FROM users WHERE hub = ?").get(name);
  if (u) deleteUserCompletely(u.id);
  const a = db.prepare("SELECT id FROM accounts WHERE username = ? COLLATE NOCASE").get(name);
  if (a) {
    db.prepare("DELETE FROM acct_sessions WHERE account_id = ?").run(a.id);
    db.prepare("DELETE FROM accounts WHERE id = ?").run(a.id);
  }
  return failed;
}
app.post("/api/acct/delete", requireAcct, async (req, res) => {
  try {
  const key = "pw:a" + req.acct.id;
  const wait = blocked(key, LOGIN_TRIES);
  if (wait) return res.status(429).json({ error: "Too many wrong passwords. Try again in " + wait + " min." });
  if (!passwordMatches(String((req.body || {}).password || ""), req.acct.salt, req.acct.pass_hash)) {
    hit(key, LOGIN_WINDOW);
    return res.status(400).json({ error: "Your password is wrong" });
  }
  if (ownerNames().includes(req.acct.username.toLowerCase())) return res.status(400).json({ error: "Server owners can’t delete their account here. Remove the owner role first." });
  const failed = await acctEraseEverywhere(req.acct.username);
  res.setHeader("Set-Cookie", [acctCookie(req, "", 0), sessionCookie(req, "", 0)]);
  res.json({ ok: true, failed });
  } catch (e) { console.error("/api/acct/delete:", e.message); res.status(500).json({ error: "Server error" }); }
});
// other servers: the main server asks to remove a player
app.post("/api/hop/erase", (req, res) => {
  const o = hopRead((req.body || {}).t);
  if (!o || !o.erase) return res.status(400).json({ error: "Not allowed" });
  const u = db.prepare("SELECT id, username FROM users WHERE hub = ?").get(o.u);
  if (u) {
    if (ownerNames().includes(u.username.toLowerCase())) return res.status(400).json({ error: "owner" });
    hopUsed.set(o.n, o.exp);
    deleteUserCompletely(u.id);
  }
  res.json({ ok: true });
});

// =====================================================================
//  v164 - A LIVING WORLD
//  🌍 World pulse + battle smoke: how busy Mars is right now, and where the
//     fights of the last hour were (public, like smoke you can see from afar).
//  🎁 Daily supply: one free crate per server day, bigger every day in a row.
//  ✨ Tribe powers: one signature trick per tribe, once per server day.
//  🧭 Discover: neighbours and alliances that take new members.
// =====================================================================
db.exec(`
  CREATE TABLE IF NOT EXISTS world_fx (
    at   INTEGER NOT NULL,
    x    INTEGER NOT NULL,
    y    INTEGER NOT NULL,
    kind TEXT NOT NULL
  );
  CREATE INDEX IF NOT EXISTS world_fx_at ON world_fx (at);
`);
addColumn("users", "daily", "TEXT NOT NULL DEFAULT ''");
addColumn("alliances", "recruit", "INTEGER NOT NULL DEFAULT 0");
const FX_SHOW_MS = 60 * 60000; // smoke stays on the map for an hour
let fxCleanAt = 0;
function worldFx(x, y, kind, at) {
  if (x === null || x === undefined || y === null || y === undefined) return;
  try { db.prepare("INSERT INTO world_fx (at, x, y, kind) VALUES (?, ?, ?, ?)").run(at || Date.now(), x, y, kind); } catch (e) {}
  const now = Date.now();
  if (now - fxCleanAt > 600000) { fxCleanAt = now; db.prepare("DELETE FROM world_fx WHERE at < ?").run(now - 2 * 86400000); }
}
function worldFxIn(x1, x2, y1, y2, now) {
  // one mark per tile: the newest fight there
  return db.prepare("SELECT x, y, MAX(at) AS at, COUNT(*) AS n FROM world_fx WHERE kind = 'fight' AND at > ? AND x BETWEEN ? AND ? AND y BETWEEN ? AND ? GROUP BY x, y")
    .all(now - FX_SHOW_MS, x1, x2, y1, y2).map((r) => ({ x: r.x, y: r.y, ago: now - r.at, n: r.n }));
}
let pulseCache = { at: 0, v: null };
function worldPulse(now) {
  if (pulseCache.v && now - pulseCache.at < 30000) return pulseCache.v;
  const n = (kind, ms) => db.prepare("SELECT COUNT(*) AS n FROM world_fx WHERE kind = ? AND at > ?").get(kind, now - ms).n;
  pulseCache = {
    at: now,
    v: {
      online: db.prepare("SELECT COUNT(*) AS n FROM users WHERE bot = 0 AND last_seen > ?").get(now - 15 * 60000).n,
      fights: n("fight", 3600000),
      settled: n("settle", 86400000),
    },
  };
  return pulseCache.v;
}


// Account progression and cooperative objectives. Periods use real UTC days.
addColumn("users", "retention", "TEXT NOT NULL DEFAULT '{}'");
db.exec(`CREATE TABLE IF NOT EXISTS community_periods (id TEXT PRIMARY KEY, target INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS community_effort (period TEXT NOT NULL, user_id INTEGER NOT NULL, points INTEGER NOT NULL DEFAULT 0, camps INTEGER NOT NULL DEFAULT 0, claimed INTEGER NOT NULL DEFAULT 0, bonus INTEGER NOT NULL DEFAULT 0, contract INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(period,user_id));`);
function retentionOf(id) { const r=db.prepare("SELECT retention FROM users WHERE id=?").get(id); try{return JSON.parse(r.retention)||{};}catch(e){return {};} }
function saveRetention(id,r){db.prepare("UPDATE users SET retention=? WHERE id=?").run(JSON.stringify(r),id);}
function retentionReturn(id,last,now){
  if(!last || now-last<=2*86400000)return;
  const r=retentionOf(id);
  if(!r.comeback && (!r.lastComeback || now-r.lastComeback>=7*86400000)){
    r.comeback=now;r.lastComeback=now;r.welcomeGranted=true;r.bank=r.bank||{};
    const amount=250;for(const k of RESOURCES)r.bank[k]=(r.bank[k]||0)+amount;
    saveRetention(id,r);
  }
}
function communityPeriod(kind,now,existingOnly=false){
  const day=Math.floor(now/86400000), no=kind==='week'?Math.floor((day+3)/7):day;
  const id=roundNumber()+':camp-hunt-v206:'+kind+':'+no;
  let row=db.prepare("SELECT target FROM community_periods WHERE id=?").get(id);
  if(!row && existingOnly)return null;
  if(!row){
    const active=db.prepare("SELECT COUNT(*) n FROM users WHERE bot=0 AND banned=0 AND last_seen>?").get(now-7*86400000).n;
    const target=Math.max(kind==='week'?12:3,active*(kind==='week'?8:2));
    db.prepare("INSERT OR IGNORE INTO community_periods(id,target) VALUES(?,?)").run(id,target);
    row=db.prepare("SELECT target FROM community_periods WHERE id=?").get(id);
  }
  return {id,target:row.target,endsAt:(kind==='week'?(no+1)*7-3:day+1)*86400000};
}
function communityEffort(id,kind,now){const p=communityPeriod(kind,now);return db.prepare("SELECT * FROM community_effort WHERE period=? AND user_id=?").get(p.id,id)||{points:0,camps:0,claimed:0,bonus:0,contract:0};}
function communityAdd(id,camp,now){
  const u=db.prepare("SELECT bot FROM users WHERE id=?").get(id);if(!u||u.bot||!camp)return;
  for(const kind of ['day','week']){
    const p=communityPeriod(kind,now),cap=kind==='week'?15:3;
    db.prepare("INSERT INTO community_effort(period,user_id,points,camps) VALUES(?,?,1,?) ON CONFLICT(period,user_id) DO UPDATE SET points=MIN(?,points+1),camps=camps+excluded.camps").run(p.id,id,camp?1:0,cap);
  }
}
function tribeJourneyText(text,tribeKey){
  const t=tribeOf(tribeKey);
  const buildings={'Terraforming Hub':'hub','Hub':'hub','warehouse':'warehouse','barracks':'barracks','wall':'wall','hospital':'hospital','market':'market','HQ':'hq','food silo':'granary','lab':'lab','workshop':'workshop','hangar':'hangar'};
  const settler=Object.values(t.units).find(isSettler),scout=Object.values(t.units).find(isScout);
  text=text.replace(/\bsettlers\b/gi,settler?settler.name+' units':'settlers').replace(/\bscouts\b/gi,scout?scout.name+' units':'scouts');
  return text.replace(/\b(Terraforming Hub|food silo|warehouse|barracks|hospital|workshop|hangar|market|wall|HQ|Hub|lab)\b/g,word=>t.names[buildings[word]]?t.names[buildings[word]][0]:word);
}
function journeySteps(cols,tribeKey){
  const any=(t,n)=>cols.some(c=>levelOf(c.state,t)>=n);
  const army=cols.reduce((n,c)=>n+countUnits(c.state.troops)+countUnits(c.state.away),0);
  return [
    {title:'1 · Establish production',text:'Upgrade four resource fields and build a warehouse.',ready:cols.some(c=>c.state.fields.filter(f=>f.level>=1).length>=4)&&any('warehouse',1),reward:250,go:'resources'},
    {title:'2 · Form a squad',text:'Train 10 troops and build a barracks.',ready:army>=10&&any('barracks',1),reward:400,go:'troops'},
    {title:'3 · Scout and raid',text:'Scout a target and defeat a monster camp. Use the simulator before sending.',ready:cols.some(c=>c.state.qstats&&c.state.qstats.spied)&&cols.some(c=>c.state.qstats&&c.state.qstats.npc),reward:600,go:'map'},
    {title:'4 · Secure your home',text:'Build a wall and hospital; maintain at least 25 troops.',ready:any('wall',1)&&any('hospital',1)&&army>=25,reward:1000,go:'buildings'},
    {title:'5 · Prepare expansion',text:'Build a market and a Terraforming Hub. Find an alliance through the recruitment board.',ready:any('market',1)&&any('hub',1),reward:1800,go:'buildings'},
    {title:'6 · Fund your settlers',text:'Reach Terraforming Hub level 5 and maintain 50 troops. The reward helps pay for settlers.',ready:any('hub',5)&&army>=50,reward:4500,go:'buildings'},
    {title:'7 · A foothold on Mars',text:'Found your second colony and maintain a real army of at least 50 troops.',ready:cols.length>=2&&army>=50,reward:1800,go:'map'}
  ].map(step=>Object.assign({},step,{title:tribeJourneyText(step.title,tribeKey||(cols[0]&&cols[0].tribe)),text:tribeJourneyText(step.text,tribeKey||(cols[0]&&cols[0].tribe))}));
}
// Small per-colony cache: recommendations refresh after army changes or 30 seconds.
const practiceCache=new Map();
function practiceTargets(id,colony,now){
  const s=colony.state,tribe=tribeOf(colony.tribe),protectedNow=protectionOf(id,now).active;
  const sig=JSON.stringify([s.troops,s.upgrades,protectedNow]);const cached=practiceCache.get(colony.id);
  if(cached&&cached.sig===sig&&now-cached.at<30000)return cached.value;
  const fighters={};for(const k in s.troops){const u=tribe.units[k];if(u&&!isScout(u)&&!isSettler(u)&&s.troops[k]>0)fighters[k]=s.troops[k];}
  const power=attackOf(fighters,tribe,s.upgrades),hasArmy=power.g+power.a>0;
  const taken=new Set(db.prepare('SELECT x,y FROM colonies WHERE x BETWEEN ? AND ? AND y BETWEEN ? AND ?').all(colony.x-12,colony.x+12,colony.y-12,colony.y+12).map(c=>c.x+'|'+c.y));
  const nearby=Object.keys(CAMP_KIND_AT).map(k=>k.split('|').map(Number)).map(([x,y])=>({x,y,dist:distance(colony.x,colony.y,x,y)})).filter(c=>c.dist<=12&&!taken.has(c.x+'|'+c.y)).sort((a,b)=>a.dist-b.dist).slice(0,30);
  const camps=[];
  for(const t of nearby){
    if(db.prepare("SELECT 1 FROM movements WHERE target_kind='camp' AND target_x=? AND target_y=? AND phase='out' LIMIT 1").get(t.x,t.y))continue;
    const camp=campAt(t.x,t.y,now);if(!countUnits(camp.troops))continue;
    const def=campDefense(camp.troops),f=hasArmy?fight('attack',power,def,1,-LUCK):null;
    if(hasArmy&&(!f.attackerWins||f.atkFrac>0.15))continue;
    camps.push({kind:'camp',x:t.x,y:t.y,dist:Math.round(t.dist*10)/10,loss:f?Math.round(f.atkFrac*100):null,scout:!hasArmy,strength:def.g+def.a});
  }
  camps.sort((a,b)=>(hasArmy?a.loss-b.loss:a.strength-b.strength)||a.dist-b.dist);
  const targets=camps.slice(0,2).map(({strength,...t})=>t);
  // Colony strength is hidden: suggest scouting, and never imply protection is preserved.
  if(!protectedNow){
    const bots=db.prepare('SELECT c.id,c.x,c.y,c.name,c.state FROM colonies c JOIN users u ON u.id=c.user_id WHERE u.bot=1 AND u.protected_until<? AND c.x BETWEEN ? AND ? AND c.y BETWEEN ? AND ?').all(now,colony.x-16,colony.x+16,colony.y-16,colony.y+16)
      .map(c=>({...c,points:colonyPoints(fixState(JSON.parse(c.state))),dist:distance(colony.x,colony.y,c.x,c.y)})).filter(c=>c.dist<=16&&c.points<=Math.max(10,colonyPoints(s)*0.8)).sort((a,b)=>a.points-b.points||a.dist-b.dist);
    if(bots[0])targets.push({kind:'colony',name:bots[0].name,x:bots[0].x,y:bots[0].y,scout:true,points:bots[0].points});
  }
  const value={protected:protectedNow,hasArmy,targets};
  if(practiceCache.size>200)practiceCache.clear();practiceCache.set(colony.id,{sig,at:now,value});return value;
}
function journeyNext(cols,chapter,practice,tribeKey){
  const next=journeyNextRaw(cols,chapter,practice);
  if(next.go&&next.go.indexOf('b:')===0){
    const home=cols.find(c=>c.tribe===tribeKey)||cols[0];let target=next.go.slice(2),visited=new Set();
    while(home&&!visited.has(target)){visited.add(target);const req=tribeBuilding(home.tribe,target).requires||{};const missing=Object.keys(req).find(k=>levelOf(home.state,k)<req[k]);if(!missing)break;next.label='Upgrade '+tribeOf(home.tribe).names[missing][0]+' to level '+req[missing];target=missing;next.go='b:'+target;}
  }
  next.label=tribeJourneyText(next.label,tribeKey||(cols[0]&&cols[0].tribe));
  if(/scouts|settlers/.test(next.label)){
    const units=Object.values(tribeOf(tribeKey||(cols[0]&&cols[0].tribe)).units),scout=units.find(isScout),settler=units.find(isSettler);
    if(scout)next.label=next.label.replace(/scouts/g,scout.name);
    if(settler)next.label=next.label.replace(/settlers/g,settler.name);
  }
  return next;
}
function journeyNextRaw(cols,chapter,practice){
  const any=(t,n)=>cols.some(c=>levelOf(c.state,t)>=n),army=cols.reduce((n,c)=>n+countUnits(c.state.troops)+countUnits(c.state.away),0);
  if(chapter===0)return !any('warehouse',1)?{label:'Build a warehouse',go:'b:warehouse'}:{label:'Upgrade resource fields',go:'field::1'};
  if(chapter===1)return !any('barracks',1)?{label:'Build a barracks',go:'b:barracks'}:{label:'Train your first squad',go:'army'};
  if(chapter===2){
    const spied=cols.some(c=>c.state.qstats&&c.state.qstats.spied);
    const hasScout=cols.some(c=>Object.keys(tribeOf(c.tribe).units).some(k=>isScout(tribeOf(c.tribe).units[k])&&(c.state.troops[k]||0)>0));
    const knowsScout=cols.some(c=>Object.keys(tribeOf(c.tribe).units).some(k=>isScout(tribeOf(c.tribe).units[k])&&unitKnown(c.state,tribeOf(c.tribe),k)));
    if(!spied&&!hasScout)return {label:knowsScout?'Train scouts':'Research scouts',go:knowsScout?'army':'lab'};
    if(!practice.hasArmy&&spied)return {label:'Rebuild your raiding squad',go:'army'};
    const t=practice.targets.find(t=>t.kind==='camp');return t?{label:spied?'Simulate this camp first':'Scout this camp first',target:t}:{label:'Prepare your army / scouts',go:'army'};
  }
  if(chapter===3)return !any('wall',1)?{label:'Build a wall',go:'b:wall'}:!any('hospital',1)?{label:'Build a hospital',go:'b:hospital'}:{label:'Train 25 troops',go:'army'};
  if(chapter===4)return !any('market',1)?{label:'Build a market',go:'b:market'}:{label:'Build a Terraforming Hub',go:'b:hub'};
  if(chapter===5)return !any('hub',5)?{label:'Upgrade your Hub to level 5',go:'b:hub'}:{label:'Train an army of 50',go:'army'};
  if(chapter>=6&&!any('hub',SETTLER_HUB_LEVEL))return {label:'Upgrade your Hub to level '+SETTLER_HUB_LEVEL,go:'b:hub'};
  return army<50?{label:'Train an army of 50',go:'army'}:cols.length<2?{label:'Train settlers in your barracks',go:'army'}:{label:'Found another colony',view:'map'};
}
db.exec('CREATE TABLE IF NOT EXISTS journey_progress (user_id INTEGER PRIMARY KEY, chapter INTEGER NOT NULL, entered_at INTEGER NOT NULL, updated_at INTEGER NOT NULL)');
app.get('/api/admin/journey',requireOwner,(req,res)=>res.json({chapters:db.prepare('SELECT chapter,COUNT(*) players,SUM(CASE WHEN updated_at<? THEN 1 ELSE 0 END) stalled FROM journey_progress GROUP BY chapter').all(Date.now()-48*3600000)}));
function retentionView(id,colony,now){
  const r=retentionOf(id),cols=coloniesOf(id).map(c=>c.id===colony.id?colony:c),i=r.chapter||0;
  db.prepare('INSERT INTO journey_progress VALUES(?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET chapter=excluded.chapter,entered_at=excluded.entered_at,updated_at=excluded.updated_at WHERE journey_progress.chapter!=excluded.chapter').run(id,i,now,now);
  const periods=['day','week'].flatMap(kind=>{
    const current=communityPeriod(kind,now);
    const previous=communityPeriod(kind,current.endsAt-(kind==='week'?7:1)*86400000-1,true);
    return [current,previous].filter(Boolean).flatMap(p=>{
      const e=db.prepare("SELECT * FROM community_effort WHERE period=? AND user_id=?").get(p.id,id);
      const total=db.prepare("SELECT COALESCE(SUM(points),0) n FROM community_effort WHERE period=?").get(p.id).n;
      const points=e?.points||0, prior=p.id!==current.id;
      const claim=points>0&&!e.claimed,bonus=points>0&&total>=p.target&&!e.bonus;
      if(prior&&!claim&&!bonus)return [];
      return [{kind,action:prior?kind+'-previous':kind,prior,periodId:p.id,points,total,target:p.target,endsAt:p.endsAt,claim,bonus,amount:kind==='week'?400:100}];
    });
  });
  const e=communityEffort(id,'day',now),day=Math.floor(now/86400000),need=1;
  const practice=practiceTargets(id,colony,now);
  const trained=cols.reduce((n,c)=>n+(c.state.dailyTrained&&c.state.dailyTrained.day===day?c.state.dailyTrained.count:0),0);
  const weekly=communityEffort(id,'week',now),week=communityPeriod('week',now).id;
  const cq=claimedQuests(colony),armyLeft=colonyQuests(colony).filter(x=>questKind(x.id)==='army'&&!cq[x.id]).length,worldLeft=colonyQuests(colony).filter(x=>questKind(x.id)==='world'&&!cq[x.id]).length;
  return {board:boardView(id),armyLeft,worldLeft,allyGift:r.boardAlly?null:{ready:!!allianceOf(id),reward:BOARD_ALLY_GIFT},weeklyPersonal:{have:weekly.camps,need:7,claimed:r.personalWeek===week,reward:400},streak:r.streak||0,practice,next:journeyNext(cols,i,practice,colony.tribe),trainingTask:(i>=7||armyLeft===0)?{have:trained,need:50,claimed:r.trainingClaim===roundNumber()+':'+day,reward:200}:null,bank:RESOURCES.reduce((n,k)=>n+((r.bank||{})[k]||0),0),chapter:i<7?Object.assign({i},journeySteps(cols,colony.tribe)[i],{reward:journeySteps(cols,colony.tribe)[i].reward}):null,complete:i>=7,comeback:!!r.comeback,comebackAmount:250,allied:!!allianceOf(id),periods,contract:{have:e.camps,need,claimed:!!e.contract,reward:180}};
}
app.post('/api/retention',requireLogin,(req,res)=>{
  if(req.sitterId)return res.status(403).json({error:'Use your own account to collect rewards.'});
  db.exec("BEGIN");
  try { withColony(req,res,(s,tribe,colony)=>{
    const now=Date.now(),id=req.user.id,v=retentionView(id,colony,now),r=retentionOf(id),act=String((req.body||{}).action||'');let amount=0;
    if(act==='chapter'){
      if(!v.chapter||!v.chapter.ready)return 'Complete this chapter first.';
      amount=v.chapter.reward;r.chapter=(r.chapter||0)+1;saveRetention(id,r);
    }else if(act==='comeback'){
      if(!r.comeback)return 'No recovery package is waiting.';
      amount=r.welcomeGranted?0:v.comebackAmount;r.comeback=0;r.welcomeGranted=false;saveRetention(id,r);
    }else if(act==='training'){
      if(!v.trainingTask||v.trainingTask.claimed||v.trainingTask.have<v.trainingTask.need)return 'Complete today’s training task first.';
      r.trainingClaim=roundNumber()+':'+Math.floor(now/86400000);saveRetention(id,r);amount=v.trainingTask.reward;
    }else if(act==='personal-week'){
      if(v.weeklyPersonal.claimed||v.weeklyPersonal.have<7)return 'Win seven camp battles this week first.';
      r.personalWeek=communityPeriod('week',now).id;saveRetention(id,r);amount=v.weeklyPersonal.reward;
    }else if(act==='contract'){
      if(v.contract.claimed||v.contract.have<v.contract.need)return 'Finish today’s camp contract first.';
      const p=communityPeriod('day',now);db.prepare('UPDATE community_effort SET contract=1 WHERE period=? AND user_id=?').run(p.id,id);amount=v.contract.reward;
      const day=Math.floor(now/86400000),previous=r.streakDay;
      r.streak=previous===day-1?Math.min(7,(r.streak||0)+1):1;r.streakDay=day;
      amount+=Math.round(Math.min(5,r.streak)*20);saveRetention(id,r);
    }else if(act==='ally'){
      if(r.boardAlly)return 'Already collected.';
      if(!allianceOf(id))return 'Join or found an alliance first.';
      r.boardAlly=now;saveRetention(id,r);amount=v.allyGift.reward;
    }else if(act==='bank'){
      if(!v.bank)return 'No reserved supplies remain.';
    }else if(v.periods.some(p=>p.action===act)){
      const x=v.periods.find(p=>p.action===act);
      if(!x.claim&&!x.bonus)return 'No reward is ready.';
      amount=x.amount*((x.claim?1:0)+(x.bonus?2:0));
      db.prepare('UPDATE community_effort SET claimed=MAX(claimed,?),bonus=MAX(bonus,?) WHERE period=? AND user_id=?').run(x.claim?1:0,x.bonus?1:0,x.periodId,id);
    }else return 'Unknown action.';
    if(amount&&act!=='bank'&&act!=='comeback')boardDone(id);
    if(amount || act==='bank'||act==='comeback'){
      const stored=retentionOf(id);
      const reward={};
      for(const k of RESOURCES) reward[k]=((stored.bank||{})[k]||0)+amount;
      if (!questInventoryReward(id,reward)) throw new Error("Commander inventory unavailable");
      stored.bank={};
      saveRetention(id,stored);
    }
    return null;
  }); db.exec("COMMIT"); } catch(e) { db.exec("ROLLBACK"); throw e; }
});

// ---------- 🎁 daily supply ----------
const DAILY_BASE = 40; // of every resource on day 1 (it comes every 24 h now, it was 120 every 76 h at x1)
const DAILY_MAX_STREAK = 7;
function dailyOf(userId) {
  const r = db.prepare("SELECT daily FROM users WHERE id = ?").get(userId);
  try { return r && r.daily ? JSON.parse(r.daily) : {}; } catch (e) { return {}; }
}
function dailyAmount(streak) {
  return DAILY_BASE * Math.min(streak, DAILY_MAX_STREAK);
}
// milestone crates: day 3 of every week of streak is a silver crate, day 7 a gold one, each with a bonus on top
function dailyPos(streak) { return ((Math.max(1, streak) - 1) % DAILY_MAX_STREAK) + 1; }
function dailyBonus(streak) {
  const p = dailyPos(streak);
  return p === 3 ? DAILY_BASE * 2 : p === DAILY_MAX_STREAK ? DAILY_BASE * DAILY_MAX_STREAK : 0;
}
function dailyView(userId, now) {
  const D = dailyOf(userId);
  const today = serverDayNo(now);
  const can = D.day !== today;
  const next = can ? (D.day === today - 1 ? (D.streak || 0) + 1 : 1) : D.streak || 1;
  return { can, streak: can ? (D.day === today - 1 ? D.streak || 0 : 0) : D.streak || 1, nextStreak: next, amount: dailyAmount(next) + dailyBonus(next), bonus: dailyBonus(next), pos: dailyPos(next), max: DAILY_MAX_STREAK, milestones: { 3: DAILY_BASE * 2, [DAILY_MAX_STREAK]: DAILY_BASE * DAILY_MAX_STREAK }, nextAt: nextDayAt(now) };
}
app.post("/api/daily", requireLogin, (req, res) => {
  withColony(req, res, (s) => {
    const now = Date.now();
    const v = dailyView(req.user.id, now);
    if (!v.can) return "Today's supply is already collected. The next one comes at the start of the next server day.";
    refund(s, { wood: v.amount, stone: v.amount, metal: v.amount, food: v.amount });
    db.prepare("UPDATE users SET daily = ? WHERE id = ?").run(JSON.stringify({ day: serverDayNo(now), streak: Math.min(v.nextStreak, 99) }), req.user.id);
    req.extra = { daily: { amount: v.amount, streak: v.nextStreak, bonus: v.bonus } };
    return null;
  });
});

// ---------- ✨ tribe powers ----------
// v170: every tribe has two powers.
//  "⚙️" the home power: once per server day in every colony, with a choice
//  "⚔️" the war power: once per server day for the player (twice with a
//     level-15 commander), ticked in the send window for one attack or raid
const TRIBE_POWERS = {
  human: { icon: "🚨", name: "Lockdown", text: "For 30 minutes this colony either fights back harder (+15% defense) or locks the stores (bunkers hide 50% more). Pick one.", pick: "lock" },
  chicken: { icon: "📣", name: "Rally Cry", text: "The next attack or raid from this colony that lands within 8 hours gets +12% attack for its ground or its air troops. Pick one.", pick: "rally" },
  alien: { icon: "🧠", name: "Mind Link", text: "Shorten research and armory work, or construction, by up to 25%. Two base-speed hours total; respects the 50% free-help limit.", pick: "job" },
};
const WAR_POWERS = {
  human: { icon: "🛰️", name: "Orbital Recon", text: "Satellites watch the fight: you get a full spy report of the target right after it, troops, buildings and resources, even if nobody comes back.", colonyOnly: true },
  chicken: { icon: "🐔", name: "Stampede", text: "This army carries 35% more loot home, stacking with commander logistics." },
  alien: { icon: "🌀", name: "Cloak", text: "The defender sees the army coming, but can't read its pace or tell an attack from a raid.", colonyOnly: true },
};
const POWER_LOCK = { def: 0.15, hide: 0.5, ms: 30 * 60000 }; // lockdown lasts half an hour
const POWER_RALLY = { atk: 0.12, ms: 8 * 3600000 };
const POWER_HATCH = 0.2;
const POWER_MIND = 0.25;
const POWER_TIME_H = 2;
function powerTimeBudget() { return Math.max(1, Math.round(POWER_TIME_H * 3600000 / Math.max(1, BUILD_SPEED))); }
const WAR_LOOT = 0.35;
const WAR_TWICE_LEVEL = 15;
addColumn("users", "war_power", "TEXT NOT NULL DEFAULT ''");
addColumn("users", "power_at", "INTEGER NOT NULL DEFAULT 0"); // when the home power was last used: one per account, ready again one server day later (24 h on Classic)
addColumn("movements", "power", "TEXT");
// 🛰️ the satellite view right after the fight: like the best spy report
function orbitalRecon(att, def, defTribe, attacker, defender, supports, T) {
  const res = {};
  for (const r of RESOURCES) res[r] = Math.floor(def.state.res[r]);
  const d = defenseOf(def.state.troops, defTribe, def.state.upgrades);
  for (const s of supports) addDefense(d, defenseOf(s.troops, s.tribe, s.owner.state.upgrades));
  addDefense(d, militiaOf(def.state));
  const wall = 1 + (perkOf(def.tribe, "wall") * levelOf(def.state, "wall")) / 100;
  addReport(att.userId, T, "🛰️", tt("Orbital recon: {0}", shortColonyName(def.name)), {
    mission: "scout",
    success: true,
    recon: true,
    attacker: Object.assign({}, attacker, { units: [] }),
    defender,
    intel: {
      depth: 3,
      need: { troops: SPY_DEPTH_TROOPS, buildings: SPY_DEPTH_BUILDINGS },
      res,
      wall: levelOf(def.state, "wall"),
      bunker: bunkerOf(def.state),
      defG: Math.round(d.g * wall),
      defA: Math.round(d.a * wall),
      troops: unitList(def.state.troops, defTribe, null),
      support: supportList(supports),
      buildings: def.state.buildings.filter((b) => b.type && b.level > 0).map((b) => ({ type: b.type, icon: defTribe.names[b.type][1], name: defTribe.names[b.type][0], level: b.level })).sort((a, b) => b.level - a.level),
    },
    flavor: "The satellites saw everything. Right after the dust settled.",
  });
}
function hatchPlan(q, now) {
  let budget = powerTimeBudget();
  let count = Math.floor(q.reduce((n, o) => n + o.remaining, 0) * POWER_HATCH);
  count = Math.max(1, count);
  let total = 0;
  for (let i = 0; i < q.length && count > 0; i++) {
    const o = q[i], each = Math.max(1, o.eachMs);
    const first = i === 0 && o.nextAt ? Math.max(1, o.nextAt - now) : each;
    if (budget < first) break;
    const n = Math.min(count, o.remaining, 1 + Math.floor((budget - first) / each));
    budget -= first + (n - 1) * each;
    total += n; count -= n;
    if (n < o.remaining) break;
  }
  return total;
}
function mindCutMs(job, now, budget) {
  if (!job || !(job.finishAt > now)) return 0;
  return Math.max(0, Math.min(Math.floor((job.finishAt - now) * POWER_MIND), freeRoom(job, now), budget));
}
function trainersWaiting(s) {
  return ["barracks", "hangar", "workshop"].filter((b) => (s.training[b] || []).some((o) => o.remaining > 0));
}
function mindJobs(s, now) {
  const j = [];
  if ((s.labJob && s.labJob.finishAt > now) || (s.smithJob && s.smithJob.finishAt > now)) j.push("lab");
  if (s.queue.length && s.queue[0].finishAt > now) j.push("build");
  return j;
}
function tribePowerView(s, tribeKey, now) {
  const p = TRIBE_POWERS[tribeKey];
  if (!p) return null;
  const prow = s._uid ? db.prepare("SELECT power_at FROM users WHERE id = ?").get(s._uid) : null;
  const readyAt = prow && prow.power_at ? prow.power_at + serverDayMs() : 0;
  const used = now < readyAt; // a strict cooldown from the moment of use
  let why = null, options = null;
  let active = null;
  if (tribeKey === "human") {
    options = [{ key: "def" }, { key: "hide" }];
    if (s.lockdown && s.lockdown.until > now) active = { kind: s.lockdown.kind, until: s.lockdown.until };
  }
  if (tribeKey === "chicken") {
    options = [{ key: "ground" }, { key: "air" }];
    if (s.rally && s.rally.until > now) active = { kind: s.rally.kind, until: s.rally.until };
  }
  if (tribeKey === "alien") {
    options = mindJobs(s, now).map((k) => ({ key: k }));
    if (!options.length) why = "No research, upgrade or construction is running";
  }
  return { key: tribeKey, icon: p.icon, name: p.name, text: p.text, pick: p.pick, options, used, why, active, nextAt: readyAt, war: warPowerView(s._uid, tribeKey, now) };
}
function warPowerView(userId, tribeKey, now) {
  const w = WAR_POWERS[tribeKey];
  if (!w || !userId) return null;
  const row = db.prepare("SELECT war_power FROM users WHERE id = ?").get(userId);
  let st = {};
  try { st = row && row.war_power ? JSON.parse(row.war_power) : {}; } catch (e) {}
  const day = serverDayNo(now);
  const used = st.day === day ? st.used || 0 : 0;
  const h = heroReady ? heroOf(userId, now) : null;
  const max = h && h.level >= WAR_TWICE_LEVEL ? 2 : 1;
  return { key: tribeKey, icon: w.icon, name: w.name, text: w.text, colonyOnly: !!w.colonyOnly, left: Math.max(0, max - used), max, nextAt: nextDayAt(now) };
}
function useWarPower(userId, now) {
  const row = db.prepare("SELECT war_power FROM users WHERE id = ?").get(userId);
  let st = {};
  try { st = row && row.war_power ? JSON.parse(row.war_power) : {}; } catch (e) {}
  const day = serverDayNo(now);
  st = { day, used: (st.day === day ? st.used || 0 : 0) + 1 };
  db.prepare("UPDATE users SET war_power = ? WHERE id = ?").run(JSON.stringify(st), userId);
}
app.post("/api/tribe-power", requireLogin, (req, res) => {
  withColony(req, res, (s, tribe, colony) => {
    const now = Date.now();
    const v = tribePowerView(s, colony.tribe, now);
    if (!v) return "Your tribe has no power";
    if (v.used) return "Your home power is recharging. It works once per account, then needs a full day";
    if (v.why) return v.why;
    const pick = String((req.body || {}).pick || "");
    if (!v.options.some((o) => o.key === pick)) return "Pick what the power should do";
    let out = {};
    if (colony.tribe === "human") {
      s.lockdown = { kind: pick, until: now + POWER_LOCK.ms };
      out = { lock: pick, until: s.lockdown.until };
    } else if (colony.tribe === "chicken") {
      s.rally = { kind: pick, until: now + POWER_RALLY.ms };
      out = { rally: pick, until: s.rally.until };
    } else if (colony.tribe === "alien") {
      let budget = powerTimeBudget();
      const cut = (j) => { const ms = mindCutMs(j, now, budget); if (ms > 0) { cutJob(j, ms, now); budget -= ms; } };
      if (pick === "lab") { cut(s.labJob); cut(s.smithJob); }
      else {
        // the construction: the next jobs in the queue start sooner too
        const q0 = s.queue[0], before = q0.finishAt;
        cut(q0);
        const gain = before - q0.finishAt;
        for (let i = 1; i < s.queue.length; i++) if (s.queue[i].finishAt) s.queue[i].finishAt -= gain;
      }
      if (budget === powerTimeBudget()) return "These jobs have already reached their free-help limit";
      out = { cut: Math.round(POWER_MIND * 100), job: pick, savedMs: powerTimeBudget() - budget };
    }
    s.powerDay = serverDayNo(now);
    db.prepare("UPDATE users SET power_at = ? WHERE id = ?").run(now, req.user.id);
    req.extra = { power: Object.assign({ name: v.name, icon: v.icon }, out) };
    return null;
  });
});

// ---------- 🧭 discover: neighbours and open alliances ----------
app.get("/api/discover", requireLogin, (req, res) => {
  const now = Date.now();
  const me = loadColony(req.colonyId);
  const mine = allianceOf(req.user.id);
  const others = db
    .prepare("SELECT colonies.x, colonies.y, colonies.name, colonies.user_id, users.username, users.last_seen, users.bot FROM colonies JOIN users ON users.id = colonies.user_id WHERE colonies.user_id != ?")
    .all(req.user.id);
  // the nearest colony of every other real player
  const best = new Map();
  for (const c of others) {
    if (c.bot) continue;
    const d = distance(me.x, me.y, c.x, c.y);
    const b = best.get(c.user_id);
    if (!b || d < b.dist) best.set(c.user_id, { id: c.user_id, name: c.username, colony: c.name, x: c.x, y: c.y, dist: d, seen: c.last_seen });
  }
  const neighbours = [...best.values()].sort((a, b) => a.dist - b.dist).slice(0, 12).map((n) => {
    const a = allianceOf(n.id);
    return {
      name: n.name, colony: n.colony, x: n.x, y: n.y, dist: Math.round(n.dist * 10) / 10,
      points: playerPoints(n.id), tag: a ? a.tag : null, ally: !!(mine && a && a.id === mine.id),
      active: now - (n.seen || 0) < 86400000,
    };
  });
  const alliances = db.prepare("SELECT id, name, tag, about, recruit FROM alliances").all().map((a) => {
    const members = allianceMembers(a.id);
    let near = Infinity;
    for (const m of members) for (const c of coloniesOf(m.id)) near = Math.min(near, distance(me.x, me.y, c.x, c.y));
    return {
      id: a.id, name: a.name, tag: a.tag, about: String(a.about || "").slice(0, 140), recruit: !!a.recruit,
      members: members.length, max: ALLIANCE_MAX_MEMBERS, points: members.reduce((n, m) => n + playerPoints(m.id), 0),
      near: near === Infinity ? null : Math.round(near * 10) / 10, mine: !!(mine && mine.id === a.id),
      asked: !!db.prepare("SELECT 1 FROM messages WHERE from_id = ? AND subject = ? AND created_at > ?").get(req.user.id, "Wants to join [" + a.tag + "]", now - 86400000),
    };
  }).filter((a) => a.recruit || a.mine).sort((a, b) => (a.near === null) - (b.near === null) || a.near - b.near);
  // 🙋 colonists looking for an alliance (active in the last 3 days)
  const meRow = db.prepare("SELECT lfa, lfa_note FROM users WHERE id = ?").get(req.user.id);
  const seekers = db.prepare("SELECT id, username, lfa_note, last_seen FROM users WHERE lfa = 1 AND bot = 0 AND id != ? AND last_seen > ?").all(req.user.id, now - 3 * 86400000)
    .filter((u) => !allianceOf(u.id))
    .map((u) => {
      let near = Infinity, nx = null, ny = null;
      for (const c of coloniesOf(u.id)) { const d = distance(me.x, me.y, c.x, c.y); if (d < near) { near = d; nx = c.x; ny = c.y; } }
      return { name: u.username, note: u.lfa_note || "", points: playerPoints(u.id), dist: near === Infinity ? null : Math.round(near * 10) / 10, x: nx, y: ny, active: now - (u.last_seen || 0) < 86400000 };
    })
    .sort((a, b) => (a.dist === null) - (b.dist === null) || a.dist - b.dist)
    .slice(0, 12);
  res.json({ seekers, lfa: { on: !!(meRow && meRow.lfa), note: (meRow && meRow.lfa_note) || "" }, neighbours, alliances, inAlliance: !!mine, staff: !!(mine && ["leader", "officer"].includes(db.prepare("SELECT role FROM alliance_members WHERE user_id = ?").get(req.user.id).role)), recruit: mine ? !!db.prepare("SELECT recruit FROM alliances WHERE id = ?").get(mine.id).recruit : false });
});
// a player asks to join: every leader and officer gets a message with their details
app.post("/api/alliance/ask-join", requireLogin, (req, res) => {
  const id = parseInt((req.body || {}).id, 10);
  const now = Date.now();
  const a = db.prepare("SELECT id, name, tag, recruit FROM alliances WHERE id = ?").get(id);
  if (!a || !a.recruit) return res.status(400).json({ error: "That alliance isn't taking new members right now" });
  if (allianceOf(req.user.id)) return res.status(400).json({ error: "Leave your alliance first" });
  const subject = "Wants to join [" + a.tag + "]";
  if (db.prepare("SELECT 1 FROM messages WHERE from_id = ? AND subject = ? AND created_at > ?").get(req.user.id, subject, now - 86400000)) return res.status(400).json({ error: "You already asked today" });
  const me = loadColony(req.colonyId);
  const body = req.user.username + " would like to join " + a.name + ". " + playerPoints(req.user.id) + " points, main colony at (" + me.x + "|" + me.y + "). Invite them from your alliance page if you like.";
  const heads = db.prepare("SELECT user_id FROM alliance_members WHERE alliance_id = ? AND role IN ('leader', 'officer')").all(a.id);
  for (const h of heads) db.prepare("INSERT INTO messages (from_id, to_id, subject, body, created_at) VALUES (?, ?, ?, ?, ?)").run(req.user.id, h.user_id, subject, body, now);
  res.json({ ok: true });
});
app.post("/api/alliance/recruit", requireLogin, (req, res) => {
  const mine = allianceOf(req.user.id);
  if (!mine) return res.status(400).json({ error: "You are not in an alliance" });
  const role = db.prepare("SELECT role FROM alliance_members WHERE user_id = ?").get(req.user.id).role;
  if (role !== "leader" && role !== "officer") return res.status(400).json({ error: "Only the leader and officers can do that" });
  db.prepare("UPDATE alliances SET recruit = ? WHERE id = ?").run((req.body || {}).on ? 1 : 0, mine.id);
  res.json({ ok: true });
});

// =====================================================================
//  v169 - MORE LIFE ON MARS
//  🐫 Wandering traders: neutral caravans that stop near colonies for a
//     while and swap one resource for another 1:1 (no market cut, no
//     market needed), once per player and caravan.
//  "🎯" Recommended targets: the camps and sleepy NPC colonies around a
//     colony, with a quick "can your army win?" estimate.
//  🎉 Milestones: the first new colony and the first landmark pay a gift
//     and get a celebration.
// =====================================================================
db.exec(`
  CREATE TABLE IF NOT EXISTS npc_traders (
    id     INTEGER PRIMARY KEY AUTOINCREMENT,
    x      INTEGER NOT NULL,
    y      INTEGER NOT NULL,
    name   TEXT NOT NULL,
    want   TEXT NOT NULL,
    give   TEXT NOT NULL,
    amount INTEGER NOT NULL,
    until  INTEGER NOT NULL
  );
  CREATE TABLE IF NOT EXISTS npc_trader_uses (
    trader_id INTEGER NOT NULL,
    user_id   INTEGER NOT NULL,
    PRIMARY KEY (trader_id, user_id)
  );
`);
addColumn("users", "milestone", "TEXT NOT NULL DEFAULT ''");
const TRADER_RANGE = 12; // tiles: a colony this close can trade with the caravan
const TRADER_BASE = 1200; // the most it swaps
const TRADER_NAMES = ["Dusty Pete's Caravan", "The Rust Nomads", "Granny Ox & Sons", "Crater Bazaar", "The Wandering Spoon", "Sol & Moon Traders", "Old Meteorite Mo", "Tumbleweed Express"];
function traderLifeMs() { return Math.max(30 * 60000, Math.round(holdDayMs() / 3)); }
function traderAt(x, y, now) {
  return db.prepare("SELECT * FROM npc_traders WHERE x = ? AND y = ? AND until > ?").get(x, y, now || Date.now()) || null;
}
function tradersIn(x0, x1, y0, y1, userId, now) {
  return db.prepare("SELECT * FROM npc_traders WHERE x BETWEEN ? AND ? AND y BETWEEN ? AND ? AND until > ?").all(x0, x1, y0, y1, now).map((t) => ({
    id: t.id, x: t.x, y: t.y, name: t.name, want: t.want, give: t.give, amount: t.amount, until: t.until,
    used: !!db.prepare("SELECT 1 FROM npc_trader_uses WHERE trader_id = ? AND user_id = ?").get(t.id, userId),
  }));
}
// keep a few caravans on the map, near colonies of players who play
function traderTick() {
  const now = Date.now();
  db.prepare("DELETE FROM npc_traders WHERE until < ?").run(now - 3600000);
  db.prepare("DELETE FROM npc_trader_uses WHERE trader_id NOT IN (SELECT id FROM npc_traders)").run();
  const active = db.prepare("SELECT colonies.x, colonies.y FROM colonies JOIN users ON users.id = colonies.user_id WHERE users.bot = 0 AND users.last_seen > ?").all(now - 86400000);
  if (!active.length) return;
  const want = Math.max(2, Math.min(14, Math.round(active.length / 3)));
  let have = db.prepare("SELECT COUNT(*) AS n FROM npc_traders WHERE until > ?").get(now).n;
  for (let tries = 0; have < want && tries < 60; tries++) {
    const c = active[Math.floor(Math.random() * active.length)];
    const ang = Math.random() * Math.PI * 2, r = 3 + Math.random() * 6;
    const x = Math.round(c.x + Math.cos(ang) * r), y = Math.round(c.y + Math.sin(ang) * r);
    if (!canSettle(x, y) || landmarkAtXY(x, y) || meteorAt(x, y, now) || traderAt(x, y, now)) continue;
    if (db.prepare("SELECT 1 FROM colonies WHERE x = ? AND y = ?").get(x, y)) continue;
    const res = RESOURCES.slice().sort(() => Math.random() - 0.5);
    const amount = Math.round(TRADER_BASE * (0.6 + Math.random() * 0.8) / 10) * 10;
    db.prepare("INSERT INTO npc_traders (x, y, name, want, give, amount, until) VALUES (?, ?, ?, ?, ?, ?, ?)").run(x, y, TRADER_NAMES[Math.floor(Math.random() * TRADER_NAMES.length)], res[0], res[1], amount, Math.round(now + traderLifeMs() * (0.7 + Math.random() * 0.6)));
    have++;
  }
}
setTimeout(traderTick, 20000);
setInterval(traderTick, 5 * 60000);
// body { id, amount }: give `amount` of what they want, get the same of what they offer
app.post("/api/npc-trade", requireLogin, (req, res) => {
  withColony(req, res, (s, tribe, colony) => {
    const now = Date.now();
    const t = db.prepare("SELECT * FROM npc_traders WHERE id = ? AND until > ?").get(parseInt((req.body || {}).id, 10), now);
    if (!t) return "The caravan has moved on";
    if (db.prepare("SELECT 1 FROM npc_trader_uses WHERE trader_id = ? AND user_id = ?").get(t.id, req.user.id)) return "You already traded with this caravan";
    if (distance(colony.x, colony.y, t.x, t.y) > TRADER_RANGE) return "Too far away: the caravan only trades with colonies up to " + TRADER_RANGE + " tiles away";
    const n = Math.min(t.amount, Math.max(0, Math.floor(Number((req.body || {}).amount) || 0)));
    if (n <= 0) return "Pick an amount";
    if (s.res[t.want] < n) return "Not enough " + t.want;
    const room = Math.floor(capacities(s)[t.give] - s.res[t.give]);
    if (room < n) return "Not enough room for " + n + " " + t.give + " (" + Math.max(0, room) + " fit)";
    s.res[t.want] -= n;
    s.res[t.give] += n;
    db.prepare("INSERT INTO npc_trader_uses (trader_id, user_id) VALUES (?, ?)").run(t.id, req.user.id);
    req.extra = { npcTrade: { n, want: t.want, give: t.give } };
    return null;
  });
});

// ---------- "🎯" recommended targets ----------
const TARGET_RANGE = 12;
app.get("/api/targets", requireLogin, (req, res) => {
  const now = Date.now();
  processMovements(now);
  const me = loadColony(req.colonyId);
  const tribe = tribeOf(me.tribe);
  update(me.state, tribe, now);
  const home = me.state.troops;
  const fighters = {};
  for (const k in home) if (home[k] > 0 && tribe.units[k] && !isScout(tribe.units[k]) && !isSettler(tribe.units[k])) fighters[k] = home[k];
  const power = attackOf(fighters, tribe, me.state.upgrades);
  const hasArmy = power.g + power.a > 0;
  const verdict = (def, mult) => {
    if (!hasArmy) return { win: false, loss: 100, none: true };
    const f = fight("attack", power, def, mult || 1, 0);
    return { win: f.attackerWins, loss: Math.round(f.atkFrac * 100) };
  };
  const taken = new Set(db.prepare("SELECT x, y FROM colonies WHERE x BETWEEN ? AND ? AND y BETWEEN ? AND ?").all(me.x - TARGET_RANGE, me.x + TARGET_RANGE, me.y - TARGET_RANGE, me.y + TARGET_RANGE).map((c) => c.x + "|" + c.y));
  const camps = [];
  for (let x = me.x - TARGET_RANGE; x <= me.x + TARGET_RANGE; x++) for (let y = me.y - TARGET_RANGE; y <= me.y + TARGET_RANGE; y++) {
    if (terrainAt(x, y) !== "n" || taken.has(x + "|" + y)) continue;
    const d = distance(me.x, me.y, x, y);
    if (d > TARGET_RANGE) continue;
    const info = campInfo(x, y, now);
    const camp = campAt(x, y, now);
    camps.push({ kind: "camp", x, y, dist: Math.round(d * 10) / 10, name: info.name, icon: info.icon, tier: info.tier, empty: info.empty, units: info.units.map((u) => ({ icon: u.icon, count: u.count })), treasure: RESOURCES.reduce((n, r) => n + info.treasure[r], 0), est: info.empty ? { win: true, loss: 0 } : verdict(campDefense(camp.troops)) });
  }
  // sleepy NPC colonies: a spy report tells more, the points give an idea
  const bots = db.prepare("SELECT colonies.id, colonies.x, colonies.y, colonies.name, colonies.state, colonies.tribe FROM colonies JOIN users ON users.id = colonies.user_id WHERE users.bot = 1 AND colonies.x BETWEEN ? AND ? AND colonies.y BETWEEN ? AND ?")
    .all(me.x - TARGET_RANGE * 2, me.x + TARGET_RANGE * 2, me.y - TARGET_RANGE * 2, me.y + TARGET_RANGE * 2)
    .map((c) => {
      const st = fixState(JSON.parse(c.state));
      const rep = db.prepare("SELECT created_at, data FROM reports WHERE user_id = ? AND data LIKE ? ORDER BY id DESC LIMIT 1").get(req.user.id, '%"x":' + c.x + ',"y":' + c.y + '%');
      let last = null;
      if (rep) { try { const dd = JSON.parse(rep.data); last = { at: rep.created_at, win: dd.attackerWins !== undefined ? !!dd.attackerWins : null, loot: dd.loot ? RESOURCES.reduce((n, r) => n + (dd.loot[r] || 0), 0) : 0 }; } catch (e) {} }
      return { kind: "bot", x: c.x, y: c.y, dist: Math.round(distance(me.x, me.y, c.x, c.y) * 10) / 10, name: c.name, icon: tribeOf(c.tribe).home, points: colonyPoints(st), last };
    })
    .sort((a, b) => a.dist - b.dist).slice(0, 6);
  camps.sort((a, b) => (b.est.win - a.est.win) || a.tier - b.tier || a.dist - b.dist);
  res.json({ camps: camps.slice(0, 10), bots, hasArmy, protected: protectionOf(req.user.id, now).active });
});

